"""Apply exact release-9.0 build compatibility edits, without warning suppression."""
import hashlib
import json
from pathlib import Path
import sys

PATCHES = [{'path': 'CMakeLists.txt', 'sha256': '0b3df571dd23f948f625dfa55d6260a23c8df3b8663cc010434e97a748c4b0a1', 'patched_sha256': '6254d8b16b60efec1ca71c5b0f38c056965a91c1a92f022bc784c05a7333f9fd', 'content': '# \n# CMake configuration script for Elmer\n# \n# Authors:\n#  Sami Ilvonen, CSC - IT Center for Science, Ltd.\n#  Phil Weir, NUMA Engineering Services, Ltd.\n#  Mikko Byckling, CSC - IT Center for Science Ltd.\n#  Juhani Kataja, CSC - IT Center for Science Ltd.\n#\n# First public beta release 11th of October, 2013\n#\n\nif(APPLE)\n  # message("you need to have gcc-gfrotran installed using HomeBrew")\n  # set(CMAKE_C_COMPILER "/usr/bin/gcc")\n  # set(CMAKE_CXX_COMPILER "/usr/bin/g++")\n  if(NOT CMAKE_C_COMPILER)\n  set(CMAKE_C_COMPILER "/usr/local/bin/gcc-10")\n  endif()\n  if(NOT CMAKE_CXX_COMPILER)\n  set(CMAKE_CXX_COMPILER "/usr/local/bin/g++-10")\n  endif()\n  if(NOT CMAKE_Fortran_COMPILER)\n  set(CMAKE_Fortran_COMPILER "/usr/local/bin/gfortran")\n  endif()\n  # set(BLA_VENDOR "OpenBLAS")\n  # option(HUNTER_ENABLED "Enable Hunter package manager support" OFF)\n  # set (CMAKE_GENERATOR "Unix Makefiles" CACHE INTERNAL "" FORCE)\n  # set(CMAKE_TRY_COMPILE_TARGET_TYPE "STATIC_LIBRARY")\nendif()\n\n\n\n\n\nIF(NOT CMAKE_BUILD_TYPE)\n  SET(CMAKE_BUILD_TYPE "RelWithDebInfo" CACHE STRING "Build type (Release, Debug, RelWithDebugInfo, MinSizeRel)")\nENDIF()\n\nPROJECT(Elmer Fortran C CXX)\n\n# CMAKE_VERSION seems to require this in minimum\nCMAKE_MINIMUM_REQUIRED(VERSION 3.0.2)\n\nIF(APPLE)\n  SET(CMAKE_MACOSX_RPATH 1) \n    # on OSX FindOpenGL uses framework version of OpenGL, but we need X11 version\n    FIND_PATH(GLX_INCLUDE_DIR GL/glx.h\n      PATHS /opt/X11/include /usr/X11/include /usr/X11R6/include)\n    find_library(X11_GL_LIB GL\n      PATH /opt/X11/lib /usr/X11/lib /usr/X11R6/lib)\n# FIND_LIBRARY(OPENGL_gl_LIBRARY GL\n#        PATHS /opt/X11/lib /usr/X11/lib /usr/X11R6/lib)\n# FIND_LIBRARY(OPENGL_glu_LIBRARY GLU\n#        PATHS /opt/X11/lib /usr/X11/lib /usr/X11R6/lib)\n# LIST(APPEND LIBS ${OPENGL_gl_LIBRARY})\nIF(GLX_INCLUDE_DIR)\n  INCLUDE_DIRECTORIES(${GLX_INCLUDE_DIR})\nENDIF()\nENDIF()\n\n#shamelessly borrowed from FreeCAD project: https://github.com/FreeCAD/FreeCAD/blob/master/cMake/FreeCAD_Helpers/SetupPython.cmake\n# For building on OS X\nif(${CMAKE_SYSTEM_NAME} MATCHES "Darwin")\n\n  # If the user doesn\'t tell us which package manager they\'re using\n  if(NOT DEFINED MACPORTS_PREFIX AND NOT DEFINED HOMEBREW_PREFIX)\n\n    # Try to find MacPorts path\n    find_program(MACPORTS_EXECUTABLE port)\n    if(EXISTS ${MACPORTS_EXECUTABLE})\n      string(REPLACE "/bin/port" ""\n      MACPORTS_PREFIX ${MACPORTS_EXECUTABLE})\n      message(STATUS "Detected MacPorts install at ${MACPORTS_PREFIX}")\n    endif(EXISTS ${MACPORTS_EXECUTABLE})\n\n    # Try to find Homebrew path\n    find_program(HOMEBREW_EXECUTABLE brew)\n    if(EXISTS ${HOMEBREW_EXECUTABLE})\n      string(REPLACE "/bin/brew" ""\n      HOMEBREW_PREFIX ${HOMEBREW_EXECUTABLE})\n      message(STATUS "Detected Homebrew install at ${HOMEBREW_PREFIX}")\n    endif()\n\n  endif(NOT DEFINED MACPORTS_PREFIX AND NOT DEFINED HOMEBREW_PREFIX)\n\n  # In case someone tries to shoot themselves in the foot\n  if(DEFINED MACPORTS_PREFIX AND DEFINED HOMEBREW_PREFIX)\n    message(SEND_ERROR "Multiple package management systems detected - ")\n    message(SEND_ERROR "define either MACPORTS_PREFIX or HOMEBREW_PREFIX")\n\n  # No package manager\n  elseif(NOT DEFINED MACPORTS_PREFIX AND NOT DEFINED HOMEBREW_PREFIX)\n    message(SEND_ERROR "No package manager detected - install MacPorts or Homebrew")\n  endif()\nendif(${CMAKE_SYSTEM_NAME} MATCHES "Darwin")\n\n\nSET(CMAKE_MODULE_PATH "${PROJECT_SOURCE_DIR}/cmake/Modules" ${CMAKE_ROOT}/Modules)\n\nSET(CMAKE_Fortran_MODULE_DIRECTORY\n  ${PROJECT_BINARY_DIR}/fmodules CACHE PATH "Directory for Fortran modules")\n\n# Defaults to cache variables\nSET(WITH_MPI TRUE CACHE BOOL "Use MPI parallelization")\nSET(MPI_TEST_MAXPROC 8 CACHE STRING "Maximum number of tasks used in parallel tests")\nSET(MPI_TEST_MINPROC 1 CACHE STRING "Minimum number of tasks used in parallel tests")\nSET(WITH_OpenMP FALSE CACHE BOOL "Use OpenMP thread and SIMD (if available) parallelization")\nSET(WITH_MKL FALSE CACHE BOOL "Use Intel Math Kernel library")\nSET(WITH_Mumps FALSE CACHE BOOL "Use Mumps sparse direct solver")\nSET(WITH_Hypre FALSE CACHE BOOL "Use Hypre linear algebra library")\nSET(WITH_ELMERGUI FALSE CACHE BOOL "Include ElmerGUI")\nSET(WITH_ElmerIce FALSE CACHE BOOL "Include ElmerIce")\nSET(WITH_ELMERGUITESTER FALSE CACHE BOOL "Include ElmerGUI tester")\nSET(WITH_ELMERGUILOGGER FALSE CACHE BOOL "Include ElmerGUI logger")\nSET(ELMER_INSTALL_LIB_DIR "lib/elmersolver" CACHE PATH "Location of elmer shared libraries relative to prefix.")\nSET(WITH_Trilinos FALSE CACHE BOOL "Use Trilinos")\nSET(WITH_FETI4I FALSE CACHE BOOL "Use FETI4I")\nSET(WITH_ELMERPOST FALSE CACHE BOOL "Include ElmerPost (DEPRECATED)")\nSET(WITH_CONTRIB FALSE CACHE BOOL "Include contributed solvers")\n\nSET(WITH_LUA FALSE CACHE BOOL "Include LUA extensions.")\n\nSET(WITH_Zoltan FALSE CACHE BOOL "Link in Zoltan mesh repartitioning library.")\n\n# Let user select if the contiguous attribute is used or not\nSET(USE_CONTIGUOUS FALSE CACHE BOOL "Use contiguous attribute")\n\nMARK_AS_ADVANCED(WITH_ELMERPOST)\n\n# if("${CMAKE_VERSION}" VERSION_GREATER 2.8.12)\n#   CMAKE_POLICY(SET CMP0022 OLD)\n# ENDIF()\n\nMARK_AS_ADVANCED(ELMER_INSTALL_LIB_DIR)\n\nENABLE_TESTING()\n\nSET(ELMER_FEM_MAJOR_VERSION 9)\nSET(ELMER_FEM_MINOR_VERSION 0)\n\nSET(ELMER_FEM_VERSION\n  ${ELMER_FEM_MAJOR_VERSION}.${ELMER_FEM_MINOR_VERSION})\n\nIF(NOT(ELMER_FEM_REVISION))\n  SET(RESET_ELMER_REVISION TRUE CACHE BOOL "")\n  MARK_AS_ADVANCED(RESET_ELMER_REVISION)\nENDIF()\n\nIF(RESET_ELMER_REVISION)\n  execute_process(\n    COMMAND "git" "--no-pager" "log" "-1" "--pretty=format:%h"\n    WORKING_DIRECTORY ${PROJECT_SOURCE_DIR}\n    OUTPUT_VARIABLE ELMER_FEM_REVISION_\n    RESULT_VARIABLE RUN_RETURN_VALUE)\n  IF(RUN_RETURN_VALUE EQUAL 0)\n    SET(ELMER_FEM_REVISION ${ELMER_FEM_REVISION_} CACHE STRING "" FORCE)\n    MARK_AS_ADVANCED(ELMER_FEM_REVISION)\n  ENDIF()\nENDIF()\n    \nSET(VERSION ${ELMER_FEM_VERSION})\nSET(REVISION ${ELMER_FEM_REVISION})\nSET(CMAKE_POSITION_INDEPENDENT_CODE TRUE)\nSTRING(TIMESTAMP ELMER_FEM_COMPILATIONDATE "%Y-%m-%d")\nSET(COMPILATIONDATE ${ELMER_FEM_COMPILATIONDATE})\n\n# Check that the gfortran version is >= 4.8\nIF(${CMAKE_Fortran_COMPILER_ID} MATCHES "GNU")\n  INCLUDE(testGFortranVersion)\n  IF(NOT CMAKE_Fortran_COMPILER_GNU_VERSION_OK)\n    MESSAGE(FATAL_ERROR "GNU Fortran version is too old, should be at least 4.8")\n  ENDIF()\nENDIF()\n\nIF(WITH_LUA)\n  IF(NOT(${USE_SYSTEM_LUA}))\n    ADD_SUBDIRECTORY(${CMAKE_CURRENT_SOURCE_DIR}/contrib/lua-5.1.5/)\n    set(LUA_LIBRARIES luaelmer CACHE STRING "")\n    set(LUA_INCLUDE_DIR ${PROJECT_SOURCE_DIR}/contrib/lua-5.1.5/src CACHE STRING "")\n  ELSE()\n    FIND_PACKAGE(Lua51 REQUIRED)\n  ENDIF()\n  SET(HAVE_LUA TRUE)\n  MARK_AS_ADVANCED(HAVE_LUA)\nENDIF()\n\nIF(WITH_OpenMP)\n  # Advanced properties\n  MARK_AS_ADVANCED(\n    OpenMP_C_FLAGS\n    OpenMP_Fortran_FLAGS\n    OpenMP_CXX_FLAGS\n    )\n\n  # Add OpenMP flags to compilation flags\n  # if(APPLE)\n  #   if(CMAKE_C_COMPILER_ID STREQUAL "GNU")\n  #     set(OpenMP_C "${CMAKE_C_COMPILER}")\n  #     set(OpenMP_C_FLAGS "-fopenmp=libomp -Wno-unused-command-line-argument")\n  #     set(OpenMP_C_LIB_NAMES "libomp" "libgomp" "libiomp5")\n  #     set(OpenMP_libomp_LIBRARY ${OpenMP_C_LIB_NAMES})\n  #     set(OpenMP_libgomp_LIBRARY ${OpenMP_C_LIB_NAMES})\n  #     set(OpenMP_libiomp5_LIBRARY ${OpenMP_C_LIB_NAMES})\n  #   endif()\n  #   if(CMAKE_C_COMPILER_ID STREQUAL "GNU")\n  #     set(OpenMP_CXX "${CMAKE_CXX_COMPILER}")\n  #     set(OpenMP_CXX_FLAGS "-fopenmp=libomp -Wno-unused-command-line-argument")\n  #     set(OpenMP_CXX_LIB_NAMES "libomp" "libgomp" "libiomp5")\n  #     set(OpenMP_libomp_LIBRARY ${OpenMP_CXX_LIB_NAMES})\n  #     set(OpenMP_libgomp_LIBRARY ${OpenMP_CXX_LIB_NAMES})\n  #     set(OpenMP_libiomp5_LIBRARY ${OpenMP_CXX_LIB_NAMES})\n  #   endif()\n  # else()\n    SET(CMAKE_C_FLAGS "${CMAKE_C_FLAGS} ${OpenMP_C_FLAGS}")\n    SET(CMAKE_Fortran_FLAGS "${CMAKE_Fortran_FLAGS} ${OpenMP_Fortran_FLAGS}")\n    SET(CMAKE_CXX_FLAGS "${CMAKE_CXX_FLAGS} ${OpenMP_CXX_FLAGS}")\n  # endif()\n\n  FIND_PACKAGE(OpenMP REQUIRED)\n  \n  # Test compiler support for OpenMP 4.0 features used\n  INCLUDE(testOpenMP40)\n  IF(CMAKE_Fortran_COMPILER_SUPPORTS_OPENMP40)\n    SET(HAVE_OPENMP40 TRUE)\n    MARK_AS_ADVANCED(HAVE_OPENMP40)\n    # Test compiler support for advanced OpenMP 4.5 features used\n    INCLUDE(testOpenMP45)\n    IF(CMAKE_Fortran_COMPILER_SUPPORTS_OPENMP45)\n      SET(HAVE_OPENMP45 TRUE)\n      MARK_AS_ADVANCED(HAVE_OPENMP45)\n    ENDIF()\n  ENDIF()\nENDIF()\n\n# Get rid of the annoying rank mismatch warning\nIF("${CMAKE_Fortran_COMPILER_ID}" MATCHES "GNU")\n  IF(CMAKE_CXX_COMPILER_VERSION VERSION_GREATER 9.9)\n    SET(CMAKE_Fortran_FLAGS "${CMAKE_Fortran_FLAGS} -fallow-argument-mismatch")\n#    SET(CMAKE_Fortran_FLAGS "${CMAKE_Fortran_FLAGS} -std=legacy")\n  ENDIF()\nENDIF()\n  \n\nIF(WITH_MPI)\n  # Advanced properties\n  MARK_AS_ADVANCED(\n    MPI_EXTRA_LIBRARY\n    MPI_LIBRARY\n    )\n\n  FIND_PACKAGE(MPI REQUIRED)\n  # Workaround if MPI is found but MPI_FOUND is not set (windows+msmpi+findmpi)\n  SET(MPI_FOUND TRUE CACHE BOOL "")\n  MARK_AS_ADVANCED(MPI_FOUND)\n  INCLUDE_DIRECTORIES(${MPI_Fortran_INCLUDE_PATH})\n  # MPI libraries may be needed for testing\n  SET(CMAKE_C_REQUIRED_LIBRARIES ${MPI_C_LIBRARIES})\n  SET(CMAKE_CXX_REQUIRED_LIBRARIES ${MPI_CXX_LIBRARIES})\n  SET(CMAKE_Fortran_REQUIRED_LIBRARIES ${MPI_Fortran_LIBRARIES})\nENDIF(WITH_MPI)\n\n# if(APPLE)\n#   # message(STATUS "Trying to find Accelerate library")\n#   # find_library(BLAS_LIBRARIES Accelerate HINTS /System/Library/Frameworks/Accelerate.framework)\n#   # MARK_AS_ADVANCED(BLAS_LIBRARIES)\n#   # set(BLAS_LINKER_FLAGS "${CMAKE_LINKER_FLAGS} -framework accelerate")\n#   # find_path(LAPACK_INCLUDE_DIRS\n#   #   NAMES clapack.h\n#   #   PATHS ${BLAS_INCLUDE_DIRS}\n#   #   NO_DEFAULT_PATH\n#   # )\n#   # set(LAPACK_HEADER ${LAPACK_INCLUDE_DIRS}/clapack.h)\n#   # set(LAPACK_SUFFIX "_")\n#   # set(LAPACK_PREFIX)\n\n#   # message(STATUS "Using Accelerate framework on macOS")\n#   message("using the local blas library")\n#   # option(BLAS_VERBOSE "Print some additional information during BLAS libraries detection" ON)\n#   set(BLAS_DIR "./mathlibs/src/blas/")\n# set(BLA_VENDOR "Generic")\n\n  # set(ACCELERATE_LIBS "-framework Accelerate")\n  # BLAS_Accelerate_LIBRARY:FILEPATH=/System/Library/Frameworks/Accelerate.framework\n\n\n# else()\n  IF(WITH_MKL)\n    # Find MKL\n    FIND_PACKAGE(MKL REQUIRED)\n    SET(HAVE_MKL TRUE)\n    MARK_AS_ADVANCED(HAVE_MKL)\n    # Set BLAS and LAPACK to point to MKL\n    SET(BLAS_LIBRARIES ${MKL_BLAS_LIBRARIES} CACHE FILEPATH "")\n    SET(LAPACK_LIBRARIES ${MKL_LAPACK_LIBRARIES} CACHE FILEPATH "")\n    IF(MKL_SCALAPACK_LIBRARIES_FOUND)\n      SET(SCALAPACK_LIBRARIES ${MKL_SCALAPACK_LIBRARIES})\n      # Versions >11.1 of MKL include Cluster PARDISO direct solver\n      IF(MKL_CPARDISO_FOUND)\n        SET(HAVE_CPARDISO TRUE)\n        MARK_AS_ADVANCED(HAVE_CPARDISO)\n      ENDIF()\n    ENDIF()\n    INCLUDE_DIRECTORIES(${MKL_INCLUDE_DIR})\n    SET(CMAKE_Fortran_FLAGS "${CMAKE_Fortran_FLAGS} ${MKL_Fortran_FLAGS}")\n  ELSE()\n    IF (NOT BLAS_LIBRARIES OR NOT LAPACK_LIBRARIES)\n      # If BLAS/LAPACK not explicitly set, attempt to find MKL BLAS/LAPACK\n      FIND_PACKAGE(MKL QUIET)\n      IF (MKL_BLAS_LIBRARIES_FOUND AND MKL_LAPACK_LIBRARIES_FOUND)\n        # Set BLAS and LAPACK to point to MKL, in order to work around\n        # CMake FindBLAS finding wrong core library for GNU Fortran\n        SET(BLAS_LIBRARIES ${MKL_BLAS_LIBRARIES} CACHE FILEPATH "")\n        SET(LAPACK_LIBRARIES ${MKL_LAPACK_LIBRARIES} CACHE FILEPATH "")\n        INCLUDE_DIRECTORIES(${MKL_INCLUDE_DIR})\n        SET(CMAKE_Fortran_FLAGS "${CMAKE_Fortran_FLAGS} ${MKL_Fortran_FLAGS}")\n      ENDIF()\n    ENDIF()\n  ENDIF()\n# endif(APPLE)\n\n# MARK_AS_ADVANCED(WITH_Trilinos)\nIF(WITH_Trilinos)\n  FIND_PACKAGE(ML REQUIRED PATHS ${TRILINOS_PATH}/lib/cmake/ML ${TRILINOS_PATH}) \n  FIND_PACKAGE(Trilinos REQUIRED PATHS ${TRILINOS_PATH}/lib/cmake/Trilinos ${TRILINOS_PATH})\n  FIND_PACKAGE(Belos REQUIRED PATHS ${TRILINOS_PATH}/lib/cmake/Belos ${TRILINOS_PATH})\n  IF(ML_DIR)\n    ADD_DEFINITIONS(-DHAVE_TRILINOS)\n  ENDIF()\nENDIF()\n\nIF(WITH_Zoltan)\n  # ZOLTAN Remeshing\n  MESSAGE(STATUS "------------------------------------------------")\n\n  SET(USE_SYSTEM_ZOLTAN FALSE CACHE BOOL "Use system Zoltan library")\n  IF(NOT ${USE_SYSTEM_ZOLTAN})\n    MESSAGE(STATUS "Building Zoltan mesh repartitioner")\n    ADD_SUBDIRECTORY(contrib/Zoltan_v3.83)\n    SET(HAVE_ZOLTAN TRUE CACHE BOOL "Has Zoltan tools for mesh (re)partitioning" ) \n    MARK_AS_ADVANCED(HAVE_ZOLTAN)\n    MESSAGE(STATUS "  Zoltan_LIB:      " "${ZOLTAN_LIBRARY}")\n    MESSAGE(STATUS "------------------------------------------------")\n  ELSE()\n    FIND_PACKAGE(Zoltan)\n\n    IF(ZOLTAN_FOUND)\n\n      SET(HAVE_ZOLTAN TRUE CACHE BOOL "Has Zoltan tools for mesh (re)partitioning" )\n      GET_FILENAME_COMPONENT(ZOLTAN_LIBDIR ${ZOLTAN_LIBRARY} DIRECTORY)\n\n      MARK_AS_ADVANCED(HAVE_ZOLTAN)\n      MESSAGE(STATUS "  Zoltan:           " "${ZOLTAN_FOUND}")\n      MESSAGE(STATUS "  Zoltan_INC:       " "${ZOLTAN_INCLUDE_DIR}")\n      MESSAGE(STATUS "  Zoltan_LIB:      " "${ZOLTAN_LIBRARY}")\n      MESSAGE(STATUS "  Zoltan_LIBDIR:      " "${ZOLTAN_LIBDIR}")\n\n      INCLUDE_DIRECTORIES(${ZOLTAN_INCLUDE_DIR})\n      MESSAGE(STATUS "------------------------------------------------")\n\n    ELSE()\n      MESSAGE(STATUS "  Library not found: >ZOLTAN_FOUND< ")\n      MESSAGE(STATUS "    Missing: >ZOLTAN_INCLUDE_DIR< , >ZOLTAN_LIBRARY< for mesh (re)partitioning")\n    ENDIF(ZOLTAN_FOUND)\n\n    MESSAGE(STATUS "------------------------------------------------")\n  ENDIF()\nENDIF(WITH_Zoltan)\n\n# MMG Remeshing\nMESSAGE(STATUS "------------------------------------------------")\nMESSAGE(STATUS "Mesh adaptation 2D/3D looking for [Mmg] tools ")\n\nFIND_PACKAGE(MMG)\n# INCLUDE("cmake/Modules/FindMMG.cmake")\n# INCLUDE_DIRECTORIES(${MMG_INCLUDE_DIR})\n# TARGET_LINK_LIBRARIES( ${YOUR_TARGET} ${MMG_LIBRARY})\n\n\nIF(MMG_FOUND)\n\n  SET(HAVE_MMG TRUE CACHE BOOL "Has Mmg tools for Elmer/Ice Mesh adaptation" )\n  GET_FILENAME_COMPONENT(MMG_LIBDIR ${MMG_LIBRARY} DIRECTORY)\n\n  MARK_AS_ADVANCED(HAVE_MMG)\n  MESSAGE(STATUS "  Mmg:           " "${MMG_FOUND}")\n  MESSAGE(STATUS "  Mmg_INC:       " "${MMG_INCLUDE_DIR}")\n  MESSAGE(STATUS "  Mmg_LIB:      " "${MMG_LIBRARY}")\n  MESSAGE(STATUS "  Mmg_LIBDIR:      " "${MMG_LIBDIR}")\n  MESSAGE(STATUS "Compile MMG2DSolver/MMG3DSolver")\n  ADD_DEFINITIONS(-DHAVE_MMG)\n\n  INCLUDE_DIRECTORIES(${MMG_INCLUDE_DIR})\n  MESSAGE(STATUS "------------------------------------------------")\n\nELSE()\n  MESSAGE(STATUS "  Library not found: >MMG_FOUND< ")\n  MESSAGE(STATUS "    Missing: >MMG_INCLUDE_DIR< , >MMG_LIBRARY<, to compile MMG3DSolver")\nENDIF(MMG_FOUND)\n\nMESSAGE(STATUS "------------------------------------------------")\n\n\n# MPI and LAPACK\nFIND_PACKAGE(BLAS REQUIRED)\nFIND_PACKAGE(LAPACK REQUIRED)\n# BLAS and LAPACK libraries may be needed for testing\nSET(CMAKE_REQUIRED_LIBRARIES \n  ${CMAKE_REQUIRED_LIBRARIES} ${BLAS_LIBRARIES} ${LAPACK_LIBRARIES})\n\nIF(MPI_FOUND)\n  # Mumps\n  IF(WITH_Mumps)\n    FIND_PACKAGE(Mumps REQUIRED)\n  ENDIF()\n  # Hypre\n  IF(WITH_Hypre)\n    FIND_PACKAGE(Hypre REQUIRED OPTIONAL_COMPONENTS Euclid parcsr_ls ParaSails IJ_mv FEI core QUIET)\n  ENDIF()\n\n  # Permon\n  IF(WITH_FETI4I)\n    FIND_PACKAGE(FETI4I REQUIRED)\n  ENDIF()\nENDIF()\n\nIF(Mumps_FOUND)\n  SET(HAVE_MUMPS TRUE)\n  MARK_AS_ADVANCED(HAVE_MUMPS)\n  # LINK_DIRECTORIES(${MUMPS_LIBRARIES})\nENDIF()\n\nIF(Hypre_FOUND)\n  SET(HAVE_HYPRE TRUE)\n  MARK_AS_ADVANCED(HAVE_HYPRE)\n  INCLUDE_DIRECTORIES(${Hypre_INCLUDE_DIR})\n  # LINK_DIRECTORIES(${Hypre_LIBRARIES})\nENDIF()\n\nIF(FETI4I_FOUND)\n  SET(HAVE_FETI4I TRUE)\n  MARK_AS_ADVANCED(HAVE_FETI4I)\n  ADD_DEFINITIONS(-DHAVE_FETI4I)\nENDIF()\n\n# Check if Fortran compiler supports procedure pointer\nINCLUDE(testProcedurePointer)\nIF(NOT CMAKE_Fortran_COMPILER_SUPPORTS_PROCEDUREPOINTER)\n  MESSAGE(FATAL_ERROR "Fortran compiler does not seem to support the PROCEDURE statement.")\nENDIF()\n\n# Check if Fortran compiler supports contiguous keyword\nINCLUDE(testContiguous)\nIF(USE_CONTIGUOUS AND CMAKE_Fortran_COMPILER_SUPPORTS_CONTIGUOUS)\n  ADD_DEFINITIONS(-DCONTIG=,CONTIGUOUS)\nELSE()\n  ADD_DEFINITIONS(-DCONTIG=)\nENDIF()\n\n# Check if this is mingw toolchain. \nIF(MINGW)\n  ADD_DEFINITIONS(-DMINGW32)\nENDIF()\n\nIF(WIN32)\n  ADD_DEFINITIONS(-DWIN32)\nENDIF()\n\n# Check if Fortran compiler supports execute_command_line \nINCLUDE(testExecutecommand)\nIF(CMAKE_Fortran_COMPILER_SUPPORTS_EXECUTECOMMANDLINE)\n  ADD_DEFINITIONS(-DHAVE_EXECUTECOMMANDLINE)\nENDIF()\n\nADD_DEFINITIONS(-DUSE_ISO_C_BINDINGS)\nSET(FC_STDCALLBULL " ")\nSET(ELMER_LINKTYP 1)\n#SET(FC_FUNC FC_GLOBAL)\n#SET(FC_FUNC_ FC_GLOBAL_)\n \n# Add support for arpack \nADD_DEFINITIONS(-DUSE_ARPACK)\n\n#INCLUDE(FortranCInterface)\n#FortranCInterface_HEADER(FCMangle.h MACRO_NAMESPACE "FC_")\n#FortranCInterface_VERIFY(CXX)\n\n# Set up rpaths to point ELMER_INSTALL_LIB_DIR\nIF(${CMAKE_SYSTEM_NAME} MATCHES "Linux")   \n  SET(ELMERSOLVER_RPATH_STRING "\\$ORIGIN/../${ELMER_INSTALL_LIB_DIR}")\n  SET(ELMERLIB_RPATH_STRING "\\$ORIGIN/")\nELSEIF(APPLE)                               \n  SET(ELMERSOLVER_RPATH_STRING "@loader_path/../${ELMER_INSTALL_LIB_DIR}")\n  SET(ELMERLIB_RPATH_STRING "@loader_path/")\nENDIF()\n\n# Uncomment these to use rpath with linked libraries\n# SET(CMAKE_INSTALL_RPATH_USE_LINK_PATH TRUE) \n# SET(CMAKE_INSTALL_RPATH "${CMAKE_INSTALL_PREFIX}/lib")\n# Remove system directories (from the CMake guide)\n# LIST(FIND CMAKE_PLATFORM_IMPLICIT_LINK_DIRECTORIES "${CMAKE_INSTALL_PREFIX}/lib" isSystemDir)\n# IF("${isSystemDir}" STREQUAL "-1")\n#    SET(CMAKE_INSTALL_RPATH "${CMAKE_INSTALL_PREFIX}/lib")\n# ENDIF("${isSystemDir}" STREQUAL "-1")\n\nADD_SUBDIRECTORY(matc)\n\nIF(WITH_ElmerIce)\n  MESSAGE(STATUS "Adding optional package ElmerIce")\n  ADD_SUBDIRECTORY(elmerice)\nENDIF(WITH_ElmerIce)\n\nADD_SUBDIRECTORY(umfpack)\nADD_SUBDIRECTORY(fhutiter)\nADD_SUBDIRECTORY(meshgen2d)\nADD_SUBDIRECTORY(fem)\nADD_SUBDIRECTORY(mathlibs)\nADD_SUBDIRECTORY(elmergrid)\nADD_SUBDIRECTORY(license_texts)\n\nIF(WITH_ELMERGUI)\n    MESSAGE(STATUS "  Building ElmerGUI")\n    MESSAGE(STATUS "------------------------------------------------")\n    ADD_SUBDIRECTORY(ElmerGUI)\nENDIF(WITH_ELMERGUI)\n\nIF(WITH_ELMERGUITESTER)\n  ADD_SUBDIRECTORY(ElmerGUItester)\nENDIF(WITH_ELMERGUITESTER)\n\nIF(WITH_ELMERGUILOGGER)\n  ADD_SUBDIRECTORY(ElmerGUIlogger)\nENDIF(WITH_ELMERGUILOGGER)\n\n#INCLUDE(FeatureSummary)\n#FEATURE_SUMMARY(WHAT ENABLED_FEATURES\n#  INCLUDE_QUIET_PACKAGES\n#  DESCRIPTION "Enabled Features:"\n#  VAR enabledFeaturesText)\n#MESSAGE(STATUS "${enabledFeaturesText}")\n\n# \nIF(CMAKE_BUILD_TYPE)\n  STRING(TOUPPER ${CMAKE_BUILD_TYPE} CMAKE_BUILD_TYPE_UPCASE)\n  MARK_AS_ADVANCED(CMAKE_BUILD_TYPE_UPCASE)\nENDIF(CMAKE_BUILD_TYPE)\n\nMESSAGE(STATUS "------------------------------------------------")\nMESSAGE(STATUS "  BLAS library:   " "${BLAS_LIBRARIES}")\nMESSAGE(STATUS "  LAPACK library: " "${LAPACK_LIBRARIES}")\nMESSAGE(STATUS "------------------------------------------------")\nMESSAGE(STATUS "  Fortran compiler:        " "${CMAKE_Fortran_COMPILER}")\nMESSAGE(STATUS "  Fortran flags:           " "${CMAKE_Fortran_FLAGS} ${CMAKE_Fortran_FLAGS_${CMAKE_BUILD_TYPE_UPCASE}}")\nMESSAGE(STATUS "------------------------------------------------")\nMESSAGE(STATUS "  C compiler:              " "${CMAKE_C_COMPILER}")\nMESSAGE(STATUS "  C flags:                 " "${CMAKE_C_FLAGS} ${CMAKE_C_FLAGS_${CMAKE_BUILD_TYPE_UPCASE}}")\nMESSAGE(STATUS "------------------------------------------------")\nMESSAGE(STATUS "  CXX compiler:            " "${CMAKE_CXX_COMPILER}")\nMESSAGE(STATUS "  CXX flags:               " "${CMAKE_CXX_FLAGS} ${CMAKE_CXX_FLAGS_${CMAKE_BUILD_TYPE_UPCASE}}")\nMESSAGE(STATUS "------------------------------------------------")\nIF(WITH_MPI)\n  MESSAGE(STATUS "  MPI Fortran:             " "${MPI_Fortran_FOUND}")\n  MESSAGE(STATUS "  MPI Fortran compiler:    " "${MPI_Fortran_COMPILER}")\n  MESSAGE(STATUS "  MPI Fortran flags:       " "${MPI_Fortran_COMPILE_FLAGS}")\n  MESSAGE(STATUS "  MPI Fortran include dir: " "${MPI_Fortran_INCLUDE_PATH}")\n  MESSAGE(STATUS "  MPI Fortran libraries:   " "${MPI_Fortran_LIBRARIES}")\n  MESSAGE(STATUS "  MPI Fortran link flags:  " "${MPI_Fortran_LINK_FLAGS}")\n  MESSAGE(STATUS "------------------------------------------------")\n  MESSAGE(STATUS "  MPI C:             " "${MPI_C_FOUND}")\n  MESSAGE(STATUS "  MPI C compiler:    " "${MPI_C_COMPILER}")\n  MESSAGE(STATUS "  MPI C flags:       " "${MPI_C_COMPILE_FLAGS}")\n  MESSAGE(STATUS "  MPI C include dir: " "${MPI_C_INCLUDE_PATH}")\n  MESSAGE(STATUS "  MPI C libraries:   " "${MPI_C_LIBRARIES}")\n  MESSAGE(STATUS "  MPI C flags:       " "${MPI_C_LINK_FLAGS}")\n  MESSAGE(STATUS "------------------------------------------------")\n  IF(WITH_Mumps)\n    MESSAGE(STATUS "  Mumps:             " "${Mumps_FOUND}")\n    MESSAGE(STATUS "  Mumps include:     " "${Mumps_INCLUDE_DIR}")\n    MESSAGE(STATUS "  Mumps libraries:   " "${Mumps_LIBRARIES}")\n    MESSAGE(STATUS "------------------------------------------------")\n  ENDIF(WITH_Mumps)\n  IF(WITH_Hypre)\n    MESSAGE(STATUS "  Hypre:             " "${Hypre_FOUND}")\n    MESSAGE(STATUS "  Hypre include:     " "${Hypre_INCLUDE_DIR}")\n    MESSAGE(STATUS "  Hypre libraries:   " "${Hypre_LIBRARIES}")\n    MESSAGE(STATUS "------------------------------------------------")\n  ENDIF(WITH_Hypre)\nENDIF(WITH_MPI)\n\nIF(WITH_Trilinos)\n  MESSAGE(STATUS "  Trilinos:           " "${Trilinos_FOUND}")\n  MESSAGE(STATUS "  Trilinos_DIR:       " "${Trilinos_DIR}")\n  MESSAGE(STATUS "  Trilinos_LIBRARIES: " "${Trilinos_LIBRARIES}")\n  MESSAGE(STATUS "------------------------------------------------")\nENDIF(WITH_Trilinos)\n\nIF(WITH_CONTRIB)\n  MESSAGE(STATUS "  Building contributed solvers")\n  MESSAGE(STATUS "------------------------------------------------")\nENDIF(WITH_CONTRIB)\n\nIF(WITH_ELMERGUITESTER)\n  MESSAGE(STATUS "  Building ElmerGUI tester")\n  MESSAGE(STATUS "------------------------------------------------")\nENDIF(WITH_ELMERGUITESTER)\n\nIF(WITH_ELMERGUILOGGER)\n  MESSAGE(STATUS "  Building ElmerGUI logger")\n  MESSAGE(STATUS "------------------------------------------------")\nENDIF(WITH_ELMERGUILOGGER)\n\nIF(WITH_ELMERPOST)\n  MESSAGE(WARNING "  Building ElmerPost")\n  MESSAGE(STATUS "------------------------------------------------")\n  ADD_SUBDIRECTORY(post)\nENDIF(WITH_ELMERPOST)\n\nIF(HAVE_LUA)\n  MESSAGE(STATUS "  Building Lua")\n  MESSAGE(STATUS "------------------------------------------------")\nENDIF(HAVE_LUA)\n\n# Packaging\nif(NOT BYPASS_CPACK)\n  INCLUDE(${CMAKE_CURRENT_SOURCE_DIR}/cpack/ElmerCPack.cmake)\nendif(NOT BYPASS_CPACK)\n'}, {'path': 'matc/src/CMakeLists.txt', 'sha256': '9c805a84e85571871f969471f0c07d3319465dcbf29778165651a15f9d70b440', 'patched_sha256': '0ee4a9681f0a17534f279f7b1a241ea9579c2068b9c5425b38fb9c32024e02fd', 'content': '\nSET(matc_SRCS c3d.c clip.c dri_ps.c eig.c error.c eval.c files.c\n  funcs.c gra.c gra_com.c jacobi.c lists.c lu.c matc.c matrix.c oper.c\n  optim.c parser.c str.c urand.c variable.c)\n\nADD_LIBRARY(matc SHARED ${matc_SRCS})\n\nTARGET_LINK_LIBRARIES(matc m)\n\nADD_EXECUTABLE(Matc_bin main.c)\nTARGET_LINK_LIBRARIES(Matc_bin matc)\n\nSET_TARGET_PROPERTIES(Matc_bin PROPERTIES OUTPUT_NAME matc)\nIF(NOT(WIN32))\n  SET_TARGET_PROPERTIES(Matc_bin PROPERTIES INSTALL_RPATH "${ELMERSOLVER_RPATH_STRING}")\nENDIF()\n\nINSTALL(TARGETS matc Matc_bin RUNTIME DESTINATION "bin" LIBRARY DESTINATION ${ELMER_INSTALL_LIB_DIR})\n\n# Preserve pre-C23 non-prototype semantics only for the legacy MATC targets.\nSET_TARGET_PROPERTIES(matc Matc_bin PROPERTIES C_STANDARD 17 C_STANDARD_REQUIRED YES C_EXTENSIONS YES)\n'}, {'path': 'matc/src/jacobi.c', 'sha256': '098ee932f216a0e2aa53177e4d2b2dd1afd9c483e08066069e75ca376a70da80', 'patched_sha256': 'd26c1a4ac34e93ed881bf25990578a2579e64c5c982dc4d37166739de7274a1a', 'content': '/*****************************************************************************\n *\n *  Elmer, A Finite Element Software for Multiphysical Problems\n *\n *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n * \n * This library is free software; you can redistribute it and/or\n * modify it under the terms of the GNU Lesser General Public\n * License as published by the Free Software Foundation; either\n * version 2.1 of the License, or (at your option) any later version.\n *\n * This library is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\n * Lesser General Public License for more details.\n * \n * You should have received a copy of the GNU Lesser General Public\n * License along with this library (in file ../LGPL-2.1); if not, write \n * to the Free Software Foundation, Inc., 51 Franklin Street, \n * Fifth Floor, Boston, MA  02110-1301  USA\n *\n *****************************************************************************/\n\n/*******************************************************************************\n *\n *     Solve symmetric positive definite eigenvalue problem.\n *\n *******************************************************************************\n *\n *                     Author:       Juha Ruokolainen\n *\n *                    Address: CSC - IT Center for Science Ltd.\n *                                Keilaranta 14, P.O. BOX 405\n *                                  02101 Espoo, Finland\n *                                  Tel. +358 0 457 2723\n *                                Telefax: +358 0 457 2302\n *                              EMail: Juha.Ruokolainen@csc.fi\n *\n *                       Date: 30 May 1996\n *\n *                Modified by:\n *\n *       Date of modification:\n *\n ******************************************************************************/\n\n/*\n * $Id: jacobi.c,v 1.1.1.1 2005/04/14 13:29:14 vierinen Exp $ \n *\n * $Log: jacobi.c,v $\n * Revision 1.1.1.1  2005/04/14 13:29:14  vierinen\n * initial matc automake package\n *\n * Revision 1.2  1998/08/01 12:34:43  jpr\n *\n * Added Id, started Log.\n * \n *\n */\n\n#include "elmer/matc.h"\nint matc_jacobi(double [], double [], double [], double [], double [], int, double);\n\nVARIABLE *mtr_jacob(a) VARIABLE *a;\n{\n  VARIABLE *x, *ev;\n\n  double *b, *d, rtol;\n  int i, n;\n\n  if (NROW(a) != NCOL(a))\n    error("Jacob: Matrix must be square.\\n");\n\n  b = MATR(NEXT(a));\n  n = NROW(a);\n\n  if (NROW(NEXT(a)) != NCOL(NEXT(a)) || n != NROW(NEXT(a))) \n    error("Jacob: Matrix dimensions incompatible.\\n");\n\n  rtol = *MATR(NEXT(NEXT(a)));\n\n  x  = var_new("eigv", TYPE_DOUBLE, NROW(a), NCOL(a));\n  d  = (double *)ALLOCMEM(n * sizeof(double));\n  ev = var_temp_new(TYPE_DOUBLE, 1, n);\n\n  matc_jacobi(MATR(a), b, MATR(x), MATR(ev), d, n, rtol);\n  FREEMEM((char *)d);\n\n  return ev;\n};\n\n/************************************************************************\n  P R O G R A M \n  To solve the generalized eigenproblem using the\n  generalized Jacobi iteration\n\n  INPUT\n\n  a(n,n)    = Stiffness matrix (assumed positive definite)\n  b(n,n)    = Mass matrix (assumed positive definite)\n  x(n,n)    = Matrix storing eigenvectors on solution exit\n  eigv(n)   = Vector storing eigenvalues on solution exit\n  d(n)      = Working vector\n  n         = Order of the matrices a and b\n  rtol      = Convergence tolerance (usually set to 10.**-12)\n  nsmax     = Maximum number of sweeps allowed (usually set to 15)\n\n  OUTPUT\n\n  a(n,n)    = Diagonalized stiffness matrix\n  b(n,n)    = Diagonalized mass matrix\n  x(n,n)    = Eigenvectors stored columnwise\n  eigv(n)   = Eigenvalues\n\n*************************************************************************/\n\nint matc_jacobi(a,b,x,eigv,d,n,rtol)\n  double a[],b[],x[],eigv[],d[],rtol;\n  int n;\n{\n  register int i,j,k,ii,jj;\n  int    nsmax=50,        /* Max number of sweeps */\n         nsweep,          /* Current sweep number */\n         nr,           \n         jp1,jm1,kp1,km1,\n         convergence;\n\n  double eps,\n         eptola,eptolb,\n         akk,ajj,ab,\n         check,sqch,\n         d1,d2,den,\n         ca,cg,\n         aj,bj,ak,bk,\n         xj,xk,\n         tol,dif,\n         epsa,epsb,\n         bb;              /* Scale mass matrix */\n\n/************************************************************************\n  Initialize eigenvalue and eigenvector matrices \n*************************************************************************/\n  for( i=0 ; i<n ; i++)\n  {\n    ii = i*n+i;            /* address of diagonal element */\n    if (a[ii]<=0.0 || b[ii]<=0.0) return 0;\n    eigv[i] = d[i] = a[ii]/b[ii];\n    x[ii] = 1.0;           /* make an unit matrix */\n  }\n  if(n==1) return 1;      /* Return if single degree of freedom system */\n\n/************************************************************************\n  Initialize sweep counter and begin iteration\n*************************************************************************/\n  nr=n - 1;\n  for ( nsweep = 0; nsweep < nsmax; nsweep++)\n  {\n/************************************************************************\n    Check if present off-diagonal element is large enough to require zeroing\n*************************************************************************/\n\n    eps = pow(0.01, 2.0 * (nsweep + 1));\n    for(j=0 ; j<nr ; j++)\n    {\n      jj=j+1;\n      for(k=jj ; k<n ; k++)\n      {\n        eptola=( a[j*n+k]*a[j*n+k] / ( a[j*n+j]*a[k*n+k] ) );\n        eptolb=( b[j*n+k]*b[j*n+k] / ( b[j*n+j]*b[k*n+k] ) );\n        if ( eptola >= eps || eptolb >=eps )\n        {\n\n/************************************************************************\n          if zeroing is required, calculate the rotation matrix elements\n*************************************************************************/\n\n          akk=a[k*n+k]*b[j*n+k] - b[k*n+k]*a[j*n+k];\n          ajj=a[j*n+j]*b[j*n+k] - b[j*n+j]*a[j*n+k];\n          ab =a[j*n+j]*b[k*n+k] - a[k*n+k]*b[j*n+j];\n          check=(ab*ab+4.0*akk*ajj)/4.0;\n\n          if (check<=0.0)\n          {\n            printf("***Error   solution stop in *jacobi*\\n");\n            printf("        check = %20.14e\\n", check);\n            return 1;\n          }\n          sqch= sqrt(check);\n          d1  = ab/2.0+sqch;\n          d2  = ab/2.0-sqch;\n          den = d1;\n          if ( abs(d2) > abs(d1) ) den=d2;\n\n          if (den == 0.0)\n          {\n            ca=0.0;\n            cg= -a[j*n+k] / a[k*n+k];\n          }\n          else\n          {\n            ca= akk/den;\n            cg= -ajj/den;\n          }\n/************************************************************************\n  Perform the generalized rotation to zero the present off-diagonal element\n*************************************************************************/\n          if (n != 2)\n          {\n            jp1=j+1;\n            jm1=j-1;\n            kp1=k+1;\n            km1=k-1;\n/**************************************/\n            if ( jm1 >= 0)\n              for (i=0 ; i<=jm1 ; i++)\n              {\n                aj = a[i*n+j];\n                bj = b[i*n+j];\n                ak = a[i*n+k];\n                bk = b[i*n+k];\n                a[i*n+j] = aj+cg*ak;\n                b[i*n+j] = bj+cg*bk;\n                a[i*n+k] = ak+ca*aj;\n                b[i*n+k] = bk+ca*bj;\n              };\n/**************************************/\n            if ((kp1-n+1) <= 0)\n              for (i=kp1 ; i<n ; i++)\n              {\n                aj = a[j*n+i];\n                bj = b[j*n+i];\n                ak = a[k*n+i];\n                bk = b[k*n+i];\n                a[j*n+i] = aj+cg*ak;\n                b[j*n+i] = bj+cg*bk;\n                a[k*n+i] = ak+ca*aj;\n                b[k*n+i] = bk+ca*bj;\n              };\n/**************************************/\n            if ((jp1-km1) <= 0.0)\n              for (i=jp1 ; i<=km1 ; i++)\n              {\n                aj = a[j*n+i];\n                bj = b[j*n+i];\n                ak = a[i*n+k];\n                bk = b[i*n+k];\n                a[j*n+i] = aj+cg*ak;\n                b[j*n+i] = bj+cg*bk;\n                a[i*n+k] = ak+ca*aj;\n                b[i*n+k] = bk+ca*bj;\n              };\n          };\n   \n          ak = a[k*n+k];\n          bk = b[k*n+k];\n          a[k*n+k] = ak+2.0*ca*a[j*n+k]+ca*ca*a[j*n+j];\n          b[k*n+k] = bk+2.0*ca*b[j*n+k]+ca*ca*b[j*n+j];\n          a[j*n+j] = a[j*n+j]+2.0*cg*a[j*n+k]+cg*cg*ak;\n          b[j*n+j] = b[j*n+j]+2.0*cg*b[j*n+k]+cg*cg*bk;\n          a[j*n+k] = 0.0;\n          b[j*n+k] = 0.0;\n\n/************************************************************************\n          Update the eigenvector matrix after each rotation\n*************************************************************************/\n          for (i=0 ; i<n ; i++)\n          {\n            xj = x[i*n+j];\n            xk = x[i*n+k];\n            x[i*n+j] = xj+cg*xk;\n            x[i*n+k] = xk+ca*xj;\n          };\n        };\n      };\n    };\n/************************************************************************\n    Update the eigenvalues after each sweep\n*************************************************************************/\n    for (i=0 ; i<n ; i++)\n    {\n      ii=i*n+i;\n      if (a[ii]<=0.0 || b[ii]<=0.0)\n      {\n         error( "*** Error  solution stop in *jacobi*\\n Matrix not positive definite.");\n      };\n      eigv[i] = a[ii] / b[ii];\n    };\n\n/************************************************************************\n    check for convergence\n*************************************************************************/\n    convergence = 1;\n    for(i=0 ; i<n ; i++)\n    {\n      tol = rtol*d[i];\n      dif = abs(eigv[i]-d[i]);\n      if (dif > tol) convergence = 0;\n      if (! convergence) break;\n    };\n/************************************************************************\n    check if all off-diag elements are satisfactorily small\n*************************************************************************/\n    if (convergence)\n    {\n      eps=rtol*rtol;\n      for (j=0 ; j<nr ; j++)\n      {\n        jj=j+1;\n        for (k=jj ; k<n ; k++)\n        {\n          epsa = ( a[j*n+k]*a[j*n+k] / ( a[j*n+j]*a[k*n+k] ) );\n          epsb = ( b[j*n+k]*b[j*n+k] / ( b[j*n+j]*b[k*n+k] ) );\n          if ( epsa >= eps || epsb >=eps ) convergence = 0;\n          if (! convergence) break;\n        };\n        if (! convergence) break;\n      };\n    };\n    if (! convergence)\n    {\n      for (i=0 ; i<n ; i++)\n      d[i] = eigv[i];\n    };\n    if (convergence) break;\n  };\n/************************************************************************\n  Fill out bottom triangle of resultant matrices and scale eigenvectors\n*************************************************************************/\n  for (i=0 ; i<n ; i++)\n    for (j=i ; j<n ; j++)\n    {\n      b[j*n+i] = b[i*n+j];\n      a[j*n+i] = a[i*n+j];\n    };\n\n  for (j=0 ; j<n ; j++)\n  {\n    bb = sqrt( b[j*n+j] );\n    for (k=0 ; k<n ; k++)\n      x[k*n+j] /= bb;\n  };\n  PrintOut( "jacobi: nsweeps %d\\n", nsweep );\n  return 1 ;\n}\n'}, {'path': 'matc/src/matrix.c', 'sha256': '87e5fbbac5d77f9cd35cd70e58ce22f3a3bcaba3d47344d98a063416bd71fd91', 'patched_sha256': '94616683a38641076cbbcf28f1cfd01ee2b9c723df5633f1e91eaea6bc1c9a95', 'content': '/*****************************************************************************\n *\n *  Elmer, A Finite Element Software for Multiphysical Problems\n *\n *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n * \n * This library is free software; you can redistribute it and/or\n * modify it under the terms of the GNU Lesser General Public\n * License as published by the Free Software Foundation; either\n * version 2.1 of the License, or (at your option) any later version.\n *\n * This library is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\n * Lesser General Public License for more details.\n * \n * You should have received a copy of the GNU Lesser General Public\n * License along with this library (in file ../LGPL-2.1); if not, write \n * to the Free Software Foundation, Inc., 51 Franklin Street, \n * Fifth Floor, Boston, MA  02110-1301  USA\n *\n *****************************************************************************/\n\n/*******************************************************************************\n *\n *     MATC matrix utilities.\n *\n *******************************************************************************\n *\n *                     Author:       Juha Ruokolainen\n *\n *                    Address: CSC - IT Center for Science Ltd.\n *                                Keilaranta 14, P.O. BOX 405\n *                                  02101 Espoo, Finland\n *                                  Tel. +358 0 457 2723\n *                                Telefax: +358 0 457 2302\n *                              EMail: Juha.Ruokolainen@csc.fi\n *\n *                       Date: 30 May 1996\n *\n *                Modified by:\n *\n *       Date of modification:\n *\n ******************************************************************************/\n/***********************************************************************\n|\n|  MATRIX.C - Last Edited 8. 8. 1988\n|\n***********************************************************************/\n\n/*======================================================================\n|Syntax of the manual pages:\n|\n|FUNCTION NAME(...) params ...\n|\n$  usage of the function and type of the parameters\n?  explane the effects of the function\n=  return value and the type of value if not of type int\n@  globals effected directly by this routine\n!  current known bugs or limitations\n&  functions called by this function\n~  these functions may interest you as an alternative function or\n|  because they control this function somehow\n^=====================================================================*/\n\n\n/*\n * $Id: matrix.c,v 1.1.1.1 2005/04/14 13:29:14 vierinen Exp $ \n *\n * $Log: matrix.c,v $\n * Revision 1.1.1.1  2005/04/14 13:29:14  vierinen\n * initial matc automake package\n *\n * Revision 1.2  1998/08/01 12:34:50  jpr\n *\n * Added Id, started Log.\n * \n *\n */\n\n#include "elmer/matc.h"\n#include <time.h>\n\n#define MA(i,j) a[(i) * ncola + (j)]\n#define MB(i,j) b[(i) * ncolb + (j)]\n#define MC(i,j) c[(i) * ncolc + (j)]\n\ndouble func_abs(arg) \n     double arg;\n{\n  return abs(arg);\n}\n\ndouble func_mod(x,y)\n     double x,y;\n{\n  int ix, iy;\n\n  ix = x + 0.5;\n  iy = y + 0.5;\n  return (double)(ix % iy);\n}\n\nVARIABLE *mtr_sum(A) VARIABLE *A;\n{\n   VARIABLE *C;\n\n   int i, j;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n\n   double *a = MATR(A), *c;\n\n\n   if (nrowa == 1 || ncola == 1)\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, 1); c = MATR(C);\n     nrowa = (nrowa == 1) ? ncola : nrowa;\n     for(i = 0; i < nrowa; i++) *c += *a++;\n   }\n   else\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, ncola); c = MATR(C);\n     for(i = 0; i < ncola; i++) \n       for(j = 0; j < nrowa; j++) c[i] += MA(j, i);\n   }\n\n   return C;\n}\n\nVARIABLE *mtr_trace(A) VARIABLE *A;\n{\n  VARIABLE *C;\n\n  double temp = 0.0;\n  int i;\n\n  int nrowa = NROW(A), ncola = NCOL(A);\n  double *a = MATR(A);\n  \n  if (nrowa !=  ncola) error("trace: not square.\\n");\n\n  for(i = 0; i < nrowa; i++) temp += MA(i,i);\n\n  C = var_temp_new(TYPE(A), 1, 1); *MATR(C) = temp;\n\n  return C;\n}\n\nVARIABLE *mtr_zeros(A) VARIABLE *A;\n{\n  VARIABLE *C;\n\n  int ind1 = 1, ind2 = 1;\n  \n  if (NEXT(A) != NULL)\n  {\n   ind1 = (int)*MATR(A); ind2 = (int)*MATR(NEXT(A));\n  } \n  else\n  {\n    ind2 = (int)*MATR(A);\n  }\n\n  if (ind1 < 1 || ind2 < 1) \n    error("Zeros: invalid size for and array");\n\n  C = var_temp_new(TYPE_DOUBLE, ind1, ind2);\n\n  return C;\n}\n\nVARIABLE *mtr_ones(A) VARIABLE *A;\n{\n  VARIABLE *C;\n  double *c;\n  int i, n;\n\n  C = mtr_zeros(A); c = MATR(C);\n  n = NROW(C) * NCOL(C);\n\n  for(i = 0; i < n; i++) *c++ = 1.0; \n\n  return C;\n}\n\nVARIABLE *mtr_rand(A) VARIABLE *A;\n{\n  VARIABLE *C;\n\n  static int seed = 0;\n#pragma omp threadprivate (seed)\n  int i, n;\n\n  double *c;\n\n  C = mtr_zeros(A); c = MATR(C);\n  n = NROW(C) * NCOL(C);\n\n  if (seed == 0) seed = time(NULL);\n  for(i = 0; i < n; i++)  *c++ = urand(&seed);\n\n  return C;\n}\n\nVARIABLE *mtr_resize(A) VARIABLE *A;\n{\n  VARIABLE *C;\n\n  int i, j, n, m, ind1 = 1, ind2;\n\n  double *a = MATR(A), *c;\n  \n  if (NEXT(NEXT(A)) != NULL)\n  {\n    ind1 = *MATR(NEXT(A)); ind2 = *MATR(NEXT(NEXT(A)));\n  } \n  else\n  {\n    ind2 = (int)*MATR(NEXT(A));;\n  }\n\n  if (ind1 < 1 || ind2 < 1) \n    error("resize: invalid size for and array");\n  \n  C = var_temp_new(TYPE(A), ind1, ind2); c = MATR(C);\n  a = MATR(A); n = ind1 * ind2; m = NROW(A) * NCOL(A);\n\n  for(i = j = 0; i < n; i++)\n  {\n    *c++ = a[j++]; if (j == m) j = 0;\n  }\n\n  return C;\n}\n\nVARIABLE *mtr_vector(A) VARIABLE *A;\n{\n  VARIABLE *C;\n\n  double start, stop, incr, x, *c;\n\n  int i, eval;\n  \n  start = *MATR(A); stop =  *MATR(NEXT(A));\n\n  if (NEXT(NEXT(A)) != (VARIABLE *)NULL)\n    incr = *MATR(NEXT(NEXT(A)));\n  else\n    incr = (start < stop) ? (1) : (-1);\n  \n  if (incr == 0)\n    incr = (start < stop) ? (1) : (-1);\n\n  eval = (int)(abs(stop-start) / abs(incr)) + 1;\n  if (eval < 1) return NULL;\n\n  C = var_temp_new(TYPE_DOUBLE, 1, eval); c = MATR(C);\n  \n  x = start;\n  for(i = 0;  i < eval; i++)\n  {\n    *c++ = x; x += incr;\n  }\n  \n  return C;\n}\n\nVARIABLE *mtr_eye(A) VARIABLE *A;\n{\n  VARIABLE *C;\n  double *c;\n  int i, ind, ncolc;\n  \n  if (*MATR(A) < 1)\n  {\n    error("eye: Invalid size for an array.\\n");\n  }\n\n  ind = (int)*MATR(A);\n  \n  C = var_temp_new(TYPE_DOUBLE, ind, ind); \n  c = MATR(C); ncolc = ind;\n\n  for (i = 0; i < ind; i++) MC(i,i) = 1.0;\n  \n  return C;\n}\n\nVARIABLE *mtr_size(A) VARIABLE *A;\n{  \n  VARIABLE *C;\n  double *c;\n\n  C = var_temp_new(TYPE_DOUBLE, 1, 2); c = MATR(C);\n  *c++ = NROW(A); *c = NCOL(A);\n  \n  return C;\n}\n\nVARIABLE *mtr_min(A) VARIABLE *A;\n{\n   VARIABLE *C;\n\n   double *a = MATR(A), *c;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n   int i, j;\n\n   if (nrowa == 1 || ncola == 1)\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, 1); c = MATR(C);\n     *c = *a++; nrowa = max(ncola, nrowa);\n     for(i = 1; i < nrowa; i++, a++) *c = min(*c, *a);\n   }\n   else\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, ncola); c = MATR(C);\n     for(i = 0; i < ncola; i++, c++)\n     {\n       *c = MA(0, i);\n       for(j = 1; j < nrowa; j++) *c = min(*c, MA(j, i));\n     }\n   }\n\n   return C;\n}\n\nVARIABLE *mtr_max(A) VARIABLE *A;\n{\n   VARIABLE *C;\n\n   double *a = MATR(A), *c;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n   int i, j;\n\n   if (nrowa == 1 || ncola == 1)\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, 1); c = MATR(C);\n     *c = *a++; nrowa = max(ncola, nrowa);\n     for(i = 1; i < nrowa; i++, a++) *c = max(*c, *a);\n   }\n   else\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, ncola); c = MATR(C);\n     for(i = 0; i < ncola; i++, c++)\n     {\n       *c = MA(0, i);\n       for(j = 1; j < nrowa; j++) *c = max(*c, MA(j, i));\n     }\n   }\n\n   return C;\n}\n\nVARIABLE *mtr_diag(A) VARIABLE *A;\n{\n   VARIABLE *C;\n\n   double *a = MATR(A), *c;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n   int ncolc;\n\n   int i;\n\n   if (nrowa == 1 || ncola == 1)\n   {\n     nrowa = max(nrowa, ncola); ncolc = nrowa;\n     C = var_temp_new(TYPE_DOUBLE, nrowa, nrowa); c = MATR(C);\n     for(i = 0; i < nrowa; i++) MC(i, i) = *a++;\n   }\n   else\n   {\n     C = var_temp_new(TYPE_DOUBLE, 1, nrowa); c = MATR(C);\n     for(i = 0; i < min(nrowa,ncola); i++) *c++ = MA(i, i);\n   }\n\n   return C;\n}\n\nVARIABLE *mtr_pow(A) VARIABLE *A;\n{\n   VARIABLE *B = NEXT(A), *C;\n   double *a = MATR(A), b = M(B,0,0), *c;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n\n   int i;\n\n   C = var_temp_new(TYPE_DOUBLE, nrowa,ncola );\n   c = MATR( C );\n   for(i = 0; i < nrowa*ncola; i++) *c++ = pow(*a++,b);\n\n   return C;\n}\n\nVARIABLE *mtr_where(A) VARIABLE *A;\n{\n   VARIABLE *C;\n\n   double *a = MATR(A), *c;\n\n   int nrowa = NROW(A), ncola = NCOL(A);\n\n   int i,n=0;\n\n   for( i=0; i < nrowa*ncola; i++) if ( a[i] ) n++;\n\n   C = var_temp_new( TYPE_DOUBLE,1,n );\n   c = MATR(C);\n\n   for( i=0; i < nrowa*ncola; i++ ) if ( a[i] ) { *c++ = i; }\n\n   return C;\n}\n\nvoid mtr_com_init()\n{\n  static char *minHelp =\n  {\n     "r = min(matrix)\\n"\n     "Return value is a vector containing smallest element in columns of given matrix.\\n"\n     "r=min(min(matrix) gives smallest element of the matrix.\\n\\n"\n  };\n\n  static char *maxHelp =\n  {\n     "r = max(matrix)\\n"\n     "Return value is a vector containing largest element in columns of given matrix.\\n"\n     "r=max(max(matrix)) gives largest element of the matrix.\\n\\n"\n  };\n\n  static char *sumHelp =\n  {\n     "r = sum(matrix)\\n"\n     "Return vector is column sums of given matrix. r=sum(sum(matrix)) gives\\n"\n     "the total sum of elements of the matrix.\\n\\n"\n  };\n\n  static char *traceHelp =\n  {\n     "r = trace(matrix)\\n"\n     "Return value is sum of matrix diagonal elements.\\n\\n"\n  };\n\n  static char *detHelp =\n  {\n     "r = det(matrix)\\n"\n     "Return value is determinant of given square matrix.\\n\\n"\n  };\n\n  static char *invHelp =\n  {\n     "r = inv(matrix)\\n"\n     "Invert given square matrix. Computed also by r=matrix^(-1).\\n\\n"\n  };\n\n  static char *eigHelp =\n  {\n     "r = eig(matrix)\\n"\n     "Return eigenvalues of given square matrix. r(n,0) is real part of the\\n"\n     "n:th eigenvalue, r(n,1) is the imaginary part respectively\\n\\n"\n  };\n\n  static char *jacobHelp =\n  {\n     "r = jacob(a,b,eps)\\n"\n     "Solve symmetric positive definite eigenvalue problem by Jacob iteration.\\n"\n     "Return values are the eigenvalues. Also a variable eigv is created containing\\n"\n     "eigenvectors.\\n\\n"\n  };\n\n  static char *ludHelp =\n  {\n     "r = lud(matrix)\\n"\n     "Return value is lud decomposition of given matrix.\\n\\n"\n  };\n\n  static char *hesseHelp =\n  {\n     "r = hesse(matrix)\\n"\n     "Return the upper hessenberg form of given matrix.\\n\\n"\n  };\n\n  static char *eyeHelp =\n  {\n     "r = eye(n)\\n"\n     "Return n by n identity matrix.\\n\\n"\n  };\n\n  static char *zerosHelp =\n  {\n     "r = zeros(n,m)\\n"\n     "Return n by m matrix with elements initialized to zero.\\n"\n  };\n\n  static char *onesHelp =\n  {\n     "r = ones(n,m)\\n"\n     "Return n by m matrix with elements initialized to one.\\n"\n  };\n\n  static char *randHelp =\n  {\n     "r = rand(n,m)\\n"\n     "Return n by m matrix with elements initialized to with random number from\\n"\n     "zero to one.\\n\\n"\n  };\n\n  static char *diagHelp =\n  {\n     "r=diag(matrix) or r=diag(vector)\\n"\n     "Given matrix return diagonal entries as a vector. Given vector return matrix\\n"\n     "with diagonal elements from vector. r=diag(diag(a)) gives matrix with diagonal\\n"\n     "elements from matrix a otherwise elements are zero.\\n\\n"\n  };\n\n  static char *vectorHelp =\n  {\n     "r=vector(start,end,inc)\\n"\n     "Return vector of values going from start to end by inc.\\n\\n"\n  };\n\n  static char *sizeHelp =\n  {\n     "r = size(matrix)\\n"\n     "Return size of given matrix.\\n"\n  };\n\n  static char *resizeHelp =\n  {\n     "r = resize(matrix,n,m)\\n"\n     "Make a matrix to look as a n by m matrix.\\n\\n"\n  };\n\n  static char *whereHelp =\n  {\n     "r = where(l)\\n"\n     "Return linear indexes of where l is true.\\n\\n"\n  };\n\n  com_init( "sin"    , TRUE,  TRUE,  (VARIABLE *(*)())sin    , 1, 1, "r=sin(x)" );\n  com_init( "cos"    , TRUE,  TRUE,  (VARIABLE *(*)())cos    , 1, 1, "r=cos(x)" );\n  com_init( "tan"    , TRUE,  TRUE,  (VARIABLE *(*)())tan    , 1, 1, "r=tan(x)" );\n  com_init( "asin"   , TRUE,  TRUE,  (VARIABLE *(*)())asin   , 1, 1, "r=asin(x)" );\n  com_init( "acos"   , TRUE,  TRUE,  (VARIABLE *(*)())acos   , 1, 1, "r=acos(x)" );\n  com_init( "atan"   , TRUE,  TRUE,  (VARIABLE *(*)())atan   , 1, 1, "r=atan(x)" );\n  com_init( "atan2"  , TRUE,  TRUE,  (VARIABLE *(*)())atan2  , 2, 2, "r=atan2(y,x)" );\n  com_init( "sinh"   , TRUE,  TRUE,  (VARIABLE *(*)())sinh   , 1, 1, "r=sinh(x)" );\n  com_init( "cosh"   , TRUE,  TRUE,  (VARIABLE *(*)())cosh   , 1, 1, "r=cosh(x)" );\n  com_init( "tanh"   , TRUE,  TRUE,  (VARIABLE *(*)())tanh   , 1, 1, "r=tanh(x)" );\n  com_init( "exp"    , TRUE,  TRUE,  (VARIABLE *(*)())exp    , 1, 1, "r=exp(x)" );\n  com_init( "ln"     , TRUE,  TRUE,  (VARIABLE *(*)())log    , 1, 1, "r=ln(x)\\nNatural logarithm." );\n  com_init( "log"    , TRUE,  TRUE,  (VARIABLE *(*)())log10  , 1, 1, "r=log(x)\\nBase 10 logarithm." );\n  com_init( "sqrt"   , TRUE,  TRUE,  (VARIABLE *(*)())sqrt   , 1, 1, "r=sqrt(x)" );\n  com_init( "ceil"   , TRUE,  TRUE,  (VARIABLE *(*)())ceil   , 1, 1, "r=ceil(x)\\nSmallest integer not less than x." );\n  com_init( "floor"  , TRUE,  TRUE,  (VARIABLE *(*)())floor  , 1, 1, "r=floor(x)\\nLargest integer not more than x." );\n  com_init( "abs"    , TRUE,  TRUE,  (VARIABLE *(*)())func_abs   , 1, 1,"r=abs(x)");\n  com_init( "mod"    , TRUE,  TRUE,  (VARIABLE *(*)())func_mod   , 2, 2,"r=mod(x,y)");\n  com_init( "pow"    , FALSE, TRUE,  mtr_pow,     2, 2, "r=pow(x,y)" );\n  com_init( "min"    , FALSE, TRUE,  mtr_min,     1, 1, minHelp    );\n  com_init( "max"    , FALSE, TRUE,  mtr_max,     1, 1, maxHelp    );\n  com_init( "sum"    , FALSE, TRUE,  mtr_sum,     1, 1, sumHelp    );\n  com_init( "trace"  , FALSE, TRUE,  mtr_trace,   1, 1, traceHelp  );\n  com_init( "det"    , FALSE, TRUE,  mtr_det,     1, 1, detHelp    );\n  com_init( "inv"    , FALSE, TRUE,  mtr_inv,     1, 1, invHelp    );\n  com_init( "eig"    , FALSE, TRUE,  mtr_eig,     1, 1, eigHelp    );\n  com_init( "jacob"  , FALSE, TRUE,  mtr_jacob,   3, 3, jacobHelp  );\n  com_init( "lud"    , FALSE, TRUE,  mtr_LUD,     1, 1, ludHelp    );\n  com_init( "hesse"  , FALSE, TRUE,  mtr_hesse,   1, 1, hesseHelp  );\n  com_init( "eye"    , FALSE, TRUE,  mtr_eye,     1, 1, eyeHelp    );\n  com_init( "zeros"  , FALSE, TRUE,  mtr_zeros,   1, 2, zerosHelp  );\n  com_init( "ones"   , FALSE, TRUE,  mtr_ones,    1, 2, onesHelp   );\n  com_init( "rand"   , FALSE, FALSE, mtr_rand,    1, 2, randHelp   );\n  com_init( "diag"   , FALSE, TRUE,  mtr_diag,    1, 1, diagHelp   );\n  com_init( "vector" , FALSE, TRUE,  mtr_vector,  2, 3, vectorHelp );\n  com_init(  "size"  , FALSE, TRUE,  mtr_size,    1, 1, sizeHelp  );\n  com_init( "resize" , FALSE, TRUE,  mtr_resize,  2, 3, resizeHelp );\n  com_init( "where"  , FALSE, FALSE, mtr_where,   1, 1, whereHelp );\n}\n'}, {'path': 'matc/src/matc.c', 'sha256': '3756042ade01f462c43bc3650457492f8ca75c6457664c014509822f77b511fc', 'patched_sha256': '6aa15901fab977d1b910f9b0035749cfd623499e2f1588a6f41675b3df30b203', 'content': '/*****************************************************************************\n *\n *  Elmer, A Finite Element Software for Multiphysical Problems\n *\n *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n * \n * This library is free software; you can redistribute it and/or\n * modify it under the terms of the GNU Lesser General Public\n * License as published by the Free Software Foundation; either\n * version 2.1 of the License, or (at your option) any later version.\n *\n * This library is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\n * Lesser General Public License for more details.\n * \n * You should have received a copy of the GNU Lesser General Public\n * License along with this library (in file ../LGPL-2.1); if not, write \n * to the Free Software Foundation, Inc., 51 Franklin Street, \n * Fifth Floor, Boston, MA  02110-1301  USA\n *\n *****************************************************************************/\n\n/*******************************************************************************\n *\n *     MATC main module.\n *\n *******************************************************************************\n *\n *                     Author:       Juha Ruokolainen\n *\n *                    Address: CSC - IT Center for Science Ltd.\n *                                Keilaranta 14, P.O. BOX 405\n *                                  02101 Espoo, Finland\n *                                  Tel. +358 0 457 2723\n *                                Telefax: +358 0 457 2302\n *                              EMail: Juha.Ruokolainen@csc.fi\n *\n *                       Date: 30 May 1996\n *\n *                Modified by:\n *\n *       Date of modification:\n *\n ******************************************************************************/\n/***********************************************************************\n|\n|  MATC - Last Edited 9. 8. 1988\n|\n***********************************************************************/\n\n/*======================================================================\n|Syntax of the manual pages:\n|\n|FUNCTION NAME(...) params ...\n|\n$  usage of the function and type of the parameters\n?  explane the effects of the function\n=  return value and the type of value if not of type int\n@  globals effected directly by this routine\n!  current known bugs or limitations\n&  functions called by this function\n~  these functions may interest you as an alternative function or\n|  because they control this function somehow\n^=====================================================================*/\n\n\n/*\n * $Id: matc.c,v 1.7 2007/06/08 08:12:17 jpr Exp $ \n *\n * $Log: matc.c,v $\n * Revision 1.7  2007/06/08 08:12:17  jpr\n * *** empty log message ***\n *\n * Revision 1.6  2006/02/07 10:21:42  jpr\n * Changed visibility of some variables to local scope.\n *\n * Revision 1.5  2006/02/02 06:54:44  jpr\n * small formatting changes.\n *\n * Revision 1.3  2005/08/25 13:44:22  vierinen\n * windoze stuff\n *\n * Revision 1.2  2005/05/27 12:26:20  vierinen\n * changed header install location\n *\n * Revision 1.1.1.1  2005/04/14 13:29:14  vierinen\n * initial matc automake package\n *\n * Revision 1.2  1998/08/01 12:34:48  jpr\n *\n * Added Id, started Log.\n * \n *\n */\n\n#define MODULE_MATC\n#include "elmer/matc.h"\n#include <unistd.h>\n#include "str.h"\n#include "../config.h"\n\n#ifdef DEBUG\n      static FILE *fplog;\n      static int tot;\n#pragma omp threadprivate (fplog, tot)\n#endif\n/*======================================================================\n? main program, initialize few constants and go for it.\n^=====================================================================*/\nvoid mtc_init( FILE *input_file, FILE *output_file, FILE *error_file )\n{\n   VARIABLE *ptr;\n\n   char str[256];\n\n   int i;                    /* i\'m getting tired with all these i\'s */\n\n   static char *evalHelp =\n   {\n       "eval( str )\\n\\n"\n       "Evaluate content variable. Another form of this command is @str.\\n"\n   };\n\n   static char *sourceHelp =\n   {\n       "source( name )\\n\\n"\n       "Execute commands from file given name.\\n"\n   };\n\n   static char *helpHelp =\n   {\n       "help or help(\\"symbol\\")\\n\\n"\n       "First form of the command gives list of available commands.\\n"\n       "Second form gives help on specific routine.\\n"\n   };\n\n#ifdef _OPENMP\n   /* Allocate listheaders for each thread separately */\n#pragma omp parallel\n   {\n\t   /* Do malloc and initialize listheaders */\n\t   listheaders = (LIST *) malloc(sizeof(LIST)*MAX_HEADERS);\n\t   /* memory allocations */\n\t   listheaders[ALLOCATIONS].next = NULL;\n\t   listheaders[ALLOCATIONS].name = "Allocations";\n\t   /* global CONSTANTS */\n\t   listheaders[CONSTANTS].next = NULL;\n\t   listheaders[CONSTANTS].name = "Constants";\n\t   /* global VARIABLES */\n\t   listheaders[VARIABLES].next = NULL;\n\t   listheaders[VARIABLES].name = "Currently defined VARIABLES";\n\t   /* internal commands */\n\t   listheaders[COMMANDS].next = NULL;\n\t   listheaders[COMMANDS].name = "Builtin Functions";\n\t   /* user defined functions */\n\t   listheaders[FUNCTIONS].next = NULL;\n\t   listheaders[FUNCTIONS].name = "User Functions";\n   }\n#endif /* _OPENMP */\n\n#ifdef DEBUG\n      fplog = fopen("matcdbg","w");\n#endif\n  ALLOC_HEAD = (LIST *)NULL;\n\n  /*\n   *   input & output & error streams\n   */\n  math_in  = input_file;\n  math_err = error_file;\n  math_out = output_file;\n\n  mtr_com_init();          /* initialize matrix handling commands   */\n  var_com_init();          /*     ""     VARIABLE  ""      ""       */\n  fnc_com_init();          /*     ""     function handling commands */\n  fil_com_init();          /*     ""     file handling commands     */\n  gra_com_init();          /*     ""     graphics commands          */\n  str_com_init();          /*     ""     string handling            */\n\n  /*\n   *    and few others.\n   */\n  com_init( "eval"   , FALSE, FALSE, com_apply,   1, 1, evalHelp   );\n  com_init( "source" , FALSE, FALSE, com_source,  1, 1, sourceHelp );\n  com_init( "help"   , FALSE, FALSE, com_help   , 0, 1, helpHelp   );\n  com_init( "quit"   , FALSE, FALSE, com_quit   , 0, 0, "quit\\n" );\n  com_init( "exit"   , FALSE, FALSE, com_quit   , 0, 0, "exit\\n" );\n  \n  /*\n   *    these constants will always be there for you.\n   */\n  ptr = const_new("true", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 1.0;\n\n  ptr = const_new("false", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 0.0;\n\n  ptr = const_new("stdin", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 0;\n\n  ptr = const_new("stdout", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 1;\n\n  ptr = const_new("stderr", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 2;\n\n  ptr = const_new("pi", TYPE_DOUBLE, 1, 1);\n  M(ptr,0,0) = 2*acos(0.0);\n\n#if 0\n  /*\n   *  trap INTERRUPT and Floating Point Exeption signals\n   */ \n   signal(SIGFPE, sig_trap);\n\n   sprintf( str, "%s/lib/mc.ini", getenv("ELMER_POST_HOME") );\n\n   if ( (math_in = fopen( str, "r" ) ) != (FILE *)NULL)\n   {\n       doread();\n       fclose( math_in );\n   }\n\n  /*\n   *   and finally standard input.\n   */\n  math_in = stdin;\n\n  doread();\n\n  var_free();\n  com_free();\n  fnc_free();\n  const_free();\n\n  mem_free_all();\n\n#ifdef DEBUG\n      fclose(fplog);\n#endif\n#endif\n\n  return;   /* done */\n}\n\nchar * mtc_domath( char *str )\n{\n  VARIABLE *headsave;            /* this should not be here */\n\n  jmp_buf jmp, *savejmp;         /* save program context */\n\n  void (*sigfunc)() =  (void (*)())signal( SIGINT, sig_trap );\n\n  if ( !str || !*str )\n  {\n      str = (char *)doread();\n      signal( SIGINT, sigfunc );\n      return math_out_str;\n  }\n\n  savejmp = jmpbuf;\n  jmpbuf = &jmp;\n\n#ifdef DEBUG \n  fprintf( stderr, "got [%s]\\n", str );\n#endif \n  if ( math_out_str ) math_out_str[0] = \'\\0\';\n  math_out_count  = 0;\n\n  /*\n   *   try it\n   */\n  if (*str != \'\\0\')\n  {\n     ALLOC_HEAD = (LIST *)NULL;\n     headsave = (VARIABLE *)VAR_HEAD;\n\n    /*\n     *  normal return takes branch 1,\n     *  error() takes branch 2, \n     *  quit() takes branch 3.\n     */\n    switch (setjmp(*jmpbuf))\n    {\n      case 0:\n        (void)doit( str );\n        longjmp(*jmpbuf, 1);\n      break;\n\n      case 1:\n      break;\n\n      case 2:\n        VAR_HEAD = (LIST *)headsave;\n      break;\n\n      case 3:\n      break;\n    }\n  }\n\n  jmpbuf = savejmp;\n\n  signal( SIGINT, sigfunc );\n\n  return math_out_str;\n}\n\nchar *doread()\n/*======================================================================\n?  doread() is really the main loop of this program. Function reads\n|  it\'s input as strings and gives them to function doit() for\n|  execution. setjmp() function is used for error recovery.\n|\n|  Memory allocated during the lifetime of this function is \n|  collected to a list represented by the global VARIABLE\n|  ALLOCLIST *alloc_list. If function error() is called, this\n|  list is used to deallocte memory. Normally (well I certainly \n|  hope so) functions which allocate memory deallocate it themselves.\n|\n|  Program stays in this function until an end of file -condition\n|  is reached or exit- or quit-commands are given.\n|\n@  jmp_buf *jmpbuf, ALLOC_LIST *alloc_list\n&  ALLOCMEM, FREEMEM, setjmp(), longjmp()\n~  doit(), quit(), error()\n^=====================================================================*/\n{\n  VARIABLE *headsave;            /* this should not be here */\n\n  jmp_buf jmp, *savejmp;         /* save program context */\n\n  char *p, *q;                   /* buffer for input stream */\n\n  savejmp = jmpbuf;\n  jmpbuf = &jmp;\n\n  if ( math_out_str ) math_out_str[0] = \'\\0\';\n  math_out_count  = 0;\n\n  p  = q = ALLOCMEM(4096);\n  /*\n   *   try it\n   */\n  while(dogets(p, PMODE_MAIN))\n  {\n    if (*p != \'\\0\')\n    {\n      ALLOC_HEAD = (LIST *)NULL;\n      headsave = (VARIABLE *)VAR_HEAD;\n\n      /*\n       *  normal return takes branch 1,\n       *  error() takes branch 2, \n       *  quit() takes branch 3.\n       */\n      switch (setjmp(*jmpbuf))\n      {\n        case 0:\n          (void)doit(p);\n          longjmp(*jmpbuf, 1);\n\tbreak;\n\n        case 1:\n\tbreak;\n\n        case 2:\n          VAR_HEAD = (LIST *)headsave;\n        break;\n\n        case 3:\n         goto ret;\n        break;\n      }\n    }\n  }\n\n ret:\n\n  jmpbuf = savejmp;\n\n  FREEMEM(q);\n\n  return math_out_str;\n}\n\nVARIABLE *com_quit()\n/*======================================================================\n?  Quit current doread entry by longjumping back to it (nasty).\n&  longjmp\n~  doread\n^=====================================================================*/\n{\n  longjmp(*jmpbuf, 3);\n\n  return (VARIABLE *)NULL;   /* won\'t be executed (hopefully) */\n}\n\nint dogets(buff, prompt) char *buff; char *prompt;\n/*======================================================================\n?  Get line from input stream. If both input & output streams are \n|  connected to terminal, this function gives user one of three \n|  (default) prompts:\n|\n|     MATC> \n|        - normal prompt                      (PMODE_MAIN)\n|     ....> \n|        - begin end- block is beign defined  (PMODE_BLOCK)\n|     ####>                                   (PMODE_CONT)\n|        - user has given a #-sign as a last character of \n|          previous line, this line will be catenated with it\n|\n|  If current comment character is found from input stream, the\n|  line after this character is discarded. Likewise if current\n|  system command character is found, the rest of the line is\n|  passed to system()-call.\n|\n=  line got -> TRUE, EOF -> FALSE\n!  There should be a way to get an echo when reading from file.\n&  fprintf(), isatty(), fileno(), strlen(), fgets(), system()\n^=====================================================================*/\n{\n   char *ptr = buff, *p;    /* Can\'t get rid of these. */\n\n   if ( !math_in ) return FALSE;\n\n   /* \n       Try figuring out if input & output streams are\n       terminals, if they both are, give user a prompt.\n   */\n   if (isatty(fileno(math_in)) && isatty(fileno(math_out)))\n     PrintOut( "%s", prompt );\n\n   /*\n      i\'m not in the mood to explain this.\n   */\n   *ptr++ = \' \';\n\n   /* \n        Go for it.\n   */\n   while((ptr = fgets(ptr, 256, math_in)) != NULL)\n   {\n\n     ptr[strlen(ptr)-1] = \'\\0\';\n\n     /*\n      *    Check if the user wants to continue with this line.\n      */\n     while(ptr[strlen(ptr)-1] == \'\\\\\')\n     {\n       ptr += strlen(ptr) - 1;\n       dogets(ptr, PMODE_CONT);\n     }\n\n     /* \n      *   if there is only spaces in this line, \n      *   don\'t bother returning it, instead\n      *   let\'s read afresh, otherwise return.\n      */\n     p = ptr; while(isspace(*p)) p++;\n\n     if (*p != \'\\0\')   /* GOOD EXIT HERE */\n     {\n#if 0\n       /* \n        *   Look for the system character, if found\n        *   pass rest of the line to system()-call\n        */\n       for(p = buff; *p; p++)\n       {\n         switch(*p)\n         {\n           case SYSTEM:\n             system(p + 1);\n             PrintOut("\\n");\n             *p = \'\\0\'; p--;\n           break;\n         }\n       }\n#endif\n       if (*buff != \'\\0\')   \n         return TRUE;          /* OR IF WE ARE HONEST, IT\'S HERE */\n     }\n\n     /* \n          if it\'s terminal give a prompt.\n     */\n     if (isatty(fileno(math_in)) && isatty(fileno(math_out)))\n         PrintOut("%s", prompt);\n   }\n\n   return FALSE;\n}\n\n\nvoid com_init(word, flag_pw, flag_ce, sub, minp, maxp, help_text ) \n/*======================================================================\n?  Adds commands to global command list. \n|\n|  Parameters:\n|      char *word \n|         - the keyword user gives for this command to be executed. \n|      int flag_pw \n|         - flag telling if the command can be executed element\n|           by element using function *(*sub)().\n|      int flag_ce\n|         - flag telling if the command can be executed when\n|           preprosessing if constant arguments\n|      double *(*sub)()\n|         - function to be executed when this command is given\n|      int minp, maxp\n|         - maximum and minimum number of parameters to command\n|\n|  The global list of available commands is updated (or created if\n|  nonexistent).\n|\n&  lst_add()\n~  *_com_init()\n^=====================================================================*/\n     char *word; \n     VARIABLE *(*sub)();\n     int minp, maxp, flag_pw, flag_ce;\n     char *help_text;\n{\n  COMMAND *ptr;        /* can\'t get rid of this */\n  \n\n  /* \n     Fill the structure... \n  */\n  ptr = (COMMAND *)ALLOCMEM(COMSIZE);\n  NAME(ptr) = STRCOPY(word);\n  if (flag_pw) \n    ptr->flags |= CMDFLAG_PW;\n  if (flag_ce) \n    ptr->flags |= CMDFLAG_CE;\n  ptr->minp = minp;\n  ptr->maxp = maxp;\n  ptr->sub  = sub;\n  ptr->help = help_text;\n\n  /* \n     ...and update the list. \n  */\n  lst_add(COMMANDS, (LIST *)ptr);\n\n  return;\n}\n\nvoid com_free()  \n/*======================================================================\n?  Deletes the list of commands and frees associated memory.\n|\n&  lst_purge()\n^=====================================================================*/\n{\n  /* \n       Give memory back to system \n  */\n  lst_purge(COMMANDS);\n\n  return;\n}\n\nCOMMAND *com_check(str) char *str;\n/*======================================================================\n?  Look for command from COMMANDS list by name.\n|\n=  COMMAND *NULL if does not exist, pointer to command otherwise\n&  lst_find()\n^=====================================================================*/\n{\n  return (COMMAND *)lst_find(COMMANDS, str);\n}\n\nVARIABLE *com_help( VARIABLE *ptr )\n/*======================================================================\n?  Print list of commands and user defined functions from global lists.\n|\n!  The command to get here is "help" but it really is not very helpful.\n|\n&  lst_print()\n^=====================================================================*/\n{\n   COMMAND  *cmd;\n   FUNCTION *fnc;\n   char *name;\n\n   if ( !ptr )\n   {\n\n       lst_print(COMMANDS);\n       lst_print(FUNCTIONS);\n\n   } else {\n\n      name = var_to_string( ptr );\n\n      if ( (cmd = com_check( name ) ) !=  (COMMAND *)NULL )\n      {\n\n          if ( cmd->help )\n              PrintOut( "\\n%s\\n", cmd->help );\n          else\n              PrintOut( "\\nSorry: no help available on [%s].\\n", name );\n\n      } else if ( (fnc = fnc_check( name ) ) !=  (FUNCTION *)NULL )\n      {\n\n          if ( fnc->help )\n              PrintOut( "\\n%s", fnc->help );\n          else\n              PrintOut( "\\nSorry: no help available on [%s].\\n", name );\n\n      } else {\n\n          error( "help: symbol not found: [%s]\\n", name );\n\n      }\n\n      FREEMEM( name );\n   }\n\n  return (VARIABLE *)NULL;\n}\n\nVARIABLE *com_pointw(sub, ptr)  double (*sub)(); VARIABLE *ptr;\n/*======================================================================\n?  This routine does a function call (*sub)(), for each element in\n|  matrix given by ptr.  \n|\n=  a temporay VARIABLE for which M(res, i, j) = (*sub)(M(ptr, i, j)\n&  var_temp_new(), *(sub)()\n^=====================================================================*/\n{\n  VARIABLE *res,*ptr2; /*  pointer to result structure */\n\n  double *a, *a2, *a3, *b; /* pointer to matrices */\n  int n, m, sz;            /* matrix dimensions   */\n\n  int i;             /* loop index          */\n\n  /* \n     Get space for result and ...\n  */\n  n = NROW(ptr); m = NCOL(ptr);\n  res = var_temp_new(TYPE(ptr) ,n , m);\n\n  sz = n*m;\n  a = MATR(ptr); b = MATR(res);\n  \n  /* \n      ...to action.\n  */\n  ptr2 = NEXT(ptr);\n  if(ptr2)\n  {\n    if(n!=NROW(ptr2)||m!=NCOL(ptr2))\n    {\n      error("Pointwise function arguments must all be of same size.");\n    }\n    a2   = MATR(ptr2);\n\n    ptr2 = NEXT(ptr2);\n    if(ptr2)\n    {\n      if(n!=NROW(ptr2)||m!=NCOL(ptr2))\n      {\n         error("Pointwise function arguments must all be of same size,");\n      }\n      if(NEXT(ptr2))\n      {\n        error("Currently at most three arguments for pointwise functions allowd,sorry.");\n      }\n      a3 = MATR(ptr2);\n      for(i = 0; i < sz; i++) *b++ = (*sub)(*a++,*a2++,*a3++);\n    }\n    else\n    {\n      for(i = 0; i < sz; i++) *b++ = (*sub)(*a++,*a2++);\n    }\n  }\n  else\n  {\n    for(i = 0; i < sz; i++) *b++ = (*sub)(*a++);\n  }\n\n  return res;\n}\n\nVARIABLE *com_el(ptr) VARIABLE *ptr;\n/*======================================================================\n?  Extracts specified elements from a matrix. Indexes are given by two\n|  column vectors. The values of the elements of these vectors give\n|  the required indexes. If there is only one index vector given\n|  it is assumed to be column index and row index is set to scalar 0.\n|\n|  If matrix x is, for example, \n|\n|        1 2\n|        3 4 \n|\n|  you get the first row by \n|\n|        x[0, 0 1]\n|\n|  or by \n| \n|        x(0 1)\n|\n=  A new temporary VARIABLE, whose size equals to\n|  number of row indexes times number of column indexes.\n|  \n&  var_temp_new(), var_delete_temp()\n^=====================================================================*/\n{\n  VARIABLE *res,               /* result ... */\n           *par = NEXT(ptr);   /* pointer to list of VARIABLES */\n                               /* containig indexes            */\n\n  static double defind = 0.0;\n#pragma omp threadprivate (defind)\n  double *ind1 = &defind, *ind2;\n\n  int      i, j, k,      /* loop indexes */\n           rows, cols,   /* no. of rows and columns in the matrix */\n                         /* to be indexed.                        */\n           size1 = 1, size2,\n           ind;\n\n  rows = NROW(ptr); cols = NCOL(ptr);\n\n  /*\n   * check if scalar ....\n   */\n  if (rows == 1 && cols == 1)\n  {\n    if (*MATR(par) != 0) error("Index out of bounds.\\n");\n    if (NEXT(par) != NULL)\n      if (*MATR(NEXT(par)) != 0) error("Index out of bounds.\\n"); \n    res = var_temp_new(TYPE(ptr),1,1);\n    *MATR(res) = *MATR(ptr);\n    return res;\n  }\n\n  /* \n     The matrix will be indexed by two column vectors. \n     If there is just one assume it\'s column index and\n     make rowindex 0.\n  */\n  if (NEXT(par) == NULL)\n  {\n    if (NROW(par) == rows && NCOL(par) == cols)\n    {\n      int logical = TRUE,\n          onecount=0;\n\n      double *dtmp;\n\n      dtmp = MATR(par);\n      for(i = 0; i < NROW(par)*NCOL(par); i++)\n        if (dtmp[i] == 0)\n        {\n        }\n        else if (dtmp[i] == 1)\n        {\n          onecount++;\n        }\n        else\n        {\n          logical = FALSE;\n          break;\n        }\n\n      if (logical)\n      {\n        if (onecount == 0) return NULL;\n\n        res = var_temp_new(TYPE(ptr),1,onecount); \n        for(i=0,k=0; i < rows; i++)\n          for(j=0; j < cols; j++)\n            if (M(par,i,j) == 1)\n            {\n              memcpy(&M(res,0,k++),&M(ptr,i,j),sizeof(double));\n            }\n        return res;\n      }\n    }\n\n    ind2 = MATR(par); size2 = NCOL(par); \n    cols *= rows; rows = 1;\n  }\n  else\n  {\n    ind1 = MATR(par); size1 = NCOL(par);\n    size2 = NCOL(NEXT(par));\n    ind2  = MATR(NEXT(par));\n  }\n\n  /* \n      Space for result  \n  */\n  res = var_temp_new(TYPE(ptr), size1, size2);\n\n  /* \n     Extract the values (try making sense out of that\n     if you feel like it).\n  */\n  for(i = 0; i < size1; i++)\n  {\n    ind = (int)ind1[i];\n    for(j = 0; j < size2; j++)\n      if (ind < rows && (int)ind2[j] < cols)\n        memcpy(&M(res,i,j),&M(ptr,ind,(int)ind2[j]),sizeof(double));\n      else\n        error("Index out of bounds.\\n");\n  }\n\n  return res;\n}\n\nVARIABLE *com_source(ptr) VARIABLE *ptr;\n/*======================================================================\n?  Redirect input stream to a file, whose name is given.\n|\n@  FILE *math_in\n&  ALLOCMEM, FREEMEM, fopen(), fclose(), error()\n^=====================================================================*/\n{\n  char *name;               /* Hold converted string (file name) */\n\n  FILE *save_in = math_in;  /* Save previous input stream until  */\n                            /* we are done with the new file.    */\n\n  /*\n      convert the file name from ptr.\n  */\n  name = var_to_string(ptr);\n\n  /*\n      Execute the file.\n  */\n  if ((math_in = fopen(name,"r")) != NULL)\n  {\n/*   PrintOut("Executing commands from file, %s...\\n", name); */\n     doread();\n     fclose(math_in);\n  }\n  else\n  {\n    PrintOut( "Source: Can\'t open file, %s.\\n",name );\n  }\n\n  math_in = save_in;\n  FREEMEM(name);\n\n  return (VARIABLE *)NULL;\n}\n\n\nVARIABLE *com_apply(ptr) VARIABLE *ptr;\n/*======================================================================\n?  Executes given string.\n|\n&  ALLOCMEM, FREEMEM, doit()\n^=====================================================================*/\n{\n  VARIABLE *res;        /* result pointer */\n\n  char *p, *q;          /* holds the string to be executed, after */\n                        /* conversion from structure VARIABLE *   */\n\n  int i, j;             /* just loop indexes */\n\n\n  /* \n      Allocate space for the string... \n  */\n  p = q = ALLOCMEM(NROW(ptr) * NCOL(ptr) + 1);\n\n  /*\n      ... convert it ... \n  */\n  for(i = 0; i < NROW(ptr); i++)\n    for(j = 0; j < NCOL(ptr); j++) \n      *p++ = (char)M(ptr,i,j);\n\n  *p = \'\\0\';\n\n  /*\n      ... and try executing it. \n  */\n  res = doit( q ); \n  \n  FREEMEM(q);\n\n  return res;\n}\n\nvoid mem_free(void *mem)\n/*======================================================================\n?  Free memory given by argument, and unlink it from alloction list.\n|  Currently FREEMEM(ptr) is defined to be mem_free(ptr).\n|\n&  free()\n~  mem_alloc(), mem_free_all()\n^=====================================================================*/\n{\n  ALLOC_LIST *lst;\n\n#ifdef DEBUG\n  tot--; fprintf(fplog,"free addr: %d total: %d\\n", ALLOC_LST(mem), tot);\n  fflush( fplog );\n#endif\n  /*\n      if the list is empty return\n  */\n  if ( (lst = (ALLOC_LIST *)ALLOC_HEAD) == (ALLOC_LIST *)NULL )\n  {\n#if 1\n/* ????? */\n     free( ALLOC_LST(mem) );\n#else\nfprintf( stderr, "SHOULD THIS HAPPEN ????\\n" );\n#endif\n    return;\n  }\n \n  /*\n   *  it\'s not the header, look if it\'s in list at all  \n   */\n  if (ALLOC_PTR(lst) != mem)\n  {\n\n    for(; NEXT(lst); lst = NEXT(lst))\n    {\n      if (ALLOC_PTR(NEXT(lst)) == mem) break;\n    }\n\n    /*\n     *  item was not found from the list. free ptr and return.\n     */\n    if (NEXT(lst) == (ALLOC_LIST *)NULL)\n    {\n      free(ALLOC_LST(mem));\n      return;\n    }\n\n    /*\n     *   unlink\n     */\n    NEXT(lst) = NEXT(NEXT(lst));\n  }\n\n  /*\n   *  item was the header, unlink it    \n   */\n  else\n    ALLOC_HEAD = NEXT(ALLOC_HEAD);\n\n  /*\n   *  and at last return memory back to system\n   */\n  free(ALLOC_LST(mem));\n\n  return;\n}\n\nvoid mem_free_all()\n/*======================================================================\n?  Free all memory allocated since last entry of doread.\n|  (actually free all memory from list ALLOCATIONS).\n|\n~  mem_alloc(), mem_free(), doread(), error()\n^=====================================================================*/\n{\n  ALLOC_LIST *lst, *lstn; \n\n  for(lst = (ALLOC_LIST *)ALLOC_HEAD; lst;)\n  {\n#ifdef DEBUG\n  tot--; fprintf(fplog,"freeall addr: %d total: %d\\n", lst, tot);\n  fflush( fplog );\n#endif\n    lstn = NEXT(lst);\n    free( (char *)lst );\n    lst = lstn;\n  }\n\n  ALLOC_HEAD = (LIST *)NULL;  /* security */\n\n  return;\n}\n\nvoid *mem_alloc(size) size_t size;\n/*======================================================================\n?  Allocate memory and link it to  memory allocation list.\n|\n~   calloc(), free(), error()\n^=====================================================================*/\n{\n  ALLOC_LIST *lst;\n\n  /* \n   *    try allocating memory \n   */\n  if ((lst = (ALLOC_LIST *)calloc(size+sizeof(ALLOC_LIST), 1)) != NULL)\n  {\n    NEXT(lst) = (ALLOC_LIST *)ALLOC_HEAD; ALLOC_HEAD = (LIST *)lst;\n  }\n  else\n    error("Can\'t alloc mem.\\n");\n\n#ifdef DEBUG\n  tot++; fprintf(fplog,"alloc addr: %d size: %d total: %d\\n", \n                          lst, size, tot);\n  fflush( fplog );\n#endif\n  return ALLOC_PTR(lst);\n}\n'}, {'path': 'matc/src/main.c', 'sha256': 'bf4b38611b453d41ff9635d34ad4214f894773d8e3ed5cfdce8f99e3e9f0cbb0', 'patched_sha256': 'a42e83b2e6426c559d8207823eef6cc2983bed533ed6ca42e1d56a62354cc8c9', 'content': '/*****************************************************************************\n *\n *  Elmer, A Finite Element Software for Multiphysical Problems\n *\n *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n * \n * This library is free software; you can redistribute it and/or\n * modify it under the terms of the GNU Lesser General Public\n * License as published by the Free Software Foundation; either\n * version 2.1 of the License, or (at your option) any later version.\n *\n * This library is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\n * Lesser General Public License for more details.\n * \n * You should have received a copy of the GNU Lesser General Public\n * License along with this library (in file ../LGPL-2.1); if not, write \n * to the Free Software Foundation, Inc., 51 Franklin Street, \n * Fifth Floor, Boston, MA  02110-1301  USA\n *\n *****************************************************************************/\n\n\n#include <stdio.h>\n#include <signal.h>\n#include <string.h>\n#include "../config.h"\n\n#ifdef USE_READLINE\n# ifdef HAVE_READLINE_READLINE_H\n#  include <readline/readline.h>\n#  include <readline/history.h>\n# else\n#  ifdef HAVE_READLINE_H\n#   include <readline.h>\n#   include <history.h>\n#  endif\n# endif\n#endif \n\n/* prototype */\nchar *mtc_domath(char *);\nvoid mtc_init(FILE *, FILE *, FILE *);\n#ifdef _OPENMP\n#include <omp.h>\n#endif\n\nint main( int argc, char **argv )\n{\n  char strt[2000];\n  char *str;\n  char *ioptr;\n  \n#ifdef _OPENMP\n  /* Set number of threads to 1, computations are single threaded anyway */\n  omp_set_num_threads(1);\n#endif\n\n  (void)mtc_init( stdin, stdout, stderr );\n  str = mtc_domath( "source(\\"mc.ini\\")" );\n\n  signal( SIGINT, SIG_IGN );\n\n  while( 1 )\n  {\n#ifdef USE_READLINE\n      str = readline ("MATC> ");\n      /* add to history */\n      if (str && *str)\n\tadd_history (str);\n\n#else\n      ioptr = fgets( strt,  2000 , stdin);\n      str = strt;      \n#endif\n      \n/* kludge to enable exit. */\n#if defined(WIN32) || defined(MINGW32)\n      if( stricmp(str,"exit") == 0  || stricmp(str,"quit") == 0 )\n#else\n      if( strcasecmp(str,"exit") == 0  || strcasecmp(str,"quit") == 0 )\n#endif\n      {\n\treturn 0;\n      }\n      if ( *str ) fprintf( stdout, "%s\\n", mtc_domath( str ) );\n      \n#ifdef USE_READLINE\n      free(str);\n#endif\n    }  \n    return 0;\n}\n'}, {'path': 'fem/src/Load.c', 'sha256': '37cdfda567b1716229c48468c9df17eb73475c9dba814393e44924dd521af8e9', 'patched_sha256': '715678a2794e32a5bc62bb8a7109878db4cb2d5c8c381e37435d4e667f30874f', 'content': '/*****************************************************************************\n! *\n! *  Elmer, A Finite Element Software for Multiphysical Problems\n! *\n! *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n! * \n! *  This library is free software; you can redistribute it and/or\n! *  modify it under the terms of the GNU Lesser General Public\n! *  License as published by the Free Software Foundation; either\n! *  version 2.1 of the License, or (at your option) any later version.\n! *\n! *  This library is distributed in the hope that it will be useful,\n! *  but WITHOUT ANY WARRANTY; without even the implied warranty of\n! *  MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\n! *  Lesser General Public License for more details.\n! * \n! *  You should have received a copy of the GNU Lesser General Public\n! *  License along with this library (in file ../LGPL-2.1); if not, write \n! *  to the Free Software Foundation, Inc., 51 Franklin Street, \n! *  Fifth Floor, Boston, MA  02110-1301  USA\n! *\n! ******************************************************************************\n! *\n! *  Utilities for dynamic loading of user functions, and other operating\n! *  system interfaces.\n! *\n! ******************************************************************************\n! *\n! *  Authors: Juha Ruokolainen\n! *  Email:   Juha.Ruokolainen@csc.fi\n! *  Web:     http://www.csc.fi/elmer\n! *  Address: CSC - IT Center for Science Ltd.\n! *           Keilaranta 14\n! *           02101 Espoo, Finland \n! *\n! *  Original Date: 02 Jun 1997\n! *\n! *****************************************************************************/\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n/* #include <elmer/matc.h> maybe in the future */\n\n/* eg. FC_CHAR_PTR and FC_FUNC is defined here */\n\n#include "../config.h"\nvoid var_copy_transpose(char *name, double *values, int nrows, int ncols);\n\n#if defined(WIN32) | defined(MINGW32)\n#  include <direct.h>\n#  include <windows.h>\n#define ELMER_PATH_SEPARATOR ";"\n#else\n#include <strings.h>\n#  include <dlfcn.h>\n#  include <sys/stat.h>\n#define ELMER_PATH_SEPARATOR ":"\n#endif\n\n#define MAX_PATH_LEN 512\n#define ERROR_BUF_LEN 10*MAX_PATH_LEN\n\n#ifndef USE_ISO_C_BINDINGS\n#ifdef SGI64\nvoid corename_()\n{\n#include <sys/types.h>\n#include <sys/resource.h>\n#include <sys/prctl.h>\n\n prctl( PR_COREPID,0,0 );\n}\n#endif\n#endif\n\n/* pc needs more bits on 64bit arch  */\n#ifdef ARCH_32_BITS\n#define f_ptr int32_t *\n#else \n#define f_ptr int64_t *\n#endif\n\n/*#if defined(MINGW32)*/\n/*--------------------------------------------------------------------------\n  work around mingw rxvt shell stdio/err buffering troubles\n  -------------------------------------------------------------------------*/\n/*void STDCALLBULL FC_FUNC_(set_stdio_bufs,SET_STDIO_BUFS) ()*/\n/*[>void set_stdio_bufs_()<]*/\n/*{*/\n   /*setvbuf( stdout, NULL, _IOLBF, 2048 );*/\n   /*setvbuf( stderr, NULL, _IONBF, 2048 );*/\n/*}*/\n/*#endif*/\n\n/*--------------------------------------------------------------------------\n  This routine will return the home directory of elmer solver.\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL getsolverhome( char *solverDir, int *len)\n#else\nvoid STDCALLBULL FC_FUNC(getsolverhome,GETSOLVERHOME) \n     ( char *solverDir, int *len)\n#endif\n{\n  *len = 0;\n\n  char *elmer_home = getenv("ELMER_HOME");\n\n  if(elmer_home != NULL) {\n    /* Return solver home relative to ELMER_HOME*/\n#if defined(WIN32) || defined(MINGW32)\n    _snprintf(solverDir, MAX_PATH_LEN, "%s\\\\share\\\\elmersolver", elmer_home);\n#else\n    snprintf(solverDir, MAX_PATH_LEN, "%s/share/elmersolver", elmer_home);\n#endif\n    *len = strlen(elmer_home) + 18;\n    if(*len > MAX_PATH_LEN) *len = MAX_PATH_LEN;\n    return;\n  }\n\n#if defined(WIN32) || defined(MINGW32)\n  static char appPath[MAX_PATH_LEN] = "";\n  static char appDir[MAX_PATH_LEN] = "";\n  char *exeName = NULL;\n  int n = 0;\n\n  /* Get the full module file name  */\n  GetModuleFileName(NULL, appPath, MAX_PATH_LEN);\n  if(appPath == NULL) return;\n  exeName = strrchr(appPath, \'\\\\\');\n  if(exeName == NULL) return;\n  n = (int)(exeName - appPath);\n  if(n < 0) return; /* play safe */\n  if(n > MAX_PATH_LEN) n = MAX_PATH_LEN;\n\n  /* This is where the executable resides */\n  strncpy(appDir, appPath, n);\n\n  /* Return solver home relative to appDir */\n  _snprintf(solverDir, MAX_PATH_LEN, "%s\\\\..\\\\share\\\\elmersolver", appDir);\n  *len = n + 21;\n  if(*len > MAX_PATH_LEN) *len = MAX_PATH_LEN;\n#else\n\n  /* Use the directory defined in config.h */\n  snprintf(solverDir, MAX_PATH_LEN, "%s", ELMER_SOLVER_HOME);\n  *len = strlen(ELMER_SOLVER_HOME);\n  if(*len > MAX_PATH_LEN) *len = MAX_PATH_LEN;\n#endif\n}\n\n/*--------------------------------------------------------------------------\n  This routine will create a directory given name of the directory.\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL makedirectory(char *Name)\n#else\nvoid STDCALLBULL FC_FUNC(makedirectory,MAKEDIRECTORY)\n     (char *Name)\n#endif\n{\n#if defined(WIN32) || defined(MINGW32)\n    if ( _mkdir( Name ) != 0 ) {\n#else\n    if ( mkdir( Name, 0700 ) != 0 ) {\n      chmod( Name, 0700 );\n#endif\n    }\n}\n\n#ifndef USE_ISO_C_BINDINGS\n/*--------------------------------------------------------------------------\n  This routine execute a operating system command.\n  -------------------------------------------------------------------------*/\nvoid STDCALLBULL FC_FUNC(systemc,SYSTEMC) ( char *str )\n{\n   system( str );\n}\n\n/*--------------------------------------------------------------------------\n  This routine will return value of a environment variable to a\n  given string variable.\n  -------------------------------------------------------------------------*/\nvoid STDCALLBULL FC_FUNC(envir,ENVIR) (char *Name, char *Value, int *len)\n{\n    if ( getenv( Name ) ) {\n      strncpy( Value,(char *)getenv(Name), MAX_PATH_LEN );\n      *len = strlen( Value );\n    } else {\n      *len = 0;\n      *Value = \'\\0\';\n    }\n}\n#endif\n\n/*--------------------------------------------------------------------------\n  Internal: convert function names into to fortran mangled form for dynamical\n  loading\n  ---------------------------------------------------------------------------*/\nstatic void STDCALLBULL fortranMangle(char *orig, char *mangled)\n{\n  int uscore, i;\n  \n  strcpy( mangled, orig );\n\n  if(ELMER_LINKTYP == 1 || ELMER_LINKTYP == 3 || ELMER_LINKTYP == 4)\n  {\n    for( i=0 ; i<strlen(mangled) ; i++ ) /* to lower case */\n    {\n      if ( mangled[i] >= \'A\'  && mangled[i] <= \'Z\' ) \n\tmangled[i] += \'a\' - \'A\';\n    }\n  }\n  if(ELMER_LINKTYP == 2)\n  {\n    for( i=0; i<strlen(mangled); i++ ) /* to upper case */\n    {\n      if ( mangled[i] >= \'a\'  && mangled[i] <= \'z\' ) \n\tmangled[i] += \'A\' - \'a\';\n    }\n  }\n  \n  if(ELMER_LINKTYP == 1) /* underscore */\n  {\n      strcat( mangled, "_" );\n  }\n  else if(ELMER_LINKTYP == 4) /* 1-2 underscores  */\n  {\n    uscore = 0;\n    for( i=0; i<strlen(mangled); i++ )\n      if(mangled[i] == \'_\')\n\tuscore++;\n    \n    if(uscore == 0)\n    {\n      strcat( mangled, "_" );\n    } \n    else \n    {\n      strcat( mangled, "__" );\n    }\n  }\n\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: Appends two paths with slash checking\n  Args: path1, path2 - string to join\n -------------------------------------------------------------------------*/\nstatic void STDCALLBULL append_path(char *path1, char *path2)\n{\n    size_t len1;\n\n    len1 = strnlen(path1, 2*MAX_PATH_LEN);\n#if defined(WIN32) || defined(MINGW)\n    if (path1[len1-1] != \'\\\\\') {\n        strncat(path1, "\\\\", 2*MAX_PATH_LEN);\n    }\n#else\n    if (path1[len1-1] != \'/\') {\n        strncat(path1, "/", 2*MAX_PATH_LEN);\n    }\n#endif\n    strncat(path1, path2, 2*MAX_PATH_LEN);\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: Tries to open library with dlopen, first without\n            any extensions and then with SHL_EXTENSION.\n  Args: Libname - name of the library file\n        Handle - handle to the dl, NULL if fails\n        error_buf - string buffer for error messages\n -------------------------------------------------------------------------*/\nstatic void STDCALLBULL try_dlopen(char *LibName, void **Handle, char *errorBuf)\n{\n    static char dl_names[2][2*MAX_PATH_LEN];\n    char error_tmp[MAX_PATH_LEN];\n    int i;\n\n    strncpy(dl_names[0], LibName, 2*MAX_PATH_LEN);\n    strncpy(dl_names[1], LibName, 2*MAX_PATH_LEN);\n\n    strncat(dl_names[1], SHL_EXTENSION, MAX_PATH_LEN);\n\n    for (i = 0; i < 2; i++) {\n#ifdef HAVE_DLOPEN_API\n        if ((*Handle = dlopen(dl_names[i], RTLD_NOW)) == NULL) {\n            strncat(errorBuf, dlerror(), MAX_PATH_LEN);\n            strncat(errorBuf, "\\n", MAX_PATH_LEN);\n        } else {\n            break;\n        }\n#elif defined(HAVE_LOADLIBRARY_API)\n        if ((*Handle = LoadLibrary(dl_names[i])) == NULL) {\n            sprintf(error_tmp, "Can not find %s.\\n", dl_names[i]);\n            strncat(errorBuf, error_tmp, ERROR_BUF_LEN);\n        } else {\n            break;\n        }\n#endif\n    }\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: Parses the search path and tries to open a solver.\n            First search is done without any path prefixes.\n  Args: SearchPath - colon separated list of searhc paths\n        Library - name of the library file to be opened\n        Handle - handle to the dl file, NULL if fails\n        error_buf - string buffer for error messages\n --------------------------------------------------------------------------*/\nstatic void STDCALLBULL\ntry_open_solver(char *SearchPath, char *Library, void **Handle, char *errorBuf)\n{\n    static char CurrentLib[2*MAX_PATH_LEN];\n    char *tok;\n\n    /* Try to open first without any prefixes */\n    try_dlopen(Library, Handle, errorBuf);\n\n    /* and then using the provided paths */\n    if (*Handle == NULL) {\n\n        tok = strtok(SearchPath, ELMER_PATH_SEPARATOR);\n        while (tok != NULL) {\n            strncpy(CurrentLib, tok, 2*MAX_PATH_LEN);\n            append_path(CurrentLib, Library);\n\n            try_dlopen(CurrentLib, Handle, errorBuf);\n            if (*Handle != NULL)\n                break;\n            tok = strtok(NULL, ELMER_PATH_SEPARATOR);\n        }\n    }\n}\n\n/*--------------------------------------------------------------------------\n  This routine will return address of a function given path to a dynamically\n  loaded library and name of the routine.\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid *STDCALLBULL loadfunction_c( int *Quiet, int *abort_not_found, char *Library, char *Name )\n#else\nvoid *STDCALLBULL FC_FUNC(loadfunction,LOADFUNCTION) ( int *Quiet, int *abort_not_found,\n                                                       char *Library, char *Name )\n#endif\n{\n/*--------------------------------------------------------------------------*/\n   void (*Function)(),*Handle;\n   char *cptr;\n   static char ElmerLib[2*MAX_PATH_LEN], NewLibName[3*MAX_PATH_LEN],\n               NewName[MAX_PATH_LEN], ErrorBuffer[ERROR_BUF_LEN];\n/*--------------------------------------------------------------------------*/\n   static char appPath[MAX_PATH_LEN] = "";\n   char *exeName = NULL;\n   int n = 0;\n/*--------------------------------------------------------------------------*/\n   memset(appPath, 0, MAX_PATH_LEN);\n   memset(ElmerLib, 0, 2*MAX_PATH_LEN);\n   memset(NewLibName, 0, 3*MAX_PATH_LEN);\n   memset(NewName, 0, MAX_PATH_LEN);\n   memset(ErrorBuffer, 0, ERROR_BUF_LEN);\n/*--------------------------------------------------------------------------*/\n   fortranMangle( Name, NewName );\n   strncpy( NewLibName, Library, 3*MAX_PATH_LEN );\n\n   if ( *Quiet==0 ) {\n     fprintf(stdout,"Loading user function library: [%s]...[%s]\\n", Library, Name );\n     fflush(stdout);\n   }\n\n   /* First path is always current directory (.) */\n   strncpy(ElmerLib, ".", 2*MAX_PATH_LEN);\n   cptr = (char *)getenv( "ELMER_LIB" );\n   if ( cptr != NULL ) {\n      strncat( ElmerLib, ELMER_PATH_SEPARATOR, 2*MAX_PATH_LEN );\n      strncat( ElmerLib, cptr, 2*MAX_PATH_LEN );\n   } else {\n      cptr = (char *)getenv("ELMER_HOME");\n      if ( cptr != NULL  ) {\n         strncat( ElmerLib, ELMER_PATH_SEPARATOR, 2*MAX_PATH_LEN);\n         strncat( ElmerLib, cptr, 2*MAX_PATH_LEN );\n         strncat( ElmerLib, "/share/elmersolver/lib", 2*MAX_PATH_LEN );\n      } else {\n#if defined(WIN32) || defined(MINGW32)\n\t/* Should not get here unless WIN32 implements DLOPEN_API */\n\tGetModuleFileName(NULL, appPath, MAX_PATH_LEN);\n\texeName = strrchr(appPath, \'\\\\\');\n\tn = (int)(exeName - appPath);\n\tif(n < 0) n = 0;\n\tif(n > MAX_PATH_LEN) n = MAX_PATH_LEN;\n        strncat(ElmerLib, ELMER_PATH_SEPARATOR, 2*MAX_PATH_LEN);\n\tstrncat(ElmerLib, appPath, n);\n\tstrncat(ElmerLib, "\\\\..\\\\share\\\\elmersolver\\\\lib", 2*MAX_PATH_LEN);\n#else\n        strncat( ElmerLib, ELMER_PATH_SEPARATOR, 2*MAX_PATH_LEN );\n\tstrncat( ElmerLib, ELMER_SOLVER_HOME, 2*MAX_PATH_LEN );\n\tstrncat( ElmerLib, "/lib", 2*MAX_PATH_LEN );\n#endif\n      }\n   }\n\n   cptr = (char *)getenv( "ELMER_MODULES_PATH" );\n   if ( cptr != NULL ) {\n      strncat( ElmerLib, ELMER_PATH_SEPARATOR, 2*MAX_PATH_LEN);\n      strncat( ElmerLib, cptr, 2*MAX_PATH_LEN);\n   }\n\n   try_open_solver(ElmerLib, Library, &Handle, ErrorBuffer);\n   if ( Handle == NULL ) {\n      fprintf(stderr, "%s", ErrorBuffer);\n      exit(0);\n   }\n   \n#ifdef HAVE_DLOPEN_API\n\n   if ( (Function = (void(*)())dlsym( Handle,NewName)) == NULL && *abort_not_found )\n   {\n      fprintf( stderr, "Load: FATAL: Can\'t find procedure [%s]\\n", NewName );\n      exit(0);\n   }\n\n#elif defined(HAVE_LOADLIBRARY_API)\n\n   if ( (Function = (void *)GetProcAddress(Handle,NewName)) == NULL && *abort_not_found )\n   {\n     fprintf( stderr,"Load: FATAL: Can\'t find procedure [%s]\\n", NewName );\n     exit(0);\n   }\n\n#endif\n\n   return (void *)Function;\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: Execute given function returning integer value\n  -------------------------------------------------------------------------*/\nstatic int IntExec( int (STDCALLBULL *Function)(),void *Model )\n{\n   return (*Function)( Model );\n}\n\n/*--------------------------------------------------------------------------\n   Execute given function returning integer value\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nint STDCALLBULL execintfunction_c( f_ptr Function,void *Model )\n#else\nint STDCALLBULL FC_FUNC(execintfunction,EXECINTFUNCTION) ( f_ptr Function,void *Model )\n#endif\n{\n  return IntExec( (int (STDCALLBULL *)())*Function,Model );\n}\n\n/*--------------------------------------------------------------------------\n   INTERNAL: Execute given function returning double value\n  -------------------------------------------------------------------------*/\nstatic void DoubleArrayExec( double *(STDCALLBULL *Function)(), void *Model,\n               int *Node, double *Value, double *Array )\n{\n   (*Function)( Model,Node,Value,Array );\n}\n\n/*--------------------------------------------------------------------------\n   Execute given function returning double value\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL execrealarrayfunction_c( f_ptr Function, void *Model,\n\t\t\t\t\t\t\t\t\t\tint *Node, double *Value, double *Array )\n#else\nvoid STDCALLBULL FC_FUNC(execrealarrayfunction,EXECREALARRAYFUNCTION)\n     ( f_ptr Function, void *Model,\n       int *Node, double *Value, double *Array )\n#endif\n{\n   DoubleArrayExec( (double*(STDCALLBULL *)())*Function,Model,Node,Value, Array );\n}\n\n/*--------------------------------------------------------------------------\n   INTERNAL: Execute given function returning double value\n  -------------------------------------------------------------------------*/\nstatic double DoubleExec( double (STDCALLBULL *Function)(), void *Model,\n               int *Node, double *Value )\n{\n   return (*Function)( Model,Node,Value );\n}\n\n/*--------------------------------------------------------------------------\n   Execute given function returning double value\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\ndouble STDCALLBULL execrealfunction_c( f_ptr Function, void *Model,\n\t\t\t\t\t\t\t\t\t int *Node, double *Value )\n#else\ndouble STDCALLBULL FC_FUNC(execrealfunction,EXECREALFUNCTION)\n     ( f_ptr Function, void *Model,\n       int *Node, double *Value )\n#endif\n{\n   return DoubleExec( (double (STDCALLBULL *)())*Function,Model,Node,Value );\n}\n\n/*--------------------------------------------------------------------------\n   INTERNAL: Execute given function returning double value\n  -------------------------------------------------------------------------*/\nstatic double ConstDoubleExec( double (STDCALLBULL *Function)(), void *Model,\n\t\t\t       double *x, double *y, double *z )\n{\n   return (*Function)( Model, x,y,z );\n}\n\n/*--------------------------------------------------------------------------\n   Execute given function returning double value\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\ndouble STDCALLBULL execconstrealfunction_c( f_ptr Function, void *Model,\n\t\t\t\t\t\t\t\t\t\t  double *x, double *y, double *z )\n#else\ndouble STDCALLBULL FC_FUNC(execconstrealfunction,EXECCONSTREALFUNCTION)\n     ( f_ptr Function, void *Model,\n       double *x, double *y, double *z )\n#endif\n{\n   return ConstDoubleExec( (double (STDCALLBULL *)())*Function,Model,x,y,z );\n}\n\n\n/*--------------------------------------------------------------------------\n   Return argument (just to fool Fortran type checking)\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid *STDCALLBULL addrfunc_c( void *Function )\n#else\nvoid *STDCALLBULL FC_FUNC(addrfunc,ADDRFUNC) ( void *Function )\n#endif\n{\n   return (void *)Function;\n}\n\n/*--------------------------------------------------------------------------\n   INTERNAL: Call solver routines at given address\n  -------------------------------------------------------------------------*/\nstatic void DoExecSolver(\n  void (STDCALLBULL *SolverProc)(), void *Model, void *Solver, void *dt, void *Transient)\n{\n  (*SolverProc)( Model,Solver,dt,Transient ); \n  return;\n}\n\n/*--------------------------------------------------------------------------\n   Call solver routines at given address\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL execsolver_c( f_ptr *SolverProc, void *Model, void *Solver,\n\t\t\t\t\t\t\t\tvoid *dt, void *Transient )\n#else\nvoid STDCALLBULL FC_FUNC(execsolver,EXECSOLVER)\n     ( f_ptr *SolverProc, void *Model, void *Solver, void *dt, void *Transient )\n#endif\n{\n  DoExecSolver( (void (STDCALLBULL *)())*SolverProc,Model,Solver,dt,Transient );\n}\n\n/*--------------------------------------------------------------------------\n   INTERNAL: Call lin. solve routines at given address\n  -------------------------------------------------------------------------*/\nstatic int DoLinSolveProcs(\n  int (STDCALLBULL *SolverProc)(), void *Model, void *Solver, void *Matrix, void *b, \n                void *x, void *n, void *DOFs, void *Norm )\n{\n   return (*SolverProc)( Model,Solver,Matrix,b,x,n, DOFs,Norm );\n}\n\n\n/*--------------------------------------------------------------------------\n   Call lin. solver routines at given address\n   -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nint STDCALLBULL execlinsolveprocs_c( f_ptr *SolverProc, void *Model, void *Solver,\n\t\t\t\t\t\tvoid *Matrix, void *b, void *x, void *n, void *DOFs, void *Norm )\n#else\nint STDCALLBULL FC_FUNC(execlinsolveprocs,EXECLINSOLVEPROCS)\n     ( f_ptr *SolverProc, void *Model, void *Solver, void *Matrix, void *b, void *x, void *n, void *DOFs, void *Norm )\n#endif\n{\n   return DoLinSolveProcs( (int (STDCALLBULL *)())*SolverProc,Model,Solver,Matrix,b,x,n,DOFs,Norm );\n}\n\nchar *mtc_domath(char *);\nvoid mtc_init(FILE *,FILE *, FILE *);\n\n/*--------------------------------------------------------------------------\n  This routine will call matc and return matc variable array values\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL matc_get_array(char *name, double *values, int *nrows, int *ncols )\n#else\nvoid STDCALLBULL FC_FUNC_(matc_get_array,MATC_GET_ARRAY) (char *name, \n           double *values, int *nrows, int *ncols )\n#endif\n{\n  var_copy_transpose(name,values,*nrows,*ncols);\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call matc and return matc result\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL matc( char *cmd, char *Value, int *len )\n#else\nvoid STDCALLBULL FC_FUNC(matc,MATC) ( char *cmd, char *Value, int *len )\n#endif\n{\n#define MAXLEN 8192\n\n  static int been_here = 0;\n  char *ptr, c, cc[32];\n  int slen, start;\n#pragma omp threadprivate(been_here)\n\n  /* MB: Critical section removed since Matc library\n   * modified to be thread safe */\n\n   slen = *len;\n   if ( been_here==0 ) {\n     mtc_init( NULL, stdout, stderr ); \n     strcpy( cc, "format( 12,\\"rowform\\")" );\n     mtc_domath( cc );\n     been_here = 1;\n   }\n\n  c = cmd[slen];\n  cmd[slen] = \'\\0\';\n\n  start = 0;\n  if (strncmp(cmd,"nc:",3)==0) start=3;\n\n  ptr = (char *)mtc_domath(&cmd[start]);\n  if ( ptr )\n  {\n    strcpy( Value, (char *)ptr );\n    *len = strlen(Value)-1; /* ignore linefeed! */\n\n    if ( strncmp(Value, "MATC ERROR:",11)==0 || strncmp(Value,"WARNING:",8)==0 ) {\n      if (start==0) {\n          fprintf( stderr, "Solver input file error: %s\\n", Value );\n          fprintf( stderr, "...offending input line: %s\\n", cmd );\n          exit(0);\n      } else {\n        Value[0]=\' \';\n        *len = 0;\n        }\n    }\n  } else {\n    *len = 0;\n    *Value = \' \';\n  }\n  cmd[slen]=c;\n  }\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute user material function\n  -------------------------------------------------------------------------*/\nstatic double DoViscFunction(double (STDCALLBULL *SolverProc)(), void *Model, void *Element, void *Nodes, void *n,\n     void *Basis, void *GradBasis, void *Viscosity, void *Velo, void *GradV )\n{\n   double s;\n   s = (*SolverProc)( Model,Element,Nodes,n,Basis,GradBasis,\n                   Viscosity, Velo, GradV );\n   return s;\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call user defined material def. function\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\ndouble STDCALLBULL materialuserfunction_c( f_ptr Function, void *Model, void *Element,\n\t\tvoid *Nodes, void *n, void *nd, void *Basis, void *GradBasis, void *Viscosity, void *Velo, void *gradV )\n#else\ndouble STDCALLBULL FC_FUNC(materialuserfunction,MATERIALUSERFUNCTION)\n  ( f_ptr Function, void *Model, void *Element, void *Nodes, void *n, void *nd, void *Basis, void *GradBasis, void *Viscosity, void *Velo, void *gradV )\n#endif\n{\n   return DoViscFunction( (double (STDCALLBULL *)())*Function,Model,Element,Nodes,n,Basis,\n                  GradBasis,Viscosity,Velo,gradV );\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute user material function\n  -------------------------------------------------------------------------*/\nstatic void DoSimulationProc( void (STDCALLBULL *SimulationProc)(), void *Model )\n{ \n  (*SimulationProc)( Model ); \n}\n\n/*--------------------------------------------------------------------------\n  This routine will call user defined material def. function\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL execsimulationproc_c( f_ptr Function, void *Model )\n#else\nvoid STDCALLBULL FC_FUNC(execsimulationproc,EXECSIMULATIONPROC)\n     ( f_ptr Function, void *Model )\n#endif\n{\n   DoSimulationProc( (void (STDCALLBULL *)())*Function,Model );\n}\n\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute (Krylov) iterator \n  -------------------------------------------------------------------------*/\nstatic void DoIterCall( void (STDCALLBULL *iterProc)(),\n       void *x,void *b,void *ipar,void *dpar,void *work,\n       void (STDCALLBULL *mvProc)(),\n       void (STDCALLBULL *pcondProc)(),\n       void (STDCALLBULL *pcondrProc)(),\n       void (STDCALLBULL *dotProc)(),\n       void (STDCALLBULL *normProc)(),\n       void (STDCALLBULL *STOPC)() )\n{ \n  (*iterProc)( x,b,ipar,dpar,work,mvProc,pcondProc, \n       pcondrProc,dotProc,normProc,STOPC );\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call (Krylov) iterator\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL itercall_c( f_ptr iterProc, void *x, void *b, void *ipar, void *dpar, void *work,\n       f_ptr mvProc, f_ptr pcondProc, f_ptr pcondrProc, f_ptr dotProc, f_ptr normProc, f_ptr STOPC )\n#else\nvoid STDCALLBULL FC_FUNC(itercall,ITERCALL)\n     ( f_ptr iterProc, void *x, void *b, void *ipar, void *dpar, void *work, \n       f_ptr mvProc, f_ptr pcondProc, f_ptr pcondrProc, f_ptr dotProc, f_ptr normProc, f_ptr STOPC )\n#endif\n{\n   DoIterCall( (void (STDCALLBULL *)())*iterProc,x,b,ipar,dpar,work,\n       (void (STDCALLBULL *)())*mvProc, \n       (void (STDCALLBULL *)())*pcondProc,\n       (void (STDCALLBULL *)())*pcondrProc,\n       (void (STDCALLBULL *)())*dotProc,\n       (void (STDCALLBULL *)())*normProc,\n       (void (STDCALLBULL *)())*STOPC );\n}\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute localmatrix call\n  -------------------------------------------------------------------------*/\nstatic void DoLocalCall( void (STDCALLBULL *localProc)(),\n  void *Model,void *Solver,void *G, void *F, void *Element,void *n,void *nd )\n{ \n  (*localProc)( Model, Solver, G, F, Element, n, nd );\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call local matrix add-on\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL execlocalproc_c( f_ptr localProc, void *Model,void *Solver,\n\t\t\t\t\t\t\t\tvoid *G, void *F, void *Element,void *n,void *nd )\n#else\nvoid STDCALLBULL FC_FUNC(execlocalproc, EXECLOCALPROC )\n     ( f_ptr localProc, void *Model,void *Solver,void *G, void *F, void *Element,void *n,void *nd )\n#endif\n{\n   DoLocalCall( (void (STDCALLBULL *)())*localProc,Model,Solver,G,F,Element,n,nd );\n}\n\n\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute complete localmatrix call\n  -------------------------------------------------------------------------*/\nstatic void DoLocalAssembly( void (STDCALLBULL *LocalAssembly)(),\n  void *Model,void *Solver,void *dt,void *transient,void *M, void *D, void *S,void *F, void *Element,void *n,void *nd )\n{ \n  (*LocalAssembly)( Model, Solver, dt, transient, M, D, S, F, Element, n, nd );\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call complete local matrix add-on\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL execlocalassembly_c( f_ptr LocalAssembly, void *Model,\n\t\t         void *Solver,void *dt,void *transient,\n\t\t         void *M, void *D, void *S,void *F,\n\t\t         void *Element,void *n,void *nd )\n#else\nvoid STDCALLBULL FC_FUNC(execlocalassembly, EXECLOCALASSEMBLY )\n     ( f_ptr LocalAssembly, void *Model,void *Solver,void *dt,void *transient,void *M, void *D, void *S,void *F,void *Element,void *n,void *nd )\n#endif\n{\n   DoLocalAssembly( (void (STDCALLBULL *)())*LocalAssembly,Model,Solver,dt,transient,M,D,S,F,Element,n,nd );\n}\n\n\n\n/*--------------------------------------------------------------------------\n  INTERNAL: execute complete localmatrix call\n  -------------------------------------------------------------------------*/\nstatic void DoMatVecSubr( void (STDCALLBULL *matvec)(),\n  void **SpMV,void *n,void *rows,void *cols,void *vals,void *u, void *v, void *reinit )\n{ \n  (*matvec)( SpMV,n,rows,cols,vals,u,v,reinit);\n}\n\n/*--------------------------------------------------------------------------\n  This routine will call complete local matrix add-on\n  -------------------------------------------------------------------------*/\n#ifdef USE_ISO_C_BINDINGS\nvoid STDCALLBULL matvecsubrext_c( f_ptr matvec, void **SpMV, void *n, void *rows,\n\t\t                          void *cols, void *vals, void *u, void *v,void *reinit )\n#else\nvoid STDCALLBULL FC_FUNC(matvecsubr, MMATVECSUBR)\n     ( f_ptr matvec, void **SpMV, void *n, void *rows, void *cols, void *vals, void *u, void *v,void *reinit )\n#endif\n{\n   DoMatVecSubr( (void (STDCALLBULL *)())*matvec,SpMV,n,rows,cols,vals,u,v,reinit);\n}\n'}, {'path': 'fem/src/view3d/ViewFactors.c', 'sha256': 'd202421b748e23c851ed44a2b10977bc389a23a26f16450d2580301216db36bd', 'patched_sha256': '2530665c335dc77d35033f84945f96a80d1127633d417c4f4969019e48e19aa9', 'content': '/*****************************************************************************\n *\n *  Elmer, A Finite Element Software for Multiphysical Problems\n *\n *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n * \n *  This program is free software; you can redistribute it and/or\n *  modify it under the terms of the GNU General Public License\n *  as published by the Free Software Foundation; either version 2\n *  of the License, or (at your option) any later version.\n * \n *  This program is distributed in the hope that it will be useful,\n *  but WITHOUT ANY WARRANTY; without even the implied warranty of\n *  MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n *  GNU General Public License for more details.\n *\n *  You should have received a copy of the GNU General Public License\n *  along with this program (in file fem/GPL-2); if not, write to the \n *  Free Software Foundation, Inc., 51 Franklin Street, Fifth Floor, \n *  Boston, MA 02110-1301, USA.\n *\n *****************************************************************************/\n\n/******************************************************************************\n *\n *\n *\n ******************************************************************************\n *\n *                     Author:       Juha Ruokolainen\n *\n *                    Address: CSC - IT Center for Science Ltd.\n *                                Keilaranta 14, P.O. BOX 405\n *                                  02\n *                                  Tel. +358 0 457 2723\n *                                Telefax: +358 0 457 2302\n *                              EMail: Juha.Ruokolainen@csc.fi\n *\n *                       Date: 02 Jun 1997\n *\n *                Modified by:\n *\n *       Date of modification:\n *\n *****************************************************************************/\n\n#define MODULE_MAIN\n\n/******************************************************************************\n\nView factor computation.\n\nJuha Ruokolainen/CSC - 24 Aug 1995\n\n******************************************************************************/\n\n#include <ViewFactors.h>\n#include "../../config.h"\n\n#if defined(WIN32) || defined(MINGW32) \ndouble drand48()\n{\n    return rand()/(1.0*(1<<15));\n}\n#endif\n\nextern double ShapeFunctionMatrix3[3][3],ShapeFunctionMatrix4[4][4];\nvoid elm_4node_quad_shape_functions(double *B);\n\n\nstatic int MaxLev;\n/*******************************************************************************\n\nCompute viewfactor from hierarchy\n\n24 Aug 1995\n\n*******************************************************************************/\nstatic double ComputeViewFactorValue( Geometry_t *Geom,int Level )\n{\n     double S=0.0, Area=Geom->Area;\n\n     GeometryList_t *Link = Geom->Link;\n\n     Link = Geom->Link;\n     while( Link )\n     {\n        S += Area * Link->ViewFactor;\n        Link = Link->Next;\n     }\n\n     if ( !(Geom->Flags & GEOMETRY_FLAG_LEAF) )\n     {\n        S += ComputeViewFactorValue( Geom->Left,Level+1 );\n        S += ComputeViewFactorValue( Geom->Right,Level+1 );\n     } else\n       MaxLev = MAX(MaxLev,Level);\n\n     return S;\n}\n\nstatic void PrintMesh( Geometry_t *Geom )\n{\n   static FILE *nfp=NULL,*efp=NULL;\n   static int nodes;\n\n   if ( !Geom->Left )\n   {\n     if ( !nfp )\n     {\n        nfp = (FILE *)fopen( "nodes", "w" );\n        efp = (FILE *)fopen( "elems", "w" );\n     }\n\n     if ( Geom->GeometryType == GEOMETRY_TRIANGLE )\n     {\n         fprintf( nfp, "%g %g %g\\n", \n            TriangleValue(0.0,0.0,Geom->Triangle->PolyFactors[0]),\n            TriangleValue(0.0,0.0,Geom->Triangle->PolyFactors[1]),\n            TriangleValue(0.0,0.0,Geom->Triangle->PolyFactors[2]) );\n\n         fprintf( nfp, "%g %g %g\\n", \n            TriangleValue(1.0,0.0,Geom->Triangle->PolyFactors[0]),\n            TriangleValue(1.0,0.0,Geom->Triangle->PolyFactors[1]),\n            TriangleValue(1.0,0.0,Geom->Triangle->PolyFactors[2]) );\n\n         fprintf( nfp, "%g %g %g\\n", \n            TriangleValue(0.0,1.0,Geom->Triangle->PolyFactors[0]),\n            TriangleValue(0.0,1.0,Geom->Triangle->PolyFactors[1]),\n            TriangleValue(0.0,1.0,Geom->Triangle->PolyFactors[2]) );\n\n        fprintf( efp, "1 303 %d %d %d\\n",nodes,nodes+1,nodes+2 );\n        nodes += 3;\n     } else {\n         fprintf( nfp, "%g %g %g\\n", \n            BiLinearValue(0.0,0.0,Geom->BiLinear->PolyFactors[0]),\n            BiLinearValue(0.0,0.0,Geom->BiLinear->PolyFactors[1]),\n            BiLinearValue(0.0,0.0,Geom->BiLinear->PolyFactors[2]) );\n\n         fprintf( nfp, "%g %g %g\\n", \n            BiLinearValue(1.0,0.0,Geom->BiLinear->PolyFactors[0]),\n            BiLinearValue(1.0,0.0,Geom->BiLinear->PolyFactors[1]),\n            BiLinearValue(1.0,0.0,Geom->BiLinear->PolyFactors[2]) );\n\n         fprintf( nfp, "%g %g %g\\n", \n            BiLinearValue(1.0,1.0,Geom->BiLinear->PolyFactors[0]),\n            BiLinearValue(1.0,1.0,Geom->BiLinear->PolyFactors[1]),\n            BiLinearValue(1.0,1.0,Geom->BiLinear->PolyFactors[2]) );\n\n         fprintf( nfp, "%g %g %g\\n", \n            BiLinearValue(0.0,1.0,Geom->BiLinear->PolyFactors[0]),\n            BiLinearValue(0.0,1.0,Geom->BiLinear->PolyFactors[1]),\n            BiLinearValue(0.0,1.0,Geom->BiLinear->PolyFactors[2]) );\n\n        fprintf( efp, "1 404 %d %d %d %d\\n",nodes,nodes+1,nodes+2,nodes+3 );\n        nodes += 4;\n     }\n   } else {\n      PrintMesh( Geom->Left );\n      PrintMesh( Geom->Right );\n   }\n}\n\n/*******************************************************************************\n*******************************************************************************/\nstatic void FreeLinks( Geometry_t *Geom )\n{\n     GeometryList_t *Link=Geom->Link, *Link1;\n\n     while( Link )\n     {\n        Link1 = Link->Next;\n        free(Link);\n        Link = Link1;\n\n     }\n     Geom->Link = NULL;\n\n     if ( Geom->Flags & GEOMETRY_FLAG_LEAF ) \n     {\n        Geom->Flags &= ~GEOMETRY_FLAG_LEAF;\n        return;\n     }\n\n     if ( Geom->Left )  FreeLinks( Geom->Left );\n     if ( Geom->Right ) FreeLinks( Geom->Right );\n}\n\n\n/*******************************************************************************\n*******************************************************************************/\nstatic void FreeChilds( Geometry_t *Geom )\n{\n    if ( !Geom ) return;\n\n     FreeChilds( Geom->Left );\n     FreeChilds( Geom->Right );\n\n    free( Geom );\n}\n\n\n\n/*******************************************************************************\n\nCompute viewfactors for elements of the model, and solve for Gebhardt factors,\nor radiosity, if requested.\n\n24 Aug 1995\n\n*******************************************************************************/\nstatic void IntegrateFromGeometry(int N,double *Factors)\n{\n    double T,s,F,Fmin=DBL_MAX,Fmax=-DBL_MAX,Favg=0.0,*RowSums,Fact;\n    int i,j,k,Imin,Imax;\n\n    GeometryList_t *Link;\n\n    for( i=0; i<N; i++ )\n    {\n        Elements[i].Area = (*AreaCompute[Elements[i].GeometryType])(&Elements[i]);\n        Elements[i].Flags |= GEOMETRY_FLAG_LEAF;\n    }\n\n    MaxLev = 0;\n#pragma omp parallel\n{\n    Geometry_t *lel;\n    lel = (Geometry_t *)malloc(N*sizeof(Geometry_t));\n    memcpy(lel,Elements,N*sizeof(Geometry_t));\n\n#pragma omp for private(i,j,Fact) schedule(dynamic,10)\n    for( i=0; i<N; i++ )\n    {\n         for( j=i; j<N; j++ ) Factors[i*N+j] = 0.0;\n         if ( lel[i].Area<1.0e-10 ) continue;\n\n         for( j=i+1; j<N; j++ )\n         { \n            if ( lel[j].Area<1.0e-10 ) continue;\n\n            FreeLinks( &lel[i] );\n            FreeLinks( &lel[j] );\n\n            lel[i].Flags |= GEOMETRY_FLAG_LEAF;\n            lel[j].Flags |= GEOMETRY_FLAG_LEAF;\n\n            (*ViewFactorCompute[lel[i].GeometryType])( &lel[i],&lel[j],0,0 );\n  \n            Fact = ComputeViewFactorValue( &lel[i],0 );\n            Factors[i*N+j] = Fact / lel[i].Area;\n            Factors[j*N+i] = Fact / lel[j].Area;\n         }\n\n         FreeChilds( lel[i].Left );\n         lel[i].Left = NULL;\n\n         FreeChilds( lel[i].Right );\n         lel[i].Right = NULL;\n    }\n\n    free(lel);\n}\n\n    k = 0;\n    for(i=0; i<N; i++ )\n    {\n         s = 0.0;\n         for( j=0; j<N; j++ ) s += Factors[i*N+j];\n\n         if ( s < Fmin )\n         {\n            Fmin = s;\n            Imin = i+1;\n         }\n         if ( s > Fmax )\n         {\n            Fmax = s;\n            Imax = i+1;\n         }\n         Favg += s;\n    }\n   fprintf( stdout, "surfs: %d, min(%d)=%-4.2f, max(%d)=%-4.2f, avg=%-4.2f\\n", \n                       N,Imin,Fmin,Imax,Fmax,Favg/N );\n}\n\nvoid MakeViewFactorMatrix(int N,double *Factors,int NInteg,int NInteg3)\n{\n    double T[32],S[32];\n    long int i,j,k,n;\n\n    n = sqrt( NInteg ) + 0.5;\n\n    switch( n )\n    {\n      case 1:\n        T[0] = 0.0;\n        S[0] = 2.0;\n\n        N_Integ = 1;\n      break;\n\n      case 2:\n        T[0] = -0.577350269189625;\n        T[1] =  0.577350269189625;\n\n        S[0] = 1.000000000000000;\n        S[1] = 1.000000000000000;\n\n        N_Integ = 2;\n      break;\n\n      case 4:\n        T[0] = -0.861136311594052;\n        T[1] = -0.339981043584856;\n        T[2] =  0.339981043584856;\n        T[3] =  0.861136311594052;\n\n        S[0] =  0.347854845137454;\n        S[1] =  0.652145154862546;\n        S[2] =  0.652145154862546;\n        S[3] =  0.347854845137454;\n\n        N_Integ = 4;\n      break;\n\n      case 7:\n        T[0] = -0.949107912342759;\n        T[1] = -0.741531185599394;\n        T[2] = -0.405845151377397;\n        T[3] =  0.000000000000000;\n        T[4] =  0.405845151377397;\n        T[5] =  0.741531185599394;\n        T[6] =  0.949107912342759;\n\n        S[0] =  0.129484966168870;\n        S[1] =  0.279705391489277;\n        S[2] =  0.381830050505119;\n        S[3] =  0.417959183673469;\n        S[4] =  0.381830050505119;\n        S[5] =  0.279705391489277;\n        S[6] =  0.129484966168870;\n\n        N_Integ = 7;\n      break;\n     }\n\n     k = 0;\n     for( i=0; i<N_Integ; i++ )\n     {\n        for( j=0; j<N_Integ; j++,k++ )\n        {\n           /* FOR -1,1 */\n           U_Integ[k] = T[i];\n           V_Integ[k] = T[j];\n           S_Integ[k] = S[i]*S[j];\n\n           /* FOR 0-1 */\n           U_Integ[k] = 0.5*(T[i]+1.0);\n           V_Integ[k] = 0.5*(T[j]+1.0);\n           S_Integ[k] = S[i]*S[j]/4.0;\n       }\n       U_Integ1d[i] = 0.5*(T[i]+1.0);\n       S_Integ1d[i] = 0.5*S[i];\n    }\n    N_Integ1d = N_Integ;\n    N_Integ = k;\n\n\n    switch( NInteg3 )\n    {\n      case 1:\n         N_Integ3 = 1;\n\n        U_Integ3[0] = 1.0/3.0;\n        V_Integ3[0] = 1.0/3.0;\n        S_Integ3[0] = 1.0/2.0;\n      break;\n\n      case 3:\n        N_Integ3 = 3;\n\n        U_Integ3[0] = 1.0/6.0;\n        U_Integ3[1] = 2.0/3.0;\n        U_Integ3[2] = 1.0/6.0;\n\n        V_Integ3[0] = 1.0/6.0;\n        V_Integ3[1] = 1.0/6.0;\n        V_Integ3[2] = 2.0/3.0;\n\n        S_Integ3[0] = 1.0/6.0;\n        S_Integ3[1] = 1.0/6.0;\n        S_Integ3[2] = 1.0/6.0;\n      break;\n\n      case 6:\n        N_Integ3 = 6;\n\n        U_Integ3[0] = 0.091576213509771;\n        U_Integ3[1] = 0.816847572980459;\n        U_Integ3[2] = 0.091576213509771;\n        U_Integ3[3] = 0.445948490915965;\n        U_Integ3[4] = 0.108103018168070;\n        U_Integ3[5] = 0.445948490915965;\n\n        V_Integ3[0] = 0.091576213509771;\n        V_Integ3[1] = 0.091576213509771;\n        V_Integ3[2] = 0.816847572980459;\n        V_Integ3[3] = 0.445948490915965;\n        V_Integ3[4] = 0.445948490915965;\n        V_Integ3[5] = 0.108103018168070;\n\n        S_Integ3[0] = 0.109951743655322 / 2;\n        S_Integ3[1] = 0.109951743655322 / 2;\n        S_Integ3[2] = 0.109951743655322 / 2;\n        S_Integ3[3] = 0.223381589678011 / 2;\n        S_Integ3[4] = 0.223381589678011 / 2;\n        S_Integ3[5] = 0.223381589678011 / 2;\n      break;\n    }\n\n    IntegrateFromGeometry( N,Factors );\n}\n\nvoid InitGeometryTypes()\n{\n    InitRayTracer( RayEPS );\n\n    IntegrateDiffToArea[GEOMETRY_LINE]        = LinearIntegrateDiffToArea;\n    IntegrateDiffToArea[GEOMETRY_TRIANGLE]    = TriangleIntegrateDiffToArea;\n    IntegrateDiffToArea[GEOMETRY_BILINEAR]    = BiLinearIntegrateDiffToArea;\n    IntegrateDiffToArea[GEOMETRY_BICUBIC]     = BiCubicIntegrateDiffToArea;\n    IntegrateDiffToArea[GEOMETRY_BIQUADRATIC] = BiQuadraticIntegrateDiffToArea;\n\n    Subdivide[GEOMETRY_LINE]                  = LinearSubdivide;\n    Subdivide[GEOMETRY_TRIANGLE]              = TriangleSubdivide;\n    Subdivide[GEOMETRY_BILINEAR]              = BiLinearSubdivide;\n    Subdivide[GEOMETRY_BICUBIC]               = BiCubicSubdivide;\n    Subdivide[GEOMETRY_BIQUADRATIC]           = BiQuadraticSubdivide;\n\n    AreaCompute[GEOMETRY_LINE]                = LinearArea;\n    AreaCompute[GEOMETRY_TRIANGLE]            = TriangleArea;\n    AreaCompute[GEOMETRY_BILINEAR]            = BiLinearArea;\n    AreaCompute[GEOMETRY_BICUBIC]             = BiCubicArea;\n    AreaCompute[GEOMETRY_BIQUADRATIC]         = BiQuadraticArea;\n\n    ViewFactorCompute[GEOMETRY_LINE]          = LinearComputeViewFactors;\n    ViewFactorCompute[GEOMETRY_TRIANGLE]      = TriangleComputeViewFactors;\n    ViewFactorCompute[GEOMETRY_BILINEAR]      = BiLinearComputeViewFactors;\n    ViewFactorCompute[GEOMETRY_BICUBIC]       = BiCubicComputeViewFactors;\n    ViewFactorCompute[GEOMETRY_BIQUADRATIC]   = BiQuadraticComputeViewFactors;\n}\n\nvoid viewfactors3d\n  ( int *EL_N,  int *EL_Topo, int *EL_Type, double *EL_Coord, double *EL_Normals,\n    int *RT_N0, int *RT_Topo0, int *RT_Type, double *RT_Coord, double *RT_Normals,\n    double *Factors, double *Feps, double *Aeps, double *Reps, int *Nr,\n    int *NInteg,int *NInteg3, int  *Combine )\n{\n   int i,j,k,l,n,NOFRayElements;\n   int RT_N=0, *RT_Topo=NULL;\n\n   AreaEPS   = *Aeps; \n   RayEPS    = *Reps; \n   FactorEPS = *Feps; \n   Nrays     = *Nr;\n\n   ShapeFunctionMatrix2[0][0] =  1.0;\n   ShapeFunctionMatrix2[0][1] = -1.0;\n\n   ShapeFunctionMatrix2[1][0] =  0.0;\n   ShapeFunctionMatrix2[1][1] =  1.0;\n\n   ShapeFunctionMatrix3[0][0] =  1.0;\n   ShapeFunctionMatrix3[0][1] = -1.0;\n   ShapeFunctionMatrix3[0][2] = -1.0;\n\n   ShapeFunctionMatrix3[1][0] =  0.0;\n   ShapeFunctionMatrix3[1][1] =  1.0;\n   ShapeFunctionMatrix3[1][2] =  0.0;\n\n   ShapeFunctionMatrix3[2][0] =  0.0;\n   ShapeFunctionMatrix3[2][1] =  0.0;\n   ShapeFunctionMatrix3[2][2] =  1.0;\n\n   elm_4node_quad_shape_functions( &ShapeFunctionMatrix4[0][0] );\n\n   Elements = (Geometry_t *)calloc( *EL_N,sizeof(Geometry_t) );\n   for( i=0; i<*EL_N; i++ )\n   {\n     switch( EL_Type[i] ) {\n     case 202:\n        Elements[i].GeometryType = GEOMETRY_LINE;\n        Elements[i].Linear = (Linear_t *)calloc( sizeof(Linear_t),1 );\n\n        for( j=0; j<2; j++ )\n        {\n           for( k=0; k<2; k++ )\n           for( n=0; n<3; n++ )\n           {\n              l = 3*EL_Topo[2*i+k]+n;\n              Elements[i].Linear->PolyFactors[n][j]   += ShapeFunctionMatrix2[k][j]*EL_Coord[l];\n              Elements[i].Linear->PolyFactors[n+3][j] += ShapeFunctionMatrix2[k][j]*EL_Normals[3*i+n];\n           }\n        }\n     break;\n     case 404:\n        Elements[i].GeometryType = GEOMETRY_BILINEAR;\n        Elements[i].BiLinear = (BiLinear_t *)calloc( sizeof(BiLinear_t),1 );\n\n        for( j=0; j<4; j++ )\n        {\n           for( k=0; k<4; k++ )\n           for( n=0; n<3; n++ )\n           {\n              l = 3*EL_Topo[4*i+k]+n;\n              Elements[i].BiLinear->PolyFactors[n][j]   += ShapeFunctionMatrix4[k][j]*EL_Coord[l];\n              Elements[i].BiLinear->PolyFactors[n+3][j] += ShapeFunctionMatrix4[k][j]*EL_Normals[3*i+n];\n           }\n        }\n     break;\n     case 303:\n        Elements[i].GeometryType = GEOMETRY_TRIANGLE;\n        Elements[i].Triangle = (Triangle_t *)calloc( sizeof(Triangle_t),1 );\n\n        for( j=0; j<3; j++ )\n        {\n           for( k=0; k<3; k++ )\n           for( n=0; n<3; n++ )\n           {\n              l = 3*EL_Topo[3*i+k] + n;\n              Elements[i].Triangle->PolyFactors[n][j]   += ShapeFunctionMatrix3[k][j]*EL_Coord[l];\n              Elements[i].Triangle->PolyFactors[n+3][j] += ShapeFunctionMatrix3[k][j]*EL_Normals[3*i+n];\n           }\n        }\n     break;\n     }\n   }\n\n   RT_N = *RT_N0;\n   RT_Topo = RT_Topo0;\n\n   if ( RT_N == 0 && EL_Type[0] == 202 && *Combine )\n   {\n     int maxind = 0, maxnodehits=0, tablesize;\n     int *nodehits,*nodetable,i,j;\n     int ind0,ind1,ind2;\n     double x0, y0,  x1, y1, x2, y2, dx1, dx2,\n       dy1, dy2, dp1, dp2, ds1,ds2, eps=1e-16;\n\n     printf("Combining original boundary elements for shading\\n");\n\n     for (i=0; i<2**EL_N; i++) \n       if(maxind < EL_Topo[i]) maxind = EL_Topo[i];\n\n     nodehits = (int*) malloc((maxind+1)*sizeof(int));\n     for(i=0;i<=maxind;i++)\n       nodehits[i] = 0;\n     for(i=0; i<2**EL_N; i++)  \n       nodehits[EL_Topo[i]]++;\n\n     maxnodehits = 0;\n     for(i=0; i<=maxind; i++) \n       if(nodehits[i] > maxnodehits) maxnodehits = nodehits[i];\n    \n     tablesize = (maxind+1)*maxnodehits;\n     nodetable = (int*) malloc(tablesize*sizeof(int));\n     for(i=0; i< tablesize; i++) \n       nodetable[i] = 0;\n\n     for(i=0;i<=maxind;i++)\n       nodehits[i] = 0;\n\n     for(i=0; i<*EL_N; i++) {\n       ind1 = EL_Topo[2*i+1];\n       ind2 = EL_Topo[2*i+0];\n       nodetable[maxnodehits*ind1 + nodehits[ind1]] = i;\n       nodetable[maxnodehits*ind2 + nodehits[ind2]] = i;\n       nodehits[ind1] += 1;\n       nodehits[ind2] += 1;\n     }\n \n     RT_Topo = (int*) malloc(2**EL_N*sizeof(int));\n     for(i=0;i<2**EL_N;i++)\n       RT_Topo[i] = EL_Topo[i];\n \n     for (i=0; i<=maxind; i++) {\n       int elem1,elem2;\n       ind0 = i;\n      \n       if( nodehits[ind0] != 2) continue;\n\n       elem1 = nodetable[maxnodehits*ind0+0];\n       if( RT_Topo[2*elem1+1] == ind0 ) \n \tind1 = RT_Topo[2*elem1];\n       else \n \tind1 = RT_Topo[2*elem1+1];\n\n       elem2 = nodetable[maxnodehits*ind0+1];\n       if( RT_Topo[2*elem2+1] == ind0 ) \n \tind2 = RT_Topo[2*elem2];\n       else \n \tind2 = RT_Topo[2*elem2+1];\n\n       x0 = EL_Coord[3*ind0];\n       x1 = EL_Coord[3*ind1];\n       x2 = EL_Coord[3*ind2];\n      \n       y0 = EL_Coord[3*ind0+1];\n       y1 = EL_Coord[3*ind1+1];\n       y2 = EL_Coord[3*ind2+1];\n\n       dx1 = x1-x0;\n       dx2 = x2-x0;\n       dy1 = y1-y0;\n       dy2 = y2-y0;\n      \n       dp1 = dx1*dx2+dy1*dy2;\n       ds1 = sqrt(dx1*dx1+dy1*dy1);\n       ds2 = sqrt(dx2*dx2+dy2*dy2);\n      \n       dp1 /= (ds1*ds2);\n\n       /* Boundary elements must be aligned */\n       if( dp1 > eps - 1. ) continue;\n\n       /* Make the 1st element bigger  */\n       if( RT_Topo[2*elem1] == ind0 ) \n \t RT_Topo[2*elem1] = ind2;\n       else \n\t RT_Topo[2*elem1+1] = ind2;\n      \n       /* Destroy the 2nd element */\n       RT_Topo[2*elem2] = 0;\n       RT_Topo[2*elem2+1] = 0;\n\n       /* Update the node information */\n       nodehits[ind0] = 0;\n       if( nodetable[maxnodehits*ind2] == elem2) \n \tnodetable[maxnodehits*ind2] = elem1;\n       else \n \tnodetable[maxnodehits*ind2+1] = elem1;\n     }\n\n     /* Free, not needed anymore */\n     free((char*)(nodetable));\n\n     j = 0;\n     for (i=0; i<*EL_N; i++) {\n       if(RT_Topo[2*i+1] || RT_Topo[2*i+0]) {\n          RT_Topo[2*j+1] = RT_Topo[2*i+1];\n          RT_Topo[2*j+0] = RT_Topo[2*i+0];\n          j++;\n       }\n     }\n     RT_N = j;\n     printf("The combined set includes %d line segments (vs. %d)\\n",RT_N,*EL_N);\n   }\n\n   /*\n    * check if different geometry elements given for shadowing ...\n    */\n   if ( RT_N > 0 ) {\n     RTElements = (Geometry_t *)calloc( RT_N,sizeof(Geometry_t) );\n     for( i=0; i<RT_N; i++ )\n     {\n       switch( RT_Type[i] ) {\n       case 202:\n          RTElements[i].GeometryType = GEOMETRY_LINE;\n          RTElements[i].Linear = (Linear_t *)calloc( sizeof(Linear_t),1 );\n\n          for( j=0; j<2; j++ )\n          {\n             for( k=0; k<2; k++ )\n             for( n=0; n<3; n++ )\n             {\n                l = 3*RT_Topo[2*i+k]+n;\n                RTElements[i].Linear->PolyFactors[n][j]   += ShapeFunctionMatrix2[k][j]*RT_Coord[l];\n              }\n          }\n       break;\n       case 404:\n          RTElements[i].GeometryType = GEOMETRY_BILINEAR;\n          RTElements[i].BiLinear = (BiLinear_t *)calloc( sizeof(BiLinear_t),1 );\n\n          for( j=0; j<4; j++ )\n          {\n             for( k=0; k<4; k++ )\n             for( n=0; n<3; n++ )\n             {\n                l = 3*RT_Topo[4*i+k]+n;\n                RTElements[i].BiLinear->PolyFactors[n][j]   += ShapeFunctionMatrix4[k][j]*RT_Coord[l];\n             }\n          }\n       break;\n       case 303:\n          RTElements[i].GeometryType = GEOMETRY_TRIANGLE;\n          RTElements[i].Triangle = (Triangle_t *)calloc( sizeof(Triangle_t),1 );\n\n          for( j=0; j<3; j++ )\n          {\n             for( k=0; k<3; k++ )\n             for( n=0; n<3; n++ )\n             {\n                l = 3*RT_Topo[3*i+k] + n;\n                RTElements[i].Triangle->PolyFactors[n][j]   += ShapeFunctionMatrix3[k][j]*RT_Coord[l];\n             }\n          }\n       break;\n       }\n     }\n     NOFRayElements = RT_N;\n   } else {\n     NOFRayElements = *EL_N;\n     RTElements = Elements;\n   }\n\n   InitGeometryTypes();\n   InitVolumeBounds( 2, NOFRayElements, RTElements );\n   MakeViewFactorMatrix( *EL_N,Factors,*NInteg,*NInteg3 );\n}\n'}, {'path': 'fem/src/CMakeLists.txt', 'sha256': '2e60b906cb99c02cb0d2442e88275420b43e75a7c14e64d96dea53c7c3ca5f85', 'patched_sha256': 'b5a4389b83e45a76f239d30cc9e9a7ff435db4b7493159164ee029b5bc6306a7', 'content': '# For the installer process we need a single directory\n# where we put all module files\nSET(CMAKE_Fortran_MODULE_DIRECTORY\n  ${PROJECT_BINARY_DIR}/fmodules CACHE PATH "Directory for Fortran modules")\n\nADD_SUBDIRECTORY(binio)\nADD_SUBDIRECTORY(modules)\nADD_SUBDIRECTORY(view3d)\nADD_SUBDIRECTORY(viewaxis)\n\nIF(WITH_MPI)\n  SET(ELMERSOLVER_OUTPUT_NAME "ElmerSolver_mpi") \nELSE()\n  SET(ELMERSOLVER_OUTPUT_NAME "ElmerSolver")\nENDIF()\n\nSET(prefix "${CMAKE_INSTALL_PREFIX}")\n\nSET(solverlib_SOURCES AddrFunc.F90 NavierStokes.F90 NavierStokesGeneral.F90\n  NavierStokesCylindrical.F90 Lists.F90\n  DiffuseConvectiveAnisotropic.F90 LoadMod.F90\n  DiffuseConvectiveGeneralAnisotropic.F90 PElementMaps.F90\n  PElementBase.F90 ElementDescription.F90 Integration.F90 ListMatrixArray.F90\n  ModelDescription.F90 GeneralUtils.F90 Stress.F90 StressGeneral.F90\n  LinearAlgebra.F90 CoordinateSystems.F90 ListMatrix.F90 CRSMatrix.F90\n  BandMatrix.F90 BandwidthOptimize.F90 BlockSolve.F90\n  MaterialModels.F90 DirectSolve.F90 IterSolve.F90\n  IterativeMethods.F90 TimeIntegrate.F90 Types.F90 SolveBand.F90\n  ElementUtils.F90 Radiation.F90 fft.c Load.c Differentials.F90\n  FreeSurface.F90 Maxwell.F90 MaxwellAxiS.F90 MaxwellGeneral.F90\n  Walls.F90 SolverUtils.F90 SolveSBand.F90 CPUTime.c Interpolation.F90\n  MainUtils.F90 Adaptive.F90 EigenSolve.F90 HashTable.F90\n  MeshUtils.F90 SaveUtils.F90 SParIterGlobals.F90 SParIterComm.F90\n  SParIterPrecond.F90 SParIterSolver.F90 Messages.F90 Multigrid.F90\n  Smoothers.F90 ClusteringMethods.F90 ParallelUtils.F90\n  ParallelEigenSolve.F90 solve_cmplx.F90 solve_real.F90 MGPrec.F90\n  DefUtils.F90 MeshPartition.F90 MeshRemeshing.F90 LUDecomposition.F90 \n  RadiationFactors.F90 f_stubs.c\n  ExchangeCorrelations.F90 SolveHypre.c SolverActivate_x.F90\n  SolveTrilinos.cxx SolveSuperLU.c iso_varying_string.F90\n  umf4_f77wrapper.c VankaCreate.F90 ParticleUtils.F90 Feti.F90\n  cholmod.c InterpolateMeshToMesh.F90 InterpVarToVar.F90\n  LinearForms.F90 H1Basis.F90 CircuitUtils.F90 BackwardError.F90\n  ElmerSolver.F90 MagnetoDynamicsUtils.F90 ComponentUtils.F90 \n  ZirkaHysteresis.F90 SolidMechanicsUtils.F90)\n\nSET_PROPERTY(SOURCE MaxwellAxiS.F90 PROPERTY\n\tCOMPILE_DEFINITIONS FULL_INDUCTION)\n\n\nIF(WITH_LUA)\n  INCLUDE_DIRECTORIES(${LUA_INCLUDE_DIR})\n  LIST(APPEND solverlib_SOURCES Lua.F90 elmer_lua_iface.c)\n  INSTALL(DIRECTORY lua-scripts DESTINATION share/elmersolver/\n    PATTERN lua-scripts/*.lua)\n  FILE(GLOB DEFAULT_LUA_SCRIPTS "lua-scripts/*.lua")\n  FILE(COPY ${DEFAULT_LUA_SCRIPTS} DESTINATION ${CMAKE_CURRENT_BINARY_DIR}/share/elmersolver/lua-scripts/)\nENDIF()\n\nIF(HAVE_FETI4I)\n  LIST(APPEND solverlib_SOURCES ${FETI4I_INTERFACE_SOURCE})\nENDIF()\n\n#FILE(GLOB SRC_FILES *.src)\n#FOREACH(FNAME ${SRC_FILES})\n#GET_FILENAME_COMPONENT(BASENAME ${FNAME} NAME_WE)\n#ADD_CUSTOM_COMMAND(\n  #OUTPUT ${CMAKE_CURRENT_BINARY_DIR}/${BASENAME}.F90\n  #COMMAND ${CMAKE_COMMAND} -E copy ${FNAME}\n    #${CMAKE_CURRENT_BINARY_DIR}/${BASENAME}.F90\n  #DEPENDS ${CMAKE_CURRENT_SOURCE_DIR}/${BASENAME}.src\n  #)\n#ENDFOREACH()\n\nINCLUDE_DIRECTORIES("${CMAKE_BINARY_DIR}/fem/src")\nINCLUDE_DIRECTORIES("${CMAKE_SOURCE_DIR}/fhutiter/src")\nINCLUDE_DIRECTORIES("${CMAKE_CURRENT_BINARY_DIR}/binio")\nINCLUDE_DIRECTORIES("${PROJECT_BINARY_DIR}/fhutiter/src")\n\nIF(WITH_Trilinos)\n  INCLUDE_DIRECTORIES("${Epetra_INCLUDE_DIRS}")\n  INCLUDE_DIRECTORIES("${ML_INCLUDE_DIRS}")\nENDIF()\n\n# Extract additional compile flags\nGET_DIRECTORY_PROPERTY( ELMER_CDEFS COMPILE_DEFINITIONS )\nFOREACH( d ${ELMER_CDEFS} )\n\t SET(ELMER_F90FLAGS "${ELMER_F90FLAGS} -D${d}")\nENDFOREACH()\n\n\n# Extract compile flags arising from build type\nIF(CMAKE_BUILD_TYPE)\n  STRING(TOUPPER ${CMAKE_BUILD_TYPE} CMAKE_BUILD_TYPE_UPCASE)\n  SET(ELMER_F90FLAGS "${ELMER_F90FLAGS} ${CMAKE_Fortran_FLAGS_${CMAKE_BUILD_TYPE_UPCASE}}")\n  MARK_AS_ADVANCED(CMAKE_BUILD_TYPE_UPCASE)\nENDIF(CMAKE_BUILD_TYPE)\n\n# Output elmerf90 and elmerld\nSET(HAVE_ELMERICE "FALSE")\nIF(WITH_ElmerIce)\n  SET(HAVE_ELMERICE "TRUE")\nENDIF()\n\nIF(WIN32)\n  CONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elmerf90.bat.in.cmake\n\t  ${CMAKE_CURRENT_BINARY_DIR}/elmerf90.bat)\n  CONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elmerld.bat.in.cmake\n\t  ${CMAKE_CURRENT_BINARY_DIR}/elmerld.bat)\nENDIF()\n\nCONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elmerf90-nosh.in.cmake\n  ${CMAKE_CURRENT_BINARY_DIR}/elmerf90-nosh)\nCONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elmerf90.in.cmake\n  ${CMAKE_CURRENT_BINARY_DIR}/elmerf90)\nCONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elmerld.in.cmake\n  ${CMAKE_CURRENT_BINARY_DIR}/elmerld)\n\n# Create pkg-config file if requested and place it under ${PKGCONFIG_PC_PATH}\n# Defaults: PKGCONFIG_PC_PATH = ${CMAKE_INSTALL_PREFIX}/share/pkgconfig\nIF(CREATE_PKGCONFIG_FILE)\n  SET(PKGCONFIG_PC_PATH "${CMAKE_INSTALL_PREFIX}/share/pkgconfig" \n    CACHE PATH "Path where to install elmer pkg-config file")\n  CONFIGURE_FILE(elmer.pc.cmake elmer.pc @ONLY)\n  INSTALL(FILES ${CMAKE_CURRENT_BINARY_DIR}/elmer.pc \n    DESTINATION ${PKGCONFIG_PC_PATH})\nENDIF(CREATE_PKGCONFIG_FILE)\n\n# Copy elements.def and SOLVER.KEYWORDS (to enable testing)\nCONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/elements.def \n  ${CMAKE_CURRENT_BINARY_DIR}/elements.def COPYONLY)\nCONFIGURE_FILE(${CMAKE_CURRENT_SOURCE_DIR}/SOLVER.KEYWORDS\n  ${CMAKE_CURRENT_BINARY_DIR}/SOLVER.KEYWORDS COPYONLY)\n\nIF (NOT MPI_FOUND)\n  FILE(COPY ${CMAKE_CURRENT_SOURCE_DIR}/mpif_stub.h \n            DESTINATION ${CMAKE_CURRENT_BINARY_DIR})\n  FILE(RENAME ${CMAKE_CURRENT_BINARY_DIR}/mpif_stub.h\n              ${CMAKE_CURRENT_BINARY_DIR}/mpif.h)\nENDIF()\n\nADD_LIBRARY(mpi_stubs SHARED mpif_stubs.F90)\nADD_LIBRARY(elmersolver SHARED ${solverlib_SOURCES})\nSET_TARGET_PROPERTIES(mpi_stubs\n                      PROPERTIES LINKER_LANGUAGE Fortran)\nSET_TARGET_PROPERTIES(elmersolver\n                      PROPERTIES LINKER_LANGUAGE Fortran)\n\n#We want MMG & Zoltan in the RPATH (if found), but given how many other \n#components use ELMERSOLVER_RPATH_STRING, it seemed best to make\n#a local copy just for ElmerSolver and libelmersolver\nSET(ELMERSOLVER_RPATH_STRING_MOD "${ELMERSOLVER_RPATH_STRING}")\nIF(HAVE_MMG)\n  TARGET_LINK_LIBRARIES(elmersolver ${MMG_LIBRARY})\n  SET(ELMERSOLVER_RPATH_STRING_MOD "${ELMERSOLVER_RPATH_STRING_MOD}:${MMG_LIBDIR}")\n  SET(ELMERLIB_RPATH_STRING "${ELMERLIB_RPATH_STRING}:${MMG_LIBDIR}")\n  #TODO - add to RPath\nENDIF()\n\nIF(HAVE_ZOLTAN)\n  TARGET_LINK_LIBRARIES(elmersolver ${ZOLTAN_LIBRARY})\n  ADD_DEPENDENCIES(elmersolver ${ZOLTAN_LIBRARY})\n  # SET(ELMERSOLVER_RPATH_STRING_MOD "${ELMERSOLVER_RPATH_STRING_MOD}/:${ZOLTAN_LIBDIR}")\n  # SET(ELMERLIB_RPATH_STRING "${ELMERLIB_RPATH_STRING}/:${ZOLTAN_LIBDIR}")\nENDIF()\n\n# ElmerSolver libraries \nSET(ELMERSOLVER_LIBRARIES matc umfpack \n                          amd fhuti binio arpack\n                          ${BLAS_LIBRARIES} ${LAPACK_LIBRARIES} \n                          ${CMAKE_DL_LIBS})\n\nIF(WITH_LUA)\n  LIST(APPEND ELMERSOLVER_LIBRARIES ${LUA_LIBRARIES})\nENDIF()\n\n\nADD_EXECUTABLE(Solver_TGT Solver.F90)\nSET_TARGET_PROPERTIES(Solver_TGT PROPERTIES OUTPUT_NAME "${ELMERSOLVER_OUTPUT_NAME}")\n\nIF(NOT(WIN32))\n  MESSAGE(STATUS " ELMERSOLVER_RPATH_STRING_MOD " ${ELMERSOLVER_RPATH_STRING_MOD})\n  MESSAGE(STATUS " ELMERLIB_RPATH_STRING " ${ELMERLIB_RPATH_STRING})\n\n   SET_TARGET_PROPERTIES(Solver_TGT PROPERTIES INSTALL_RPATH "${ELMERSOLVER_RPATH_STRING_MOD}")\n   SET_TARGET_PROPERTIES(elmersolver PROPERTIES INSTALL_RPATH "${ELMERLIB_RPATH_STRING}")\nENDIF()\n\nIF(NOT(WITH_MPI))\n  TARGET_LINK_LIBRARIES(elmersolver mpi_stubs ${ELMERSOLVER_LIBRARIES})\n  TARGET_LINK_LIBRARIES(Solver_TGT elmersolver)\nENDIF()\n\n# ElmerSolver libraries \nIF(WITH_MPI)\n  #ADD_LIBRARY(elmersolver_mpi SHARED ${solverlib_SOURCES})\n\n  # Add parpack and possibly others\n  IF(Mumps_LIBRARIES)\n    INCLUDE_DIRECTORIES(${Mumps_INCLUDE_DIR})\n    # Link to SCALAPACK implicitly\n    LIST(APPEND ELMERSOLVER_LIBRARIES ${Mumps_LIBRARIES})\n  ELSEIF(MKL_CPARDISO_FOUND)\n    # Mumps includes SCALAPACK, but it is needed with CPARDISO\n    LIST(APPEND ELMERSOLVER_LIBRARIES ${SCALAPACK_LIBRARIES})\n  ENDIF()\n\n  IF(Hypre_LIBRARIES)\n    LIST(APPEND ELMERSOLVER_LIBRARIES ${Hypre_LIBRARIES})\n  ENDIF()\n\n  IF(FETI4I_LIBRARIES)\n    LIST(APPEND ELMERSOLVER_LIBRARIES ${FETI4I_LIBRARIES})\n  ENDIF()\n   \n  # Executable\n  GET_TARGET_PROPERTY(CURRENT_LINK_FLAGS Solver_TGT LINK_FLAGS)\n  GET_TARGET_PROPERTY(CURRENT_COMPILE_FLAGS Solver_TGT COMPILE_FLAGS)\n\n  IF(CURRENT_LINK_FLAGS)\n    SET(CURR_LFLAGS "${CURRENT_LINK_FLAGS};${MPI_Fortran_LINK_FLAGS}")\n  ELSE()\n    SET(CURR_LFLAGS "${MPI_Fortran_LINK_FLAGS}")\n  ENDIF()\n\n  IF(CURRENT_COMPILE_FLAGS)\n    SET(CURR_CFLAGS "${CURRENT_COMPILE_FLAGS};${MPI_Fortran_COMPILE_FLAGS}")\n  ELSE()\n    SET(CURR_CFLAGS "${MPI_Fortran_COMPILE_FLAGS}")\n  ENDIF()\n\n  SET_TARGET_PROPERTIES(Solver_TGT PROPERTIES LINK_FLAGS "${CURR_LFLAGS}")\n  SET_TARGET_PROPERTIES(Solver_TGT PROPERTIES COMPILE_FLAGS "${CURR_CFLAGS}")\n  TARGET_LINK_LIBRARIES(Solver_TGT elmersolver ${ELMERSOLVER_LIBRARIES})\n\n  # Library object\n  GET_TARGET_PROPERTY(CURRENT_LINK_FLAGS elmersolver LINK_FLAGS) \n  GET_TARGET_PROPERTY(CURRENT_COMPILE_FLAGS elmersolver COMPILE_FLAGS)\n\n  IF(CURRENT_LINK_FLAGS)\n    SET(CURR_LFLAGS "${CURRENT_LINK_FLAGS};${MPI_Fortran_LINK_FLAGS}")\n  ELSE()\n    SET(CURR_LFLAGS "${MPI_Fortran_LINK_FLAGS}")\n  ENDIF()\n  IF(CURRENT_COMPILE_FLAGS)\n    SET(CURR_CFLAGS "${CURRENT_COMPILE_FLAGS};${MPI_Fortran_COMPILE_FLAGS}")\n  ELSE()\n    SET(CURR_CFLAGS "${MPI_Fortran_COMPILE_FLAGS}")\n  ENDIF()\n\n  SET_TARGET_PROPERTIES(elmersolver PROPERTIES LINK_FLAGS "${CURR_LFLAGS}")\n  SET_TARGET_PROPERTIES(elmersolver PROPERTIES COMPILE_FLAGS "${CURR_CFLAGS}")\n  TARGET_LINK_LIBRARIES(elmersolver ${ELMERSOLVER_LIBRARIES} parpack ${MPI_Fortran_LIBRARIES})\n\n  SET(SERIAL_SOLVER_FILEPATH "${CMAKE_INSTALL_PREFIX}/bin/ElmerSolver")\n  SET(MPI_SOLVER_FILEPATH "${CMAKE_INSTALL_PREFIX}/bin/${ELMERSOLVER_OUTPUT_NAME}")\nENDIF()\n\nIF(WITH_Trilinos)\n  TARGET_LINK_LIBRARIES(elmersolver "${Trilinos_LIBRARIES};${ML_LIBRARIES};${Epetra_LIBRARIES};${Teuchos_LIBRARIES}")\nENDIF()\n\n# elmersolver -library\n#TARGET_LINK_LIBRARIES(elmersolver ${ELMERSOLVER_LIBRARIES})\n\n## ElmerSolver serial\n#IF(NOT(NO_SERIAL_BINARY))\n  #TARGET_LINK_LIBRARIES(elmersolver mpi_stubs ${ELMERSOLVER_LIBRARIES})\n  #TARGET_LINK_LIBRARIES(ElmerSolver elmersolver)\n#ENDIF()\n\n# ElmerSolver\n#ADD_EXECUTABLE(ElmerSolver Solver.F90)\n#TARGET_LINK_LIBRARIES(ElmerSolver ${ELMERSOLVER_LIBRARIES} \n                                  #mpi_stubs)\n\n# ViewFactors\nADD_EXECUTABLE(ViewFactors ViewFactors.F90)\nSET_TARGET_PROPERTIES(ViewFactors PROPERTIES LINKER_LANGUAGE Fortran)\n# TARGET_INCLUDE_DIRECTORIES(ViewFactors PUBLIC ${CMAKE_BINARY_DIR}/fem/src/view3d)\n# TARGET_INCLUDE_DIRECTORIES(ViewFactors PUBLIC ${CMAKE_BINARY_DIR}/fem/src/viewfactors)\n# FIND_LIBRARY(VIEW3D_LIBRARIES PATHS ${CMAKE_CURRENT_BINARY_DIR}/view3d)\n# FIND_LIBRARY(VIEWAXIS_LIBRARIES PATHS ${CMAKE_CURRENT_BINARY_DIR}/viewaxis)\nTARGET_LINK_LIBRARIES(ViewFactors ${ELMERSOLVER_LIBRARIES} \n                                  mpi_stubs\n\t\t\t\t  view3d\n\t\t\t\t  viewaxis elmersolver)\nINSTALL(TARGETS ViewFactors RUNTIME DESTINATION "bin")\n\nIF(NOT(WIN32))\n  SET_TARGET_PROPERTIES(ViewFactors PROPERTIES INSTALL_RPATH "${ELMERSOLVER_RPATH_STRING}")\nENDIF()\n\n# GebhardFactors\nADD_EXECUTABLE(GebhardtFactors GebhardtFactors.F90)\nTARGET_LINK_LIBRARIES(GebhardtFactors ${ELMERSOLVER_LIBRARIES} \n                                      mpi_stubs elmersolver)\n\nIF(NOT(WIN32))\n  SET_TARGET_PROPERTIES(GebhardtFactors PROPERTIES INSTALL_RPATH "${ELMERSOLVER_RPATH_STRING}")\nENDIF()\n\nIF(WITH_Trilinos)\n  TARGET_LINK_LIBRARIES(GebhardtFactors elmersolver "${Trilinos_LIBRARIES};${Belos_LIBRARIES};${ML_LIBRARIES};${Epetra_LIBRARIES};${Teuchos_LIBRARIES}")\nENDIF()\n\nINSTALL(TARGETS GebhardtFactors mpi_stubs RUNTIME DESTINATION "bin"\n  LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\n\n# Installation rules\nINSTALL(FILES elements.def SOLVER.KEYWORDS DESTINATION "share/elmersolver/lib")\n\n\nIF(NOT(WIN32))\n  IF(WITH_MPI)\n    INSTALL(TARGETS Solver_TGT elmersolver RUNTIME DESTINATION "bin"\n      LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\n    INSTALL(TARGETS Solver_TGT RUNTIME DESTINATION "bin"\n      LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\n  ELSE()\n    INSTALL(TARGETS Solver_TGT elmersolver mpi_stubs RUNTIME DESTINATION "bin" \n      LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\n  ENDIF()\nELSE()\n  INSTALL(TARGETS elmersolver mpi_stubs RUNTIME DESTINATION "${ELMER_INSTALL_LIB_DIR}" \n    LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\n  INSTALL(TARGETS Solver_TGT elmersolver mpi_stubs RUNTIME DESTINATION "bin" \n    LIBRARY DESTINATION "${ELMER_INSTALL_LIB_DIR}")\nENDIF()\n\nIF(WIN32)\n  INSTALL(PROGRAMS ${CMAKE_CURRENT_BINARY_DIR}/elmerf90.bat DESTINATION "bin")\n  INSTALL(PROGRAMS ${CMAKE_CURRENT_BINARY_DIR}/elmerld.bat DESTINATION  "bin")\nENDIF()\nINSTALL(PROGRAMS ${CMAKE_CURRENT_BINARY_DIR}/elmerf90 DESTINATION "bin")\nINSTALL(PROGRAMS ${CMAKE_CURRENT_BINARY_DIR}/elmerld DESTINATION  "bin")\n\n                  \nINSTALL(DIRECTORY ${CMAKE_Fortran_MODULE_DIRECTORY}/.\n                  DESTINATION "share/elmersolver/include")\n\nIF(WITH_MPI)\n  IF(NOT(WIN32))\n    # INSTALL(CODE "\n    # EXECUTE_PROCESS(COMMAND \\${CMAKE_COMMAND} -E create_symlink ElmerSolver_mpi ElmerSolver\n    # WORKING_DIRECTORY \\${CMAKE_INSTALL_PREFIX}/bin)")\n    ADD_CUSTOM_TARGET(elmersolver_link ALL COMMAND ${CMAKE_COMMAND} -E create_symlink ElmerSolver_mpi ElmerSolver)\n    ADD_DEPENDENCIES(elmersolver_link Solver_TGT)\n    INSTALL(FILES ${CMAKE_CURRENT_BINARY_DIR}/ElmerSolver DESTINATION "bin")\n  ELSE()\n    INSTALL(CODE "EXECUTE_PROCESS(COMMAND \\${CMAKE_COMMAND} -E copy\n    \\${CMAKE_INSTALL_PREFIX}/bin/ElmerSolver_mpi.exe\n    \\${CMAKE_INSTALL_PREFIX}/bin/ElmerSolver.exe)")\n  ENDIF()\nENDIF()\n\n# Legacy MATC callback interfaces in Load.c require pre-C23 semantics.\nSET_TARGET_PROPERTIES(elmersolver PROPERTIES C_STANDARD 17 C_STANDARD_REQUIRED YES C_EXTENSIONS YES)\n\n# Use declarations from the bundled UMFPACK implementation linked by Elmer.\nINCLUDE_DIRECTORIES("${CMAKE_SOURCE_DIR}/umfpack/src/umfpack/include")\n'}, {'path': 'fem/src/umf4_f77wrapper.c', 'sha256': '388e2a19d7381c1504e4764bfd64f6c0cadab324b7a6709633088ed2c982eb09', 'patched_sha256': 'c654971d5f563d2a5d27340c88a3ee827210f8a6aa0f4581eaa27ce632808513', 'content': '\n/* ----------------------------------------------  */\n/* Modified file for use with Elmer.               */\n/* Original copyright and usage information below: */\n\n\n/* ========================================================================== */\n/* === umf4_f77wrapper ====================================================== */\n/* ========================================================================== */\n\n/* -------------------------------------------------------------------------- */\n/* UMFPACK Version 4.4, Copyright (c) 2005 by Timothy A. Davis.  CISE Dept,   */\n/* Univ. of Florida.  All Rights Reserved.  See ../Doc/License for License.   */\n/* web: http://www.cise.ufl.edu/research/sparse/umfpack                       */\n/* -------------------------------------------------------------------------- */\n\n/* FORTRAN interface for the C-callable UMFPACK library (double / int version\n * only and double / long versions only).  This is HIGHLY non-portable.  You\n * will need to modify this depending on how your FORTRAN and C compilers\n * behave.  This has been tested in Linux, Sun Solaris, SGI IRIX, and IBM AIX,\n * with various compilers.  It has not been exhaustively tested on all possible\n * combinations of C and FORTRAN compilers.  The long version works on\n * Solaris, SGI IRIX, and IBM AIX when the UMFPACK library is compiled in\n * 64-bit mode.\n *\n * Only a subset of UMFPACK\'s capabilities are provided.  Refer to the UMFPACK\n * User Guide for details.\n *\n * For some C and FORTRAN compilers, the FORTRAN compiler appends a single\n * underscore ("_") after each routine name.  C doesn\'t do this, so the\n * translation is made here.  Other FORTRAN compilers treat underscores\n * differently.  For example, a FORTRAN call to a_b gets translated to a call\n * to a_b__ by g77, and to a_b_ by most other FORTRAN compilers.  Thus, the\n * FORTRAN names here do not use underscores.  The xlf compiler in IBM AIX\n * doesn\'t add an underscore.\n *\n * The matrix A is passed to UMFPACK in compressed column form, with 0-based\n * indices.  In FORTRAN, for an m-by-n matrix A with nz entries, the row\n * indices of the first column (column 1) are in Ai (Ap (1) + 1 ... Ap (2)),\n * with values in Ax (Ap (1) + 1 ... Ap (2)).  The last column (column n) is\n * in Ai (Ap (n) + 1 ... Ap (n+1)) and Ax (Ap (n) + 1 ... Ap (n+1)).  The row\n * indices in Ai are in the range 0 to m-1.  They must be sorted, with no\n * duplicate entries allowed.  Refer to umfpack_di_triplet_to_col for a more\n * flexible format for the input matrix.  The following definitions apply\n * for each of the routines in this file:\n *\n *\tinteger m, n, Ap (n+1), Ai (nz), symbolic, numeric, filenum, status\n *\tdouble precision Ax (nz), control (20), info (90), x (n), b (n)\n *\n * UMFPACK\'s status is returned in either a status argument, or in info (1).\n * It is zero if everything is OK, 1 if the matrix is singular (this is a\n * warning, not an error), and negative if an error occurred.  See umfpack.h\n * for more details on the contents of the control and info arrays, and the\n * value of the sys argument.\n *\n * For the Numeric and Symbolic handles, it\'s probably safe to assume that a\n * FORTRAN integer is sufficient to store a C pointer.  If that doesn\'t work,\n * try defining numeric and symbolic as integer arrays of size 2, or as\n * integer*8, in the FORTRAN routine that calls these wrapper routines.\n * The latter is required on Solaris, SGI IRIX, and IBM AIX when UMFPACK is\n * compiled in 64-bit mode.\n *\n * If you want to use 64-bit integers, try compiling this file with the -DDLONG\n * compiler option (via "make fortran64").  First modify your Make/Make.include\n * and Make/Make.<arch> files to compile UMFPACK in LP64 mode (see the User\n * Guide for details).  Your FORTRAN code should use integer*8.  See umf4hb64.f\n * for an example.\n *\n * Tested with the following compilers:\n *\t* Solaris with cc and f77 from Sun WorkShop 6 update 1\n *\t    (32-bit and 64-bit modes)\n *\t* SGI Irix with MIPSpro cc and f77 compilers version 7.4\n *\t    (32-bit and 64-bit modes)\n *\t* Linux with GNU gcc and Intel\'s icc, and GNU g77 and Intel\'s\n *\t    ifc FORTRAN compiler.  See the comments above about g77 and\n *\t    underscores.  Only supports 32-bit mode.\n *\t* IBM AIX xlc and xlf compilers.\n *\t    (32-bit and 64-bit modes)\n */\n\n#include "../config.h"\n#include "umfpack.h"\n\n#ifdef NULL\n#undef NULL\n#endif\n#define NULL 0\n\n/* Use no name mangling when ISO_C_BINDING is being used */\n#ifdef USE_ISO_C_BINDINGS\n#undef FC_FUNC\n#define FC_FUNC(ARG1,ARG2) ARG1\n#undef FC_FUNC_\n#define FC_FUNC_(ARG1,ARG2) ARG1\n#endif\n\n/* -------------------------------------------------------------------------- */\n/* integer type: int or long */\n/* -------------------------------------------------------------------------- */\n\n#define Int int\n#define UMFPACK_defaults\t umfpack_di_defaults\n#define UMFPACK_free_numeric\t umfpack_di_free_numeric\n#define UMFPACK_free_symbolic\t umfpack_di_free_symbolic\n#define UMFPACK_numeric\t\t umfpack_di_numeric\n#define UMFPACK_report_control\t umfpack_di_report_control\n#define UMFPACK_report_info\t umfpack_di_report_info\n#define UMFPACK_save_numeric\t umfpack_di_save_numeric\n#define UMFPACK_save_symbolic\t umfpack_di_save_symbolic\n#define UMFPACK_load_numeric\t umfpack_di_load_numeric\n#define UMFPACK_load_symbolic\t umfpack_di_load_symbolic\n#define UMFPACK_scale\t\t umfpack_di_scale\n#define UMFPACK_solve\t\t umfpack_di_solve\n#define UMFPACK_symbolic\t umfpack_di_symbolic\n\n#define UMFPACK_IRSTEP 7\n\n\n/* -------------------------------------------------------------------------- */\n/* umf4def: set default control parameters */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4def (control) */\n\nvoid STDCALLBULL FC_FUNC(umf4def,UMF4DEF) (double Control[])\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_defaults (Control) ;\n#endif\n}\n\n\n/* -------------------------------------------------------------------------- */\n/* umf4sym: pre-ordering and symbolic factorization */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4sym (m, n, Ap, Ai, Ax, symbolic, control, info) */\n\nvoid STDCALLBULL FC_FUNC(umf4sym,UMF4SYM) (Int *m, Int *n, Int Ap [ ], Int Ai [ ],\n    double Ax [ ], void **Symbolic,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_symbolic (*m, *n, Ap, Ai, Ax, Symbolic, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4num: numeric factorization */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4num (Ap, Ai, Ax, symbolic, numeric, control, info) */\n\nvoid STDCALLBULL FC_FUNC(umf4num,UMF4NUM) (Int Ap [ ], Int Ai [ ], double Ax [ ],\n    void **Symbolic, void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_numeric (Ap, Ai, Ax, *Symbolic, Numeric, Control, Info);\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4solr: solve a linear system with iterative refinement */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4solr (sys, Ap, Ai, Ax, x, b, numeric, control, info) */\n\nvoid STDCALLBULL FC_FUNC(umf4solr,UMF4SOLR) (Int *sys, Int Ap [ ], Int Ai [ ], double Ax [ ],\n    double x [ ], double b [ ], void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_solve (*sys, Ap, Ai, Ax, x, b, *Numeric, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4sol: solve a linear system without iterative refinement */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4sol (sys, x, b, numeric, control, info) */\n\nvoid STDCALLBULL FC_FUNC(umf4sol,UMF4SOL) (Int *sys, double x [ ], double b [ ], void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    Control [UMFPACK_IRSTEP] = 0 ;\n    (void) UMFPACK_solve (*sys, (Int *) NULL, (Int *) NULL, (double *) NULL,\n\tx, b, *Numeric, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4fnum: free the Numeric object */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4fnum (numeric) */\n\nvoid STDCALLBULL FC_FUNC(umf4fnum,UMF4FNUM) (void **Numeric)\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_free_numeric (Numeric) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4fsym: free the Symbolic object */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4fsym (symbolic) */\n\nvoid STDCALLBULL FC_FUNC(umf4fsym,UMF4FSYM) (void **Symbolic)\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_free_symbolic (Symbolic) ;\n#endif\n}\n\n\n#undef Int\n#undef UMFPACK_defaults\n#undef UMFPACK_free_numeric\n#undef UMFPACK_free_symbolic\n#undef UMFPACK_numeric\n#undef UMFPACK_report_control\n#undef UMFPACK_report_info\n#undef UMFPACK_save_numeric\n#undef UMFPACK_save_symbolic\n#undef UMFPACK_load_numeric\n#undef UMFPACK_load_symbolic\n#undef UMFPACK_scale\n#undef UMFPACK_solve\n#undef UMFPACK_symbolic\n\n#define Int long\n#define UMFPACK_defaults\t umfpack_dl_defaults\n#define UMFPACK_free_numeric\t umfpack_dl_free_numeric\n#define UMFPACK_free_symbolic\t umfpack_dl_free_symbolic\n#define UMFPACK_numeric\t\t umfpack_dl_numeric\n#define UMFPACK_report_control\t umfpack_dl_report_control\n#define UMFPACK_report_info\t umfpack_dl_report_info\n#define UMFPACK_save_numeric\t umfpack_dl_save_numeric\n#define UMFPACK_save_symbolic\t umfpack_dl_save_symbolic\n#define UMFPACK_load_numeric\t umfpack_dl_load_numeric\n#define UMFPACK_load_symbolic\t umfpack_dl_load_symbolic\n#define UMFPACK_scale\t\t umfpack_dl_scale\n#define UMFPACK_solve\t\t umfpack_dl_solve\n#define UMFPACK_symbolic\t umfpack_dl_symbolic\n\n\n/* -------------------------------------------------------------------------- */\n/* umf4def: set default control parameters */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4def (control) */\nvoid STDCALLBULL FC_FUNC_(umf4_l_def,UMF4_L_DEF) (double Control[])\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_defaults (Control) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4sym: pre-ordering and symbolic factorization */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4sym (m, n, Ap, Ai, Ax, symbolic, control, info) */\n\nvoid STDCALLBULL FC_FUNC_(umf4_l_sym,UMF4_L_SYM) (Int *m, Int *n, Int Ap [ ], Int Ai [ ],\n    double Ax [ ], void **Symbolic,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_symbolic (*m, *n, Ap, Ai, Ax, Symbolic, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4num: numeric factorization */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4num (Ap, Ai, Ax, symbolic, numeric, control, info) */\n\nvoid STDCALLBULL FC_FUNC_(umf4_l_num,UMF4_L_NUM) (Int Ap [ ], Int Ai [ ], double Ax [ ],\n    void **Symbolic, void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_numeric (Ap, Ai, Ax, *Symbolic, Numeric, Control, Info);\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4solr: solve a linear system with iterative refinement */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4solr (sys, Ap, Ai, Ax, x, b, numeric, control, info) */\n\nvoid STDCALLBULL FC_FUNC_(umf4_l_solr,UMF4_L_SOLR) (Int *sys, Int Ap [ ], Int Ai [ ], double Ax [ ],\n    double x [ ], double b [ ], void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    (void) UMFPACK_solve (*sys, Ap, Ai, Ax, x, b, *Numeric, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4sol: solve a linear system without iterative refinement */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4sol (sys, x, b, numeric, control, info) */\nvoid STDCALLBULL FC_FUNC_(umf4_l_sol,UMF4_L_SOL) (Int *sys, double x [ ], double b [ ], void **Numeric,\n    double Control[], double Info[])\n{\n#ifdef HAVE_UMFPACK\n    Control [UMFPACK_IRSTEP] = 0 ;\n    (void) UMFPACK_solve (*sys, (Int *) NULL, (Int *) NULL, (double *) NULL,\n\tx, b, *Numeric, Control, Info) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4fnum: free the Numeric object */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4fnum (numeric) */\n\nvoid STDCALLBULL FC_FUNC_(umf4_l_fnum,UMF4FNUM) (void **Numeric)\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_free_numeric (Numeric) ;\n#endif\n}\n\n/* -------------------------------------------------------------------------- */\n/* umf4fsym: free the Symbolic object */\n/* -------------------------------------------------------------------------- */\n\n/* call umf4fsym (symbolic) */\n\nvoid STDCALLBULL FC_FUNC_(umf4_l_fsym,UMF4FSYM) (void **Symbolic)\n{\n#ifdef HAVE_UMFPACK\n    UMFPACK_free_symbolic (Symbolic) ;\n#endif\n}\n'}, {'path': 'fem/src/modules/DCRComplexSolve.F90', 'sha256': 'dd5062a4cc971b73153c3a7798c92a54663202ec3d84786da2c6286c228b442a', 'patched_sha256': '241d8d4f9a08803d0b41b6b25b2c082c0eadcc234e32282255a4345acb43678b', 'content': "!/*****************************************************************************/\n! *\n! *  Elmer, A Finite Element Software for Multiphysical Problems\n! *\n! *  Copyright 1st April 1995 - , CSC - IT Center for Science Ltd., Finland\n! * \n! *  This program is free software; you can redistribute it and/or\n! *  modify it under the terms of the GNU General Public License\n! *  as published by the Free Software Foundation; either version 2\n! *  of the License, or (at your option) any later version.\n! * \n! *  This program is distributed in the hope that it will be useful,\n! *  but WITHOUT ANY WARRANTY; without even the implied warranty of\n! *  MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n! *  GNU General Public License for more details.\n! *\n! *  You should have received a copy of the GNU General Public License\n! *  along with this program (in file fem/GPL-2); if not, write to the \n! *  Free Software Foundation, Inc., 51 Franklin Street, Fifth Floor, \n! *  Boston, MA 02110-1301, USA.\n! *\n! *****************************************************************************/\n!\n! ******************************************************************************\n! *\n! *  Authors: Juha Ruokolainen, Mikko Lyly\n! *  Email:   Juha.Ruokolainen@csc.fi\n! *  Web:     http://www.csc.fi/elmer\n! *  Address: CSC - IT Center for Science Ltd.\n! *           Keilaranta 14\n! *           02101 Espoo, Finland \n! *\n! *  Original Date: 04 Oct 2000\n! *\n! ****************************************************************************/\n\n!------------------------------------------------------------------------------\n!>  Solve the complex diffusion-convection-reaction equation.\n!> \\ingroup Solvers\n!------------------------------------------------------------------------------\nSUBROUTINE DCRComplexSolver( Model,Solver,dt,TransientSimulation )\n!------------------------------------------------------------------------------\n  USE Types\n  USE Lists\n  USE Adaptive\n  USE Integration\n  USE ElementDescription\n  USE SolverUtils\n\n  IMPLICIT NONE\n!------------------------------------------------------------------------------\n  TYPE(Solver_t) :: Solver\n  TYPE(Model_t) :: Model\n\n  REAL(KIND=dp) :: dt\n  LOGICAL :: TransientSimulation\n!------------------------------------------------------------------------------\n! Local variables\n!------------------------------------------------------------------------------\n  TYPE(Matrix_t),POINTER  :: StiffMatrix\n  TYPE(Nodes_t) :: ElementNodes\n  TYPE(Element_t),POINTER :: CurrentElement\n\n  INTEGER, POINTER :: NodeIndexes(:)\n\n  LOGICAL :: AllocationsDone = .FALSE., Bubbles, GotIt, notScalar = .TRUE., stat\n\n  INTEGER, POINTER :: PressurePerm(:)\n  REAL(KIND=dp), POINTER :: Pressure(:), ForceVector(:)\n\n  INTEGER :: iter, i, j, k, n, t, istat, eq, LocalNodes\n  REAL(KIND=dp) :: Norm, PrevNorm, RelativeChange\n\n  TYPE(ValueList_t), POINTER :: Material\n\n  INTEGER :: NonlinearIter\n  REAL(KIND=dp) :: NonlinearTol,s\n\n  REAL(KIND=dp), ALLOCATABLE :: LocalStiffMatrix(:,:), Load(:,:), Work(:), &\n       LocalForce(:), &\n       Amatrix(:,:,:), AvectorReal(:,:), AvectorImag(:,:), AscalarReal(:), &\n       AscalarImag(:), Bvector(:,:), BscalarReal(:), BscalarImag(:)\n\n  CHARACTER(LEN=MAX_NAME_LEN) :: EquationName\n\n  SAVE LocalStiffMatrix, Work, Load, LocalForce, ElementNodes, &\n       AllocationsDone, &\n       Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag, &\n       Bvector, BscalarReal, BscalarImag\n   REAL(KIND=dp) :: at,at0,totat,st,totst,t1\n!------------------------------------------------------------------------------\n     INTERFACE\n        FUNCTION DCRBoundaryResidual( Model,Edge,Mesh,Quant,Perm,Gnorm ) RESULT(Indicator)\n          USE Types\n          TYPE(Element_t), POINTER :: Edge\n          TYPE(Model_t) :: Model\n          TYPE(Mesh_t), POINTER :: Mesh\n          REAL(KIND=dp) :: Quant(:), Indicator(2), Gnorm\n          INTEGER :: Perm(:)\n        END FUNCTION DCRBoundaryResidual\n\n        FUNCTION DCREdgeResidual( Model,Edge,Mesh,Quant,Perm ) RESULT(Indicator)\n          USE Types\n          TYPE(Element_t), POINTER :: Edge\n          TYPE(Model_t) :: Model\n          TYPE(Mesh_t), POINTER :: Mesh\n          REAL(KIND=dp) :: Quant(:), Indicator(2)\n          INTEGER :: Perm(:)\n        END FUNCTION DCREdgeResidual\n\n        FUNCTION DCRInsideResidual( Model,Element,Mesh,Quant,Perm, Fnorm ) RESULT(Indicator)\n          USE Types\n          TYPE(Element_t), POINTER :: Element\n          TYPE(Model_t) :: Model\n          TYPE(Mesh_t), POINTER :: Mesh\n          REAL(KIND=dp) :: Quant(:), Indicator(2), Fnorm\n          INTEGER :: Perm(:)\n        END FUNCTION DCRInsideResidual\n     END INTERFACE\n\n!------------------------------------------------------------------------------\n! Get variables needed for solution\n!------------------------------------------------------------------------------\n  IF ( .NOT.ASSOCIATED( Solver % Matrix ) ) RETURN\n  Solver % Matrix % Complex = .TRUE.\n\n  Pressure     => Solver % Variable % Values\n  PressurePerm => Solver % Variable % Perm\n\n  LocalNodes = COUNT( PressurePerm > 0 )\n  IF ( LocalNodes <= 0 ) RETURN\n\n  StiffMatrix => Solver % Matrix\n  ForceVector => StiffMatrix % RHS\n\n  Norm = Solver % Variable % Norm\n\n!------------------------------------------------------------------------------\n! Allocate some permanent storage, this is done first time only\n!------------------------------------------------------------------------------\n  IF ( .NOT. AllocationsDone .OR. Solver % MeshChanged ) THEN\n     N = Solver % Mesh % MaxElementNodes\n\n     IF ( AllocationsDone ) THEN\n        DEALLOCATE(                 &\n             ElementNodes % x,      &\n             ElementNodes % y,      &\n             ElementNodes % z,      &\n             LocalForce,            &\n             Work,                  &\n             LocalStiffMatrix,      &\n             Load, &\n             Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag, &\n             Bvector, BscalarReal, BscalarImag )\n     END IF\n\n     ALLOCATE( ElementNodes % x( N ),  &\n          ElementNodes % y( N ),       &\n          ElementNodes % z( N ),       &\n          LocalForce( 2*N ),           &\n          Work( N ),                   &\n          LocalStiffMatrix( 2*N,2*N ), &\n          Amatrix(3,3,N), AvectorReal(3,N), AvectorImag(3,N), &\n          AscalarReal(N), AscalarImag(N), Bvector(3,N), &\n          BscalarReal(N), BscalarImag(N), &\n          Load( 2,N ), STAT=istat )\n\n     IF ( istat /= 0 ) THEN\n        CALL Fatal( 'DCRComplexSolve', 'Memory allocation error.' )\n     END IF\n\n     AllocationsDone = .TRUE.\n  END IF\n!------------------------------------------------------------------------------\n\n!------------------------------------------------------------------------------\n! Do some additional initialization, and go for it\n!------------------------------------------------------------------------------\n  NonlinearTol = ListGetConstReal( Solver % Values, &\n       'Nonlinear System Convergence Tolerance',GotIt )\n\n  NonlinearIter = ListGetInteger( Solver % Values, &\n       'Nonlinear System Max Iterations', GotIt )\n\n  IF ( .NOT.GotIt ) NonlinearIter = 1\n\n  EquationName = ListGetString( Solver % Values, 'Equation' )\n\n  Bubbles = ListGetLogical( Solver % Values, 'Bubbles', GotIt )\n\n!------------------------------------------------------------------------------\n! Iterate over any nonlinearity of material or source\n!------------------------------------------------------------------------------\n  totat = 0.0d0\n  totst = 0.0d0\n\n  DO iter=1,NonlinearIter\n!------------------------------------------------------------------------------\n     at  = CPUTime()\n     at0 = RealTime()\n\n     CALL Info( 'DCRComplexSolve', ' ', Level=4 )\n     CALL Info( 'DCRComplexSolve', '-------------------------------------', Level=4 )\n     WRITE( Message, * ) 'DCRComplex iteration', iter\n     CALL Info( 'DCRComplexSolve', Message, Level=4 )\n     CALL Info( 'DCRComplexSolve', '-------------------------------------', Level=4 )\n     CALL Info( 'DCRComplexSolve', ' ', Level=4 )\n     CALL Info( 'DCRComplexSolve', 'Starting Assmebly', Level=4 )\n\n     CALL InitializeToZero( StiffMatrix, ForceVector )\n!\n!    Do the bulk assembly:\n!    ---------------------\n\n!------------------------------------------------------------------------------\n     DO t=1,Solver % NumberOfActiveElements\n!------------------------------------------------------------------------------\n        IF ( RealTime() - at0 > 1.0 ) THEN\n          WRITE(Message,'(a,i3,a)' ) '   Assembly: ', INT(100.0 - 100.0 * &\n           (Solver % NumberOfActiveElements-t) / &\n                       (1.0*Solver % NumberOfActiveElements)), ' % done'\n          CALL Info( 'DCRComplexSolve', Message, Level=5 )\n                      \n          at0 = RealTime()\n        END IF\n!------------------------------------------------------------------------------\n!       Check if this element belongs to a body where this equation\n!       should be computed\n!------------------------------------------------------------------------------\n        CurrentElement => Solver % Mesh % Elements(Solver % ActiveElements(t))\n\n!       IF ( .NOT. CheckElementEquation( Model, &\n!            CurrentElement, EquationName ) ) CYCLE\n!------------------------------------------------------------------------------\n        Model % CurrentElement => CurrentElement\n\n        n = CurrentElement % Type % NumberOfNodes\n        NodeIndexes => CurrentElement % NodeIndexes\n\n        ElementNodes % x(1:n) = Solver % Mesh % Nodes % x(NodeIndexes)\n        ElementNodes % y(1:n) = Solver % Mesh % Nodes % y(NodeIndexes)\n        ElementNodes % z(1:n) = Solver % Mesh % Nodes % z(NodeIndexes)\n\n!------------------------------------------------------------------------------\n!       Get equation & material parameters\n!------------------------------------------------------------------------------\n        k = ListGetInteger( Model % Bodies( CurrentElement % &\n         Bodyid ) % Values, 'Material',minv=1,maxv=Model % NumberOfMaterials )\n\n        Material => Model % Materials(k) % Values\n\n!------------------------------------------------------------------------------\n!       Second and first order time derivative term coefficients on nodes\n!------------------------------------------------------------------------------\n        CALL InputTensor( Amatrix, notScalar, &\n             'Amatrix', Material, n, NodeIndexes )\n\n        CALL InputVector( AvectorReal, notScalar, &\n             'Avector 1', Material, n, NodeIndexes )\n\n        CALL InputVector( AvectorImag, notScalar, &\n             'Avector 2', Material, n, NodeIndexes )\n\n        AscalarReal(1:n) = ListGetReal( Material, &\n             'Ascalar 1', n, NodeIndexes, GotIt)\n\n        AscalarImag(1:n) = ListGetReal( Material, &\n             'Ascalar 2', n, NodeIndexes, GotIt)\n\n!------------------------------------------------------------------------------\n!       The source term on nodes\n!------------------------------------------------------------------------------\n        k = ListGetInteger( Model % Bodies( CurrentElement % BodyId ) % &\n              Values, 'Body Force', GotIt, 1, Model % NumberOFBodyForces )\n\n        Load = 0.0d0\n        IF ( k > 0 ) THEN\n           Load(1,1:n) = ListGetReal( Model % BodyForces(k) % Values, &\n                'Pressure Source 1', n, NodeIndexes, GotIt )\n\n           Load(2,1:n) = ListGetReal( Model % BodyForces(k) % Values, &\n                'Pressure Source 2', n, NodeIndexes, GotIt )\n        END IF\n\n!------------------------------------------------------------------------------\n!       Get element local matrix and rhs vector\n!------------------------------------------------------------------------------\n        CALL LocalMatrix(  LocalStiffMatrix, LocalForce, & \n           Load, Bubbles, CurrentElement, n, ElementNodes, &\n           Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag )\n\n!------------------------------------------------------------------------------\n!       Update global matrix and rhs vector from local matrix & vector\n!------------------------------------------------------------------------------\n        CALL UpdateGlobalEquations( StiffMatrix, LocalStiffMatrix, &\n             ForceVector, LocalForce, n, Solver % Variable % DOFs, &\n                  PressurePerm(NodeIndexes) )\n!------------------------------------------------------------------------------\n     END DO\n!------------------------------------------------------------------------------\n\n!\n!    Neumann & Newton BCs:\n!    ---------------------\n\n!------------------------------------------------------------------------------\n     DO t = Solver % Mesh % NumberOfBulkElements + 1,  &\n               Solver % Mesh % NumberOfBulkElements +  &\n                  Solver % Mesh % NumberOfBoundaryElements\n!------------------------------------------------------------------------------\n        CurrentElement => Solver % Mesh % Elements(t)\n        Model % CurrentElement => CurrentElement\n\n!------------------------------------------------------------------------------\n!       The element type 101 (point element) can only be used\n!       to set Dirichlet BCs, so skip em at this stage.\n!------------------------------------------------------------------------------\n        IF ( CurrentElement % Type % ElementCode == 101 ) CYCLE\n\n!------------------------------------------------------------------------------\n        DO i=1,Model % NumberOfBCs\n           IF ( CurrentElement % BoundaryInfo % Constraint == &\n                Model % BCs(i) % Tag ) THEN\n!------------------------------------------------------------------------------\n              n = CurrentElement % Type % NumberOfNodes\n              NodeIndexes => CurrentElement % NodeIndexes\n\n              IF ( ANY( PressurePerm(NodeIndexes) == 0 ) ) CYCLE\n\n              ElementNodes % x(1:n) = Solver % Mesh % Nodes % x(NodeIndexes)\n              ElementNodes % y(1:n) = Solver % Mesh % Nodes % y(NodeIndexes)\n              ElementNodes % z(1:n) = Solver % Mesh % Nodes % z(NodeIndexes)\n\n              Load(1,1:n) = ListGetReal( Model % BCs(i) % Values, &\n                   'Wave Flux 1', n, NodeIndexes, GotIt )\n\n              Load(2,1:n) = ListGetReal( Model % BCs(i) % Values, &\n                   'Wave Flux 2', n, NodeIndexes, GotIt )\n\n              CALL InputVector( Bvector, notScalar, &\n                   'Bvector', Model % BCs(i) % Values,  n, NodeIndexes )\n\n              BscalarReal(1:n) = ListGetReal( Model % BCs(i) % Values, &\n                   'Bscalar 1', n, NodeIndexes, GotIt)\n              \n              BscalarImag(1:n) = ListGetReal( Model % BCs(i) % Values, &\n                   'Bscalar 2', n, NodeIndexes, GotIt)\n\n!------------------------------------------------------------------------------\n!             Get element local matrix and rhs vector\n!------------------------------------------------------------------------------\n              CALL LocalMatrixBoundary(  LocalStiffMatrix, LocalForce, &\n                   Load, CurrentElement, n, ElementNodes, & \n                   Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag, &\n                   Bvector, BscalarReal, BscalarImag )\n\n!------------------------------------------------------------------------------\n!             Update global matrix and rhs vector from local matrix & vector\n!------------------------------------------------------------------------------\n              CALL UpdateGlobalEquations( StiffMatrix, LocalStiffMatrix, &\n                  ForceVector, LocalForce, n, Solver % Variable % DOFs,  &\n                      PressurePerm(NodeIndexes) )\n!------------------------------------------------------------------------------\n           END IF\n        END DO\n!------------------------------------------------------------------------------\n     END DO\n!------------------------------------------------------------------------------\n\n     CALL FinishAssembly( Solver, ForceVector )\n!\n!    Dirichlet BCs:\n!    --------------\n     CALL SetDirichletBoundaries( Model, StiffMatrix, ForceVector, &\n          ComponentName(Solver % Variable,1), 1, &\n             Solver % Variable % DOFs, PressurePerm )\n\n     CALL SetDirichletBoundaries( Model, StiffMatrix, ForceVector, &\n          ComponentName(Solver % Variable,2), 2, &\n             Solver % Variable % DOFs, PressurePerm )\n\n     CALL Info( 'DCRComplexSolve', 'Assembly done', Level=4 )\n\n!\n!    Solve the system and we are done:\n!    ---------------------------------\n     PrevNorm = Norm\n     at = CPUTime() - at\n     st = CPUTime()\n\n     CALL SolveSystem( StiffMatrix, ParMatrix, ForceVector, &\n          Pressure, Norm, Solver % Variable % DOFs, Solver )\n\n     st = CPUTIme()-st\n     totat = totat + at\n     totst = totst + st\n     WRITE(Message,'(a,i4,a,F8.2,F8.2)') 'iter: ',iter,' Assembly: (s)', at, totat\n     CALL Info( 'DCRComplexSolve', Message, Level=4 )\n     WRITE(Message,'(a,i4,a,F8.2,F8.2)') 'iter: ',iter,' Solve:    (s)', st, totst\n     CALL Info( 'DCRComplexSolve', Message, Level=4 )\n\n!------------------------------------------------------------------------------\n     IF ( PrevNorm + Norm /= 0.0d0 ) THEN\n        RelativeChange = 2*ABS(PrevNorm - Norm) / (PrevNorm + Norm)\n     ELSE\n        RelativeChange = 0.0d0\n     END IF\n\n     CALL Info( 'DCRComplexSolve', ' ', Level=4 )\n     WRITE( Message, * ) 'Result Norm    : ',Norm\n     CALL Info( 'DCRComplexSolve', Message, Level=4 )\n     WRITE( Message, * ) 'Relative Change: ',RelativeChange\n     CALL Info( 'DCRComplexSolve', Message, Level=4 )\n\n     IF ( RelativeChange < NonlinearTol ) EXIT\n!------------------------------------------------------------------------------\n  END DO ! of nonlinear iteration\n!------------------------------------------------------------------------------\n   IF ( ListGetLogical( Solver % Values, 'Adaptive Mesh Refinement', GotIt ) ) &\n      CALL RefineMesh( Model,Solver,Pressure,PressurePerm, &\n            DCRInsideResidual, DCREdgeResidual, DCRBoundaryResidual )\n\nCONTAINS\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputTensor( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i, j\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE IF ( SIZE(Hwrk,2) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,1))\n            Tensor(i,i,1:n) = Hwrk(i,1,1:n)\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           DO j=1,MIN(3,SIZE(Hwrk,2))\n              Tensor( i,j,1:n ) = Hwrk(i,j,1:n)\n           END DO\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n   END SUBROUTINE InputTensor\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputVector( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           Tensor( i,1:n ) = Hwrk( i,1,1:n )\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n    END SUBROUTINE InputVector\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n\n  SUBROUTINE LocalMatrix(  StiffMatrix, Force, Load, Bubbles, Element, n, &\n       Nodes, Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag )\n!------------------------------------------------------------------------------\n    REAL(KIND=dp) :: StiffMatrix(:,:), Force(:), Load(:,:), &\n         Amatrix(:,:,:), AvectorReal(:,:), AvectorImag(:,:), &\n         AscalarReal(:), AscalarImag(:)\n    LOGICAL :: Bubbles\n    INTEGER :: n\n    TYPE(Nodes_t) :: Nodes\n    TYPE(Element_t), POINTER :: Element\n!------------------------------------------------------------------------------\n    REAL(KIND=dp) :: Basis(2*n),dBasisdx(2*n,3)\n    REAL(KIND=dp) :: SqrtElementMetric,U,V,W,S,M,D,L1,L2\n    REAL(KIND=dp) :: DiffCoef(3,3), Velo(3)\n    COMPLEX(KIND=dp) :: LSTIFF(2*n,2*n), LFORCE(2*n), A\n    LOGICAL :: Stat\n    INTEGER :: i,p,q,t,dim, NBasis, CoordSys\n    TYPE(GaussIntegrationPoints_t) :: IntegStuff\n\n    REAL(KIND=dp) :: X,Y,Z,Metric(3,3),SqrtMetric,Symb(3,3,3),dSymb(3,3,3,3)\n    REAL(kind=dp) :: A2(3,3), A1r(3), A1i(3), A0r, A0i\n!------------------------------------------------------------------------------\n    dim = CoordinateSystemDimension()\n    CoordSys = CurrentCoordinateSystem()\n\n    Metric = 0.0d0\n    Metric(1,1) = 1.0d0\n    Metric(2,2) = 1.0d0\n    Metric(3,3) = 1.0d0\n\n    LSTIFF = 0.0d0\n    LFORCE = 0.0d0\n!------------------------------------------------------------------------------\n!   Numerical integration\n!------------------------------------------------------------------------------\n    IF ( Bubbles ) THEN\n       IntegStuff = GaussPoints( Element, Element % Type % GaussPoints2 )\n       NBasis = 2*n\n    ELSE\n       NBasis = n\n       IntegStuff = GaussPoints( Element )\n    END IF\n!------------------------------------------------------------------------------\n    DO t=1,IntegStuff % n\n       U = IntegStuff % u(t)\n       V = IntegStuff % v(t)\n       W = IntegStuff % w(t)\n       S = IntegStuff % s(t)\n!------------------------------------------------------------------------------\n!      Basis function values & derivatives at the integration point\n!------------------------------------------------------------------------------\n       stat = ElementInfo( Element, Nodes, U, V, W, SqrtElementMetric, &\n            Basis, dBasisdx, Bubbles=Bubbles )\n\n       s = s * SqrtElementMetric\n       IF ( CoordSys /= Cartesian ) THEN\n          X = SUM( Nodes % X(1:n) * Basis(1:n) )\n          Y = SUM( Nodes % Y(1:n) * Basis(1:n) )\n          Z = SUM( Nodes % Z(1:n) * Basis(1:n) )\n          CALL CoordinateSystemInfo( Metric,SqrtMetric,Symb,dSymb,X,Y,Z )\n          s = s * SqrtMetric\n       END IF\n!------------------------------------------------------------------------------\n!      The source term and the coefficient of the time derivative and \n!      diffusion terms at the integration point\n!------------------------------------------------------------------------------\n!       D  =  WaveNumber * SUM( Damping(1:n) * Basis(1:n) )\n!       M  = -WaveNumber**2\n\n       L1 = SUM( Load(1,1:n) * Basis(1:n) )\n       L2 = SUM( Load(2,1:n) * Basis(1:n) )\n\n       A2 = 0.0d0\n       A1r = 0.0d0\n       A1i = 0.0d0\n       A0r = 0.0d0\n       A0i = 0.0d0\n\n       A0r = SUM( AscalarReal(1:n) * Basis(1:n) )\n       A0i = SUM( AscalarImag(1:n) * Basis(1:n) )\n       do i = 1,dim\n          A1r(i) = A1r(i) + SUM( AvectorReal(i,1:n) * Basis(1:n) )\n          A1i(i) = A1i(i) + SUM( AvectorImag(i,1:n) * Basis(1:n) )\n          do j = 1,dim\n             A2(i,j) = A2(i,j) + SUM( Amatrix(i,j,1:n) * Basis(1:n) )\n          end do\n       end do\n\n\n!      Stiffness matrix and load vector\n!      --------------------------------\n       DO p=1,NBasis\n          DO q=1,NBasis\n             A = CMPLX( A0r, A0i,KIND=dp ) * Basis(q) * Basis(p)\n             DO i=1,dim\n                A = A + CMPLX( A1r(i), A1i(i), KIND=dp ) * dBasisdx(q,i) * basis(p)\n                DO j=1,dim\n                   DO k = 1,dim\n                      A = A + Metric(i,j) * A2(i,k) * dBasisdx(q,k) * dBasisdx(p,j)\n                   END DO\n                END DO\n             END DO\n             LSTIFF(p,q) = LSTIFF(p,q) + s*A\n          END DO\n          LFORCE(p) = LFORCE(p) + s * Basis(p) * CMPLX( L1,L2,KIND=dp )\n       END DO\n    END DO\n!------------------------------------------------------------------------------\n\n    IF ( Bubbles ) THEN\n       CALL CondensateP( n, n, LSTIFF, LFORCE )\n    END IF\n\n    DO i=1,n\n       Force( 2*(i-1)+1 ) = REAL( LFORCE(i) )\n       Force( 2*(i-1)+2 ) = AIMAG( LFORCE(i) )\n\n       DO j=1,n\n         StiffMatrix( 2*(i-1)+1, 2*(j-1)+1 ) =  REAL( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+1, 2*(j-1)+2 ) = -AIMAG( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+2, 2*(j-1)+1 ) =  AIMAG( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+2, 2*(j-1)+2 ) =  REAL( LSTIFF(i,j) )\n       END DO\n    END DO\n!------------------------------------------------------------------------------\n  END SUBROUTINE LocalMatrix\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n  SUBROUTINE LocalMatrixBoundary(  StiffMatrix, Force, & \n       Load, Element, n, Nodes, &\n       Amatrix, AvectorReal, AvectorImag, AscalarReal, AscalarImag, &\n       Bvector, BscalarReal, BscalarImag )\n!------------------------------------------------------------------------------\n    REAL(KIND=dp) :: StiffMatrix(:,:),Force(:),Load(:,:)\n!    REAL(KIND=dp) :: ConvVelo(:,:)\n    INTEGER :: n\n    REAL(kind=dp) :: Amatrix(:,:,:), AvectorReal(:,:), AvectorImag(:,:), &\n         AscalarReal(:), AscalarImag(:), Bvector(:,:), BscalarReal(:), &\n         BscalarImag(:)\n    TYPE(Nodes_t) :: Nodes\n    TYPE(Element_t), POINTER :: Element\n!------------------------------------------------------------------------------\n    REAL(KIND=dp) :: SqrtElementMetric,U,V,W,S,L1,L2\n    REAL(KIND=dp) :: Basis(n),dBasisdx(n,3),X,Y,Z\n    REAL(KIND=dp) :: Normal(3), Velo(3), NormVelo, TangVelo(3)\n    REAL(kind=dp) :: A2(3,3), A1r(3), A1i(3), A0r, A0i, B1(3), B0r, B0i, &\n         C1(3), C0\n    COMPLEX(KIND=dp) :: LSTIFF(n,n), LFORCE(n), A\n    LOGICAL :: Stat\n    INTEGER :: i,p,q,t,dim,CoordSys\n    TYPE(GaussIntegrationPoints_t) :: IntegStuff\n!------------------------------------------------------------------------------\n    dim = CoordinateSystemDimension()\n    CoordSys = CurrentCoordinateSystem()\n\n    LSTIFF = 0.0d0\n    LFORCE = 0.0d0\n!------------------------------------------------------------------------------\n!   Numerical integration\n!------------------------------------------------------------------------------\n    IntegStuff = GaussPoints( Element )\n!------------------------------------------------------------------------------\n    DO t=1,IntegStuff % n\n       U = IntegStuff % u(t)\n       V = IntegStuff % v(t)\n       W = IntegStuff % w(t)\n       S = IntegStuff % s(t)\n!------------------------------------------------------------------------------\n!      Basis function values & derivatives at the integration point\n!------------------------------------------------------------------------------\n       stat = ElementInfo( Element, Nodes, U, V, W, SqrtElementMetric, &\n              Basis, dBasisdx )\n\n       s = s * SqrtElementMetric\n\n       Normal = Normalvector(Element, Nodes, U, V, .TRUE.)\n\n       A2 = 0.0d0\n       A1r = 0.0d0\n       A1i = 0.0d0\n       A0r = 0.0d0\n       A0i = 0.0d0\n\n       A0r = SUM( AscalarReal(1:n) * Basis(1:n) )\n       A0i = SUM( AscalarImag(1:n) * Basis(1:n) )\n       do i = 1,dim\n          A1r(i) = A1r(i) + SUM( AvectorReal(i,1:n) * Basis(1:n) )\n          A1i(i) = A1i(i) + SUM( AvectorImag(i,1:n) * Basis(1:n) )\n          do j = 1,dim\n             A2(i,j) = A2(i,j) + SUM( Amatrix(i,j,1:n) * Basis(1:n) )\n          end do\n       end do\n\n       B1 = 0.0d0\n       B0r = 0.0d0\n       B0i = 0.0d0\n\n       B0r = SUM( BscalarReal(1:n) * Basis(1:n) )\n       B0i = SUM( BscalarImag(1:n) * Basis(1:n) )\n       do i = 1,dim\n          B1(i) = B1(i) + SUM( Bvector(i,1:n) * Basis(1:n) )\n       end do\n       B1(1:dim) = B1(1:dim) + Normal(1:dim)\n       \n       C1 = 0.0d0\n       C0 = 0.0d0\n       do i = 1,dim\n          do j = 1,dim\n             C0 = C0 + Normal(i)*A2(i,j)*Normal(j)\n          end do\n       end do\n       C0 = C0 / SUM( B1(1:dim) * Normal(1:dim) )\n       C1 = C0*B1\n       do i = 1,dim\n          do j = 1,dim\n             C1(i) = C1(i) - A2(i,j)*Normal(j)\n          end do\n       end do\n\n\n!------------------------------------------------------------------------------\n       L1 = SUM( Load(1,1:n) * Basis )\n       L2 = SUM( Load(2,1:n) * Basis )\n!------------------------------------------------------------------------------\n       DO p=1,n\n          DO q=1,n\n             A = CMPLX( B0r, B0i, KIND=dp ) * C0 * Basis(p)*Basis(q)\n             A = A + SUM( C1(1:dim) * dBasisdx(q,1:dim) ) * Basis(p)\n             LSTIFF(p,q) = LSTIFF(p,q) + s * A\n          END DO\n          LFORCE(p) = LFORCE(p) + s * Basis(p) * C0 * CMPLX( L1, L2, KIND=dp ) \n       END DO\n!------------------------------------------------------------------------------\n    END DO\n!------------------------------------------------------------------------------\n    DO i=1,n\n       Force( 2*(i-1)+1 ) =  REAL( LFORCE(i) )\n       Force( 2*(i-1)+2 ) = AIMAG( LFORCE(i) )\n\n       DO j=1,n\n         StiffMatrix( 2*(i-1)+1, 2*(j-1)+1 ) =  REAL( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+1, 2*(j-1)+2 ) = -AIMAG( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+2, 2*(j-1)+1 ) =  AIMAG( LSTIFF(i,j) )\n         StiffMatrix( 2*(i-1)+2, 2*(j-1)+2 ) =  REAL( LSTIFF(i,j) )\n       END DO\n    END DO\n!------------------------------------------------------------------------------\n  END SUBROUTINE LocalMatrixBoundary\n!------------------------------------------------------------------------------\n\n!------------------------------------------------------------------------------\nEND SUBROUTINE DCRComplexSolver\n!------------------------------------------------------------------------------\n\n!------------------------------------------------------------------------------\n  FUNCTION DCRBoundaryResidual( Model, Edge, Mesh, Quant, Perm,Gnorm ) RESULT( Indicator )\n!------------------------------------------------------------------------------\n     USE DefUtils\n     IMPLICIT NONE\n!------------------------------------------------------------------------------\n     TYPE(Model_t) :: Model\n     INTEGER :: Perm(:)\n     REAL(KIND=dp) :: Quant(:), Indicator(2), Gnorm\n     TYPE( Mesh_t ), POINTER    :: Mesh\n     TYPE( Element_t ), POINTER :: Edge\n!------------------------------------------------------------------------------\n     TYPE(Nodes_t) :: Nodes, EdgeNodes\n     TYPE(Element_t), POINTER :: Element, Bndry\n\n     INTEGER :: i,j,k,n,l,t,DIM,Pn,En\n     LOGICAL :: stat, GotIt, gotWIreal,gotWIimag \n\n     LOGICAL :: notScalar = .TRUE.\n\n     REAL(KIND=dp) :: SqrtMetric, Metric(3,3), Symb(3,3,3), dSymb(3,3,3,3)\n     REAL(KIND=dp) :: Grad(3,3), Normal(3), EdgeLength\n     REAL(KIND=dp) :: Source, ResidualNorm, Area\n     REAL(kind=dp) :: B1(3), B0r, B0i, Greal, Gimag\n     REAL(KIND=dp) :: u, v, w, s, detJ, ResidualReal, ResidualImag, WaveFlux(2)\n\n     REAL(KIND=dp), ALLOCATABLE :: EdgeBasis(:), Basis(:)\n     REAL(KIND=dp), ALLOCATABLE :: dBasisdx(:,:)\n     REAL(KIND=dp), ALLOCATABLE :: Flux(:)\n     REAL(KIND=dp), ALLOCATABLE :: Work(:)\n     REAL(KIND=dp), ALLOCATABLE :: x(:), y(:), z(:)\n     REAL(KIND=dp), ALLOCATABLE :: Pressure(:,:), FluxReal(:), FluxImag(:)\n     REAL(KIND=dp), ALLOCATABLE :: Bvector(:,:), BScalarReal(:), BscalarImag(:)\n\n     TYPE(GaussIntegrationPoints_t), TARGET :: IntegStuff\n\n     LOGICAL :: Dirichlet = .FALSE.\n\n!    Initialize:\n!    -----------\n     Indicator = 0.0d0\n     Gnorm     = 0.0d0\n\n     Metric = 0.0d0\n     DO i=1,3\n        Metric(i,i) = 1.0d0\n     END DO\n\n     SELECT CASE( CurrentCoordinateSystem() )\n        CASE( AxisSymmetric, CylindricSymmetric )\n           DIM = 3\n        CASE DEFAULT\n           DIM = CoordinateSystemDimension()\n     END SELECT\n!    \n!    ---------------------------------------------\n     Element => Edge % BoundaryInfo % Left\n     IF ( .NOT. ASSOCIATED( Element ) ) THEN\n        Element => Edge % BoundaryInfo % Right\n     ELSE IF ( ANY( Perm( Element % NodeIndexes ) <= 0 ) ) THEN\n        Element => Edge % BoundaryInfo % Right\n     END IF\n\n     IF ( .NOT. ASSOCIATED( Element ) ) RETURN\n     IF ( ANY( Perm( Element % NodeIndexes ) <= 0 ) ) RETURN\n\n     En = Edge % TYPE % NumberOfNodes\n     Pn = Element % TYPE % NumberOfNodes\n\n     ALLOCATE( EdgeNodes % x(En), EdgeNodes % y(En), EdgeNodes % z(En) )\n\n     EdgeNodes % x = Mesh % Nodes % x(Edge % NodeIndexes)\n     EdgeNodes % y = Mesh % Nodes % y(Edge % NodeIndexes)\n     EdgeNodes % z = Mesh % Nodes % z(Edge % NodeIndexes)\n\n     ALLOCATE( Nodes % x(Pn), Nodes % y(Pn), Nodes % z(Pn) )\n\n     Nodes % x = Mesh % Nodes % x(Element % NodeIndexes)\n     Nodes % y = Mesh % Nodes % y(Element % NodeIndexes)\n     Nodes % z = Mesh % Nodes % z(Element % NodeIndexes)\n\n     ALLOCATE( x(En), y(En), z(En), EdgeBasis(En), Basis(Pn), dBasisdx(Pn,3),   &\n           Flux(en), Pressure(2,Pn), FluxReal(En), FluxImag(En), BVector(3,Pn), &\n           BScalarReal(Pn), BScalarImag(Pn) )\n\n     DO l = 1,En\n       DO k = 1,Pn\n          IF ( Edge % NodeIndexes(l) == Element % NodeIndexes(k) ) THEN\n             x(l) = Element % TYPE % NodeU(k)\n             y(l) = Element % TYPE % NodeV(k)\n             z(l) = Element % TYPE % NodeW(k)\n             EXIT\n          END IF\n       END DO\n     END DO\n\n!\n!    Integrate square of residual over boundary element:\n!    ---------------------------------------------------\n     Indicator    = 0.0d0\n     EdgeLength   = 0.0d0\n     ResidualNorm = 0.0d0\n     Gnorm = 0.0d0\n\n     DO j=1,Model % NumberOfBCs\n        IF ( Edge % BoundaryInfo % Constraint /= Model % BCs(j) % Tag ) CYCLE\n!\n!       ...given parameters:\n!       --------------------\n\n        CALL InputVector( Bvector, notScalar, 'Bvector', &\n             Model % BCs(j) % Values, Pn, Element % NodeIndexes )\n        \n        BscalarReal(1:Pn) = ListGetReal( Model % BCs(j) % Values, &\n             'Bscalar 1', Pn, Element % NodeIndexes, GotIt)\n\n        BscalarImag(1:Pn) = ListGetReal( Model % BCs(j) % Values, &\n             'Bscalar 2', Pn, Element % NodeIndexes, GotIt)\n\n        FluxReal(1:En) = ListGetReal( Model % BCs(j) % Values, &\n          'Wave Flux 1', En, Edge % NodeIndexes, gotIt )\n        if( .not.GotIt ) FluxReal(1:En) = 0.0d0\n\n        FluxImag(1:En) = ListGetReal( Model % BCs(j) % Values, &\n          'Wave Flux 2', En, Edge % NodeIndexes, gotIt )\n        if( .not.GotIt ) FluxImag(1:En) = 0.0d0\n!\n!       get material parameters:\n!       ------------------------\n        k = ListGetInteger(Model % Bodies(Element % BodyId) % Values,'Material', &\n                   minv=1, maxv=Model % NumberOfMaterials)\n!\n!       elementwise nodal solution:\n!       ---------------------------\n        Pressure(1,1:Pn) = Quant( 2*Perm(Element % NodeIndexes)-1 )\n        Pressure(2,1:Pn) = Quant( 2*Perm(Element % NodeIndexes)-0 )\n\n!       do the integration:\n!       -------------------\n        EdgeLength   = 0.0d0\n        ResidualNorm = 0.0d0\n        Gnorm = 0.0d0\n\n        IntegStuff = GaussPoints( Edge )\n\n        DO t=1,IntegStuff % n\n           u = IntegStuff % u(t)\n           v = IntegStuff % v(t)\n           w = IntegStuff % w(t)\n\n           stat = ElementInfo( Edge, EdgeNodes, u, v, w, detJ, &\n               EdgeBasis, dBasisdx )\n\n           IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n              s = IntegStuff % s(t) * detJ\n\n           ELSE\n              u = SUM( EdgeBasis(1:En) * EdgeNodes % x(1:En) )\n              v = SUM( EdgeBasis(1:En) * EdgeNodes % y(1:En) )\n              w = SUM( EdgeBasis(1:En) * EdgeNodes % z(1:En) )\n      \n              CALL CoordinateSystemInfo( Metric, SqrtMetric, &\n                         Symb, dSymb, u, v, w )\n\n              s = IntegStuff % s(t) * detJ * SqrtMetric\n\n           END IF\n\n!\n!          Integration point in parent element local\n!          coordinates:\n!          -----------------------------------------\n           u = SUM( EdgeBasis(1:En) * x(1:En) )\n           v = SUM( EdgeBasis(1:En) * y(1:En) )\n           w = SUM( EdgeBasis(1:En) * z(1:En) )\n\n           stat = ElementInfo( Element, Nodes, u, v, w, detJ, &\n                 Basis, dBasisdx )\n!\n!          Flux and parameters at integration point:\n!          ----------------------------------------\n\n           Normal = NormalVector( Edge, EdgeNodes, u, v, .TRUE. )\n\n           B1 = 0.0d0\n           B0r = 0.0d0\n           B0i = 0.0d0\n           \n           B0r = SUM( BscalarReal(1:Pn) * Basis(1:Pn) )\n           B0i = SUM( BscalarImag(1:Pn) * Basis(1:Pn) )\n           do i = 1,dim\n              B1(i) = B1(i) + SUM( Bvector(i,1:Pn) * Basis(1:Pn) )\n           end do\n           B1(1:dim) = B1(1:dim) + Normal(1:dim)\n\n           WaveFlux = 0.0d0\n           WaveFlux(1) = SUM( FluxReal(1:En) * EdgeBasis(1:En) )\n           WaveFlux(2) = SUM( FluxImag(1:En) * EdgeBasis(1:En) )\n           \n           ResidualReal = -WaveFlux(1)\n           ResidualImag = -WaveFlux(2)\n\n           Greal = 0.0d0\n           Gimag = 0.0d0\n!\n!          flux given by the computed solution, and \n!          force norm for scaling the residual:\n!          -----------------------------------------\n           IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n              DO k=1,DIM\n\n                 ResidualReal = ResidualReal + &\n                      SUM( dBasisdx(1:Pn,k) * Pressure(1,1:Pn) ) * B1(k)\n\n                 ResidualImag = ResidualImag + &\n                      SUM( dBasisdx(1:Pn,k) * Pressure(2,1:Pn) ) * B1(k) \n\n                 GReal = GReal + &\n                      SUM( dBasisdx(1:Pn,k) * Pressure(1,1:Pn) ) * B1(k)\n\n                 Gimag = Gimag + &\n                      SUM( dBasisdx(1:Pn,k) * Pressure(2,1:Pn) ) * B1(k) \n\n              END DO\n\n              ResidualReal = ResidualReal + &\n                    SUM( Basis(1:Pn) * Pressure(1,1:Pn) ) * B0r &\n                   -SUM( Basis(1:Pn) * Pressure(2,1:Pn) ) * B0i\n              \n              ResidualImag = ResidualImag + &\n                    SUM( Basis(1:Pn) * Pressure(1,1:Pn) ) * B0i &\n                   +SUM( Basis(1:Pn) * Pressure(2,1:Pn) ) * B0r\n\n              Greal = Greal + &\n                    SUM( Basis(1:Pn) * Pressure(1,1:Pn) ) * B0r &\n                   -SUM( Basis(1:Pn) * Pressure(2,1:Pn) ) * B0i\n              \n              Gimag = Gimag + &\n                    SUM( Basis(1:Pn) * Pressure(1,1:Pn) ) * B0i &\n                   +SUM( Basis(1:Pn) * Pressure(2,1:Pn) ) * B0r\n\n           ELSE\n!              DO k=1,DIM\n!                 DO l=1,DIM\n!                    Residual = Residual + Metric(k,l) * Conductivity  * &\n!                       SUM( dBasisdx(1:Pn,k) * Temperature(1:Pn) ) * Normal(l)\n!\n!                    Gnorm = Gnorm + s * (Metric(k,l) * Conductivity * &\n!                      SUM(dBasisdx(1:Pn,k) * Temperature(1:Pn) ) * Normal(l))**2\n!                 END DO\n!              END DO\n           END IF\n\n           EdgeLength   = EdgeLength + s\n           Gnorm = Gnorm + s * ( Greal **2 + Gimag**2 )\n\n           IF ( .NOT. Dirichlet ) THEN\n              ResidualNorm = ResidualNorm + s * (ResidualReal**2 + ResidualImag**2)\n           END IF\n\n        END DO\n\n        EXIT\n\n     END DO\n\n     IF ( CoordinateSystemDimension() == 3 ) THEN\n        EdgeLength = SQRT(EdgeLength)\n     END IF\n\n     Gnorm = EdgeLength * Gnorm\n\n     Indicator = EdgeLength * ResidualNorm\n\n     DEALLOCATE( Nodes % x, Nodes % y, Nodes % z)\n     DEALLOCATE( EdgeNodes % x, EdgeNodes % y, EdgeNodes % z)\n\n     DEALLOCATE( x, y, z, EdgeBasis, Basis, dBasisdx,   &\n           Flux, Pressure, FluxReal, FluxImag, BVector, &\n           BScalarReal, BScalarImag )\n\n\n\n!------------------------------------------------------------------------------\n\ncontains\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputVector( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           Tensor( i,1:n ) = Hwrk( i,1,1:n )\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n    END SUBROUTINE InputVector\n!------------------------------------------------------------------------------\n   END FUNCTION DCRBoundaryResidual\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n  FUNCTION DCREdgeResidual( Model, Edge, Mesh, Quant, Perm ) RESULT( Indicator )\n!------------------------------------------------------------------------------\n     USE DefUtils\n     IMPLICIT NONE\n\n     TYPE(Model_t) :: Model\n     INTEGER :: Perm(:)\n     REAL(KIND=dp) :: Quant(:), Indicator(2)\n     TYPE( Mesh_t ), POINTER    :: Mesh\n     TYPE( Element_t ), POINTER :: Edge\n!------------------------------------------------------------------------------\n\n     TYPE(Nodes_t) :: Nodes, EdgeNodes\n     TYPE(Element_t), POINTER :: Element, Bndry\n\n     INTEGER :: i,j,k,l,n,t,DIM,En,Pn\n     LOGICAL :: stat, GotIt\n!     REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n     REAL(KIND=dp) :: Grad(3,3), Normal(3), EdgeLength, Jump, JumpReal, JumpImag, &\n                      GradReal(3,3),GradImag(3,3)\n     REAL(KIND=dp) :: u, v, w, s, detJ\n     REAL(KIND=dp) :: Residual, ResidualNorm, Area\n     REAL(kind=dp) :: A2(3,3), A1r(3), A1i(3), A0r, A0i\n     REAL(KIND=dp) :: SqrtMetric, Metric(3,3), Symb(3,3,3), dSymb(3,3,3,3)\n\n     REAL(KIND=dp), ALLOCATABLE :: AvectorImag(:,:), AscalarReal(:), AscalarImag(:)\n     REAL(KIND=dp), ALLOCATABLE :: Flux(:), x(:), y(:), z(:)\n     REAL(KIND=dp), ALLOCATABLE :: Amatrix(:,:,:)\n     REAL(KIND=dp), ALLOCATABLE :: EdgeBasis(:)\n     REAL(KIND=dp), ALLOCATABLE :: AvectorReal(:,:)\n     REAL(KIND=dp), ALLOCATABLE :: Basis(:), dBasisdx(:,:)\n     REAL(KIND=dp), ALLOCATABLE :: Temperature(:), Pressure(:,:)\n\n     LOGICAL :: notScalar = .TRUE.\n\n     TYPE(GaussIntegrationPoints_t), TARGET :: IntegStuff\n\n!     LOGICAL :: First = .TRUE.\n!     SAVE Hwrk, First\n!------------------------------------------------------------------------------\n\n!    Initialize:\n!    -----------\n\n!     IF ( First ) THEN\n!        First = .FALSE.\n!        NULLIFY( Hwrk )\n!     END IF\n\n     SELECT CASE( CurrentCoordinateSystem() )\n        CASE( AxisSymmetric, CylindricSymmetric )\n           DIM = 3\n        CASE DEFAULT\n           DIM = CoordinateSystemDimension()\n     END SELECT\n\n     Metric = 0.0d0\n     DO i = 1,3\n        Metric(i,i) = 1.0d0\n     END DO\n\n     Grad = 0.0d0\n     GradReal = 0.0d0\n     GradImag = 0.0d0\n!\n!    ---------------------------------------------\n\n     Element => Edge % BoundaryInfo % Left\n     n = Element % TYPE % NumberOfNodes\n\n     Element => Edge % BoundaryInfo % Right\n     n = MAX( n, Element % TYPE % NumberOfNodes )\n\n     ALLOCATE( Nodes % x(n), Nodes % y(n), Nodes % z(n) )\n\n     En = Edge % TYPE % NumberOfNodes\n     ALLOCATE( EdgeNodes % x(En), EdgeNodes % y(En), EdgeNodes % z(En) )\n\n     EdgeNodes % x = Mesh % Nodes % x(Edge % NodeIndexes)\n     EdgeNodes % y = Mesh % Nodes % y(Edge % NodeIndexes)\n     EdgeNodes % z = Mesh % Nodes % z(Edge % NodeIndexes)\n\n     ALLOCATE( AvectorImag(3,n), AscalarReal(n), AscalarImag(n), Flux(en),   &\n       x(En), y(En), z(En), AMatrix(3,3,n), EdgeBasis(En), AvectorReal(3,n), &\n       Basis(n), dBasisdx(n,3), Temperature(n), Pressure(2,n) )\n\n!    Integrate square of jump over edge:\n!    -----------------------------------\n     ResidualNorm = 0.0d0\n     EdgeLength   = 0.0d0\n     Indicator    = 0.0d0\n\n     IntegStuff = GaussPoints( Edge )\n\n     DO t=1,IntegStuff % n\n\n        u = IntegStuff % u(t)\n        v = IntegStuff % v(t)\n        w = IntegStuff % w(t)\n\n        stat = ElementInfo( Edge, EdgeNodes, u, v, w, detJ, &\n             EdgeBasis, dBasisdx )\n\n        Normal = NormalVector( Edge, EdgeNodes, u, v, .FALSE. )\n\n        IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n           s = IntegStuff % s(t) * detJ\n        ELSE\n           u = SUM( EdgeBasis(1:En) * EdgeNodes % x(1:En) )\n           v = SUM( EdgeBasis(1:En) * EdgeNodes % y(1:En) )\n           w = SUM( EdgeBasis(1:En) * EdgeNodes % z(1:En) )\n\n           CALL CoordinateSystemInfo( Metric, SqrtMetric, &\n                      Symb, dSymb, u, v, w )\n           s = IntegStuff % s(t) * detJ * SqrtMetric\n        END IF\n! \n!       Compute flux over the edge as seen by elements\n!       on both sides of the edge:\n!       ----------------------------------------------\n        DO i = 1,2\n           SELECT CASE(i)\n              CASE(1)\n                 Element => Edge % BoundaryInfo % Left\n              CASE(2)\n                 Element => Edge % BoundaryInfo % Right\n           END SELECT\n!\n!          Can this really happen (maybe it can...)  ?      \n!          -------------------------------------------\n           IF ( ANY( Perm( Element % NodeIndexes ) <= 0 ) ) CYCLE\n!\n!          Next, get the integration point in parent\n!          local coordinates:\n!          -----------------------------------------\n           Pn = Element % TYPE % NumberOfNodes\n\n           DO j = 1,En\n              DO k = 1,Pn\n                 IF ( Edge % NodeIndexes(j) == Element % NodeIndexes(k) ) THEN\n                    x(j) = Element % TYPE % NodeU(k)\n                    y(j) = Element % TYPE % NodeV(k)\n                    z(j) = Element % TYPE % NodeW(k)\n                    EXIT\n                 END IF\n              END DO\n           END DO\n\n           u = SUM( EdgeBasis(1:En) * x(1:En) )\n           v = SUM( EdgeBasis(1:En) * y(1:En) )\n           w = SUM( EdgeBasis(1:En) * z(1:En) )\n!\n!          Get parent element basis & derivatives at the\n!          integration point:\n!          ---------------------------------------------\n           Nodes % x(1:Pn) = Mesh % Nodes % x(Element % NodeIndexes)\n           Nodes % y(1:Pn) = Mesh % Nodes % y(Element % NodeIndexes)\n           Nodes % z(1:Pn) = Mesh % Nodes % z(Element % NodeIndexes)\n\n           stat = ElementInfo( Element, Nodes, u, v, w, detJ, &\n             Basis, dBasisdx )\n!\n!          Material parameters:\n!          --------------------\n           k = ListGetInteger( Model % Bodies( &\n                Element % BodyId) % Values, 'Material', minv=1,maxv=Model % NumberOfMaterials )\n\n           CALL InputTensor( Amatrix, notScalar, &\n                'Amatrix', Model % Materials(k) % Values, Pn, Element % NodeIndexes )\n           \n           CALL InputVector( AvectorReal, notScalar, &\n                'Avector 1', Model % Materials(k) % Values, Pn, Element % NodeIndexes )\n           \n           CALL InputVector( AvectorImag, notScalar, &\n                'Avector 2', Model % Materials(k) % Values, Pn, Element % NodeIndexes )\n           \n           AscalarReal(1:Pn) = ListGetReal( Model % Materials(k) % Values, &\n                'Ascalar 1', Pn, Element % NodeIndexes, GotIt)\n           \n           AscalarImag(1:Pn) = ListGetReal( Model % Materials(k) % Values, &\n                'Ascalar 2', Pn, Element % NodeIndexes, GotIt)\n\n           A2 = 0.0d0\n           A1r = 0.0d0\n           A1i = 0.0d0\n           A0r = 0.0d0\n           A0i = 0.0d0\n           \n           A0r = SUM( AscalarReal(1:Pn) * Basis(1:Pn) )\n           A0i = SUM( AscalarImag(1:Pn) * Basis(1:Pn) )\n           do j = 1,dim\n              A1r(j) = A1r(j) + SUM( AvectorReal(j,1:Pn) * Basis(1:Pn) )\n              A1i(j) = A1i(j) + SUM( AvectorImag(j,1:Pn) * Basis(1:Pn) )\n              do k = 1,dim\n                 A2(j,k) = A2(j,k) + SUM( Amatrix(j,k,1:Pn) * Basis(1:Pn) )\n              end do\n           end do\n!\n!          Pressure at element nodal points\n!          ---------------------------------\n           do k = 1,2\n              Pressure(k,1:Pn) = Quant( 2*Perm(Element % NodeIndexes)-2+k )\n           end do\n!\n!          Finally, the flux:\n!          ------------------\n           DO j=1,DIM\n              do k = 1,dim\n                 GradReal(j,i) = GradReal(j,i) &\n                      + SUM( dBasisdx(1:Pn,k) * Pressure(1,1:Pn) )*A2(j,k)\n                 GradImag(j,i) = GradImag(j,i) &\n                      + SUM( dBasisdx(1:Pn,k) * Pressure(2,1:Pn) )*A2(j,k)\n              end do\n           END DO\n\n        END DO\n\n!       Compute squre of the flux jump:\n!       -------------------------------   \n        EdgeLength  = EdgeLength + s\n        JumpReal = 0.0d0\n        JumpImag = 0.0d0\n\n        DO k=1,DIM\n           IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n              JumpReal = JumpReal + (GradReal(k,1) - GradReal(k,2)) * Normal(k)\n              JumpImag = JumpImag + (GradImag(k,1) - GradImag(k,2)) * Normal(k)\n           ELSE\n!              DO l=1,DIM\n!                 Jump = Jump + &\n!                       Metric(k,l) * (Grad(k,1) - Grad(k,2)) * Normal(l)\n!              END DO\n           END IF\n        END DO\n        ResidualNorm = ResidualNorm + s * ( JumpReal**2 + JumpImag**2 )\n     END DO\n\n     IF ( CoordinateSystemDimension() == 3 ) THEN\n        EdgeLength = SQRT(EdgeLength)\n     END IF\n     Indicator = EdgeLength * ResidualNorm\n\n     DEALLOCATE( Nodes % x, Nodes % y, Nodes % z)\n     DEALLOCATE( EdgeNodes % x, EdgeNodes % y, EdgeNodes % z)\n\n     DEALLOCATE( AvectorImag, AscalarReal, AscalarImag, Flux,    &\n       x, y, z, AMatrix, EdgeBasis, AvectorReal, Basis, dBasisdx,&\n       Temperature, Pressure )\n!------------------------------------------------------------------------------\n\ncontains\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputTensor( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i, j\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE IF ( SIZE(Hwrk,2) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,1))\n            Tensor(i,i,1:n) = Hwrk(i,1,1:n)\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           DO j=1,MIN(3,SIZE(Hwrk,2))\n              Tensor( i,j,1:n ) = Hwrk(i,j,1:n)\n           END DO\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n   END SUBROUTINE InputTensor\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputVector( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           Tensor( i,1:n ) = Hwrk( i,1,1:n )\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n    END SUBROUTINE InputVector\n!------------------------------------------------------------------------------\n\n\n   END FUNCTION DCREdgeResidual\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n   FUNCTION DCRInsideResidual( Model, Element, Mesh, &\n        Quant, Perm, Fnorm ) RESULT( Indicator )\n!------------------------------------------------------------------------------\n     USE DefUtils\n!------------------------------------------------------------------------------\n     IMPLICIT NONE\n!------------------------------------------------------------------------------\n     TYPE(Model_t) :: Model\n     INTEGER :: Perm(:)\n     REAL(KIND=dp) :: Quant(:), Indicator(2), Fnorm\n     TYPE( Mesh_t ), POINTER    :: Mesh\n     TYPE( Element_t ), POINTER :: Element\n!------------------------------------------------------------------------------\n\n     TYPE(Nodes_t) :: Nodes\n\n     INTEGER :: i,j,k,l,n,t,DIM\n     LOGICAL :: stat, GotIt\n     TYPE( Variable_t ), POINTER :: Var\n\n     REAL(KIND=dp) :: SqrtMetric, Metric(3,3), Symb(3,3,3), dSymb(3,3,3,3)\n     REAL(KIND=dp) :: Source, Residual, ResidualNorm, Area\n     REAL(kind=dp) :: A2(3,3), A1r(3), A1i(3), A0r, A0i\n     REAL(KIND=dp) :: u, v, w, s, detJ, ResidualReal, ResidualImag\n\n     REAL(KIND=dp), ALLOCATABLE :: NodalSource(:,:), Basis(:)\n     REAL(KIND=dp), ALLOCATABLE :: dBasisdx(:,:), ddBasisddx(:,:,:), Pressione(:,:)\n     REAL(KIND=dp), ALLOCATABLE :: Amatrix(:,:,:), AvectorReal(:,:)\n     REAL(KIND=dp), ALLOCATABLE :: AvectorImag(:,:), AscalarReal(:), AscalarImag(:)\n\n     LOGICAL :: notScalar = .TRUE.\n     TYPE( ValueList_t ), POINTER :: Material\n     TYPE(GaussIntegrationPoints_t), TARGET :: IntegStuff\n\n!     LOGICAL :: First = .TRUE.\n!     SAVE Hwrk, First\n!------------------------------------------------------------------------------\n\n!    Initialize:\n!    -----------\n     Indicator = 0.0d0\n     Fnorm     = 0.0d0\n!\n!    Check if this eq. computed in this element:\n!    -------------------------------------------\n     IF ( ANY( Perm( Element % NodeIndexes ) <= 0 ) ) RETURN\n\n     Metric = 0.0d0\n     DO i=1,3\n        Metric(i,i) = 1.0d0\n     END DO\n\n     SELECT CASE( CurrentCoordinateSystem() )\n        CASE( AxisSymmetric, CylindricSymmetric )\n           DIM = 3\n        CASE DEFAULT\n           DIM = CoordinateSystemDimension()\n     END SELECT\n!\n!    Element nodal points:\n!    ---------------------\n     n = Element % TYPE % NumberOfNodes\n\n     ALLOCATE( Nodes % x(n), Nodes % y(n), Nodes % z(n) )\n     Nodes % x = Mesh % Nodes % x(Element % NodeIndexes)\n     Nodes % y = Mesh % Nodes % y(Element % NodeIndexes)\n     Nodes % z = Mesh % Nodes % z(Element % NodeIndexes)\n\n     ALLOCATE( NodalSource(2,n), Basis(n), dBasisdx(n,3), ddBasisddx(n,3,3), &\n         Pressione(2,n), AMatrix(3,3,n), AvectorReal(3,n), AvectorImag(3,n), &\n         AscalarReal(n), AscalarImag(n) )\n!\n!    Elementwise nodal solution:\n!    ---------------------------\n     Pressione(1,1:n) = Quant( 2*Perm(Element % NodeIndexes)-1 )\n     Pressione(2,1:n) = Quant( 2*Perm(Element % NodeIndexes)-0 )\n!\n!    Material parameters: sound speed:\n!    ---------------------------------\n     k = ListGetInteger( Model % Bodies(Element % BodyId) % Values, 'Material', &\n                  minv=1, maxv=Model % NumberOfMaterials )\n\n     Material => Model % Materials(k) % Values\n\n     CALL InputTensor( Amatrix, notScalar, &\n          'Amatrix', Material, n, Element % NodeIndexes )\n     \n     CALL InputVector( AvectorReal, notScalar, &\n          'Avector 1', Material, n, Element % NodeIndexes )\n     \n     CALL InputVector( AvectorImag, notScalar, &\n          'Avector 2', Material, n, Element % NodeIndexes )\n     \n     AscalarReal(1:n) = ListGetReal( Material, &\n          'Ascalar 1', n, Element % NodeIndexes, GotIt)\n     \n     AscalarImag(1:n) = ListGetReal( Material, &\n          'Ascalar 2', n, Element % NodeIndexes, GotIt)\n!\n!    Source term:\n!    ------------\n     k = ListGetInteger( &\n         Model % Bodies(Element % BodyId) % Values,'Body Force',GotIt, &\n                    1, Model % NumberOFBodyForces )\n\n     NodalSource = 0.0d0\n     IF ( GotIt .AND. k > 0  ) THEN\n        NodalSource(1,1:n) = ListGetReal( Model % BodyForces(k) % Values, &\n             'Pressure Source 1', n, Element % NodeIndexes, GotIt )\n\n        NodalSource(2,1:n) = ListGetReal( Model % BodyForces(k) % Values, &\n             'Pressure Source 2', n, Element % NodeIndexes, GotIt )\n     END IF\n!\n!    Integrate square of residual over element:\n!    ------------------------------------------\n\n     ResidualNorm = 0.0d0\n     Area = 0.0d0\n\n     IntegStuff = GaussPoints( Element )\n\n     DO t=1,IntegStuff % n\n        u = IntegStuff % u(t)\n        v = IntegStuff % v(t)\n        w = IntegStuff % w(t)\n\n        stat = ElementInfo( Element, Nodes, u, v, w, detJ, &\n            Basis, dBasisdx, ddBasisddx, .TRUE. )\n\n        IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n           s = IntegStuff % s(t) * detJ\n\n        ELSE\n           u = SUM( Basis(1:n) * Nodes % x(1:n) )\n           v = SUM( Basis(1:n) * Nodes % y(1:n) )\n           w = SUM( Basis(1:n) * Nodes % z(1:n) )\n\n           CALL CoordinateSystemInfo( Metric, SqrtMetric, &\n                       Symb, dSymb, u, v, w )\n           s = IntegStuff % s(t) * detJ * SqrtMetric\n\n        END IF\n\n        ResidualReal = 0.0d0\n        ResidualImag = 0.0d0\n\n        A2 = 0.0d0\n        A1r = 0.0d0\n        A1i = 0.0d0\n        A0r = 0.0d0\n        A0i = 0.0d0\n        \n        A0r = SUM( AscalarReal(1:n) * Basis(1:n) )\n        A0i = SUM( AscalarImag(1:n) * Basis(1:n) )\n        do i = 1,dim\n           A1r(i) = A1r(i) + SUM( AvectorReal(i,1:n) * Basis(1:n) )\n           A1i(i) = A1i(i) + SUM( AvectorImag(i,1:n) * Basis(1:n) )\n           do j = 1,dim\n              A2(i,j) = A2(i,j) + SUM( Amatrix(i,j,1:n) * Basis(1:n) )\n           end do\n        end do\n\n        IF ( CurrentCoordinateSystem() == Cartesian ) THEN\n\n! diffusion\n!-----------\n           do i = 1,dim\n              do j = 1,dim\n                 ResidualReal = ResidualReal &\n                      - SUM( Pressione(1,1:n) * ddBasisddx(1:n,i,j) ) * A2(i,j)\n\n                 ResidualImag = ResidualImag &\n                      - SUM( Pressione(2,1:n) * ddBasisddx(1:n,i,j) ) * A2(i,j)\n              end do\n           end do\n\n! convection\n!------------\n           do i = 1,dim\n              ResidualReal = ResidualReal + &\n                   SUM( dBasisdx(1:n,i) * Pressione(1,1:n) ) * A1r(i) &\n                   -SUM( dBasisdx(1:n,i) * Pressione(2,1:n) ) * A1i(i)\n              \n              ResidualImag = ResidualImag + &\n                   SUM( dBasisdx(1:n,i) * Pressione(1,1:n) ) * A1i(i) &\n                   +SUM( dBasisdx(1:n,i) * Pressione(2,1:n) ) * A1r(i)\n           end do\n\n! reaction\n!----------\n           ResidualReal = ResidualReal + &\n                SUM( Basis(1:n) * Pressione(1,1:n) ) * A0r &\n                -SUM( Basis(1:n) * Pressione(2,1:n) ) * A0i\n           \n           ResidualImag = ResidualImag + &\n                SUM( Basis(1:n) * Pressione(1,1:n) ) * A0i &\n                +SUM( Basis(1:n) * Pressione(2,1:n) ) * A0r\n\n        ELSE\n           print *,'Only cartesian coordinates implemented at the moment!'\n           stop\n\n!           DO j=1,DIM\n!              DO k=1,DIM\n!\n!                - g^{jk} C_{,k}T_{j}:\n!                ---------------------\n!\n!                 Residual = Residual - Metric(j,k) * &\n!                    SUM( Temperature(1:n) * dBasisdx(1:n,j) ) * &\n!                    SUM( NodalConductivity(1:n) * dBasisdx(1:n,k) )\n\n!\n!                - g^{jk} C T_{,jk}:\n!                -------------------\n!\n!                 Residual = Residual - Metric(j,k) * Conductivity * &\n!                    SUM( Temperature(1:n) * ddBasisddx(1:n,j,k) )\n!\n!                + g^{jk} C {_jk^l} T_{,l}:\n!                ---------------------------\n!                 DO l=1,DIM\n!                    Residual = Residual + Metric(j,k) * Conductivity * &\n!                      Symb(j,k,l) * SUM( Temperature(1:n) * dBasisdx(1:n,l) )\n!                 END DO\n!              END DO\n!           END DO\n        END IF\n\n!\n!       Compute also force norm for scaling the residual:\n!       -------------------------------------------------\n        DO i=1,DIM\n           Fnorm = Fnorm &\n                + s * ( SUM( NodalSource(1,1:n) * Basis(1:n) ) ) ** 2 &\n                + s * ( SUM( NodalSource(2,1:n) * Basis(1:n) ) ) ** 2\n        END DO\n\n        Area = Area + s\n        ResidualNorm = ResidualNorm + s *  ( ResidualReal ** 2 + ResidualImag ** 2 )\n     END DO\n\n     Fnorm = Element % hk**2 * Fnorm\n     Indicator = Element % hK**2 * ResidualNorm\n\n     DEALLOCATE( Nodes % x, Nodes % y, Nodes % z )\n     DEALLOCATE( NodalSource, Basis, dBasisdx, ddBasisddx, Pressione, &\n       AMatrix, AvectorReal, AvectorImag,AscalarReal, AscalarImag )\n\nCONTAINS\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputTensor( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i, j\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE IF ( SIZE(Hwrk,2) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,1))\n            Tensor(i,i,1:n) = Hwrk(i,1,1:n)\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           DO j=1,MIN(3,SIZE(Hwrk,2))\n              Tensor( i,j,1:n ) = Hwrk(i,j,1:n)\n           END DO\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n   END SUBROUTINE InputTensor\n!------------------------------------------------------------------------------\n\n\n!------------------------------------------------------------------------------\n   SUBROUTINE InputVector( Tensor, IsScalar, Name, Material, n, NodeIndexes )\n!------------------------------------------------------------------------------\n      REAL(KIND=dp) :: Tensor(:,:)\n      INTEGER :: n, NodeIndexes(:)\n      INTEGER :: i\n      LOGICAL :: IsScalar\n      CHARACTER(LEN=*) :: Name\n      TYPE(ValueList_t), POINTER :: Material\n!------------------------------------------------------------------------------\n      LOGICAL :: FirstTime = .TRUE., stat\n      REAL(KIND=dp), POINTER :: Hwrk(:,:,:)\n\n      SAVE FirstTime, Hwrk\n!------------------------------------------------------------------------------\n      IF ( FirstTime ) THEN\n         NULLIFY( Hwrk )\n         FirstTime = .FALSE.\n      END IF\n\n      Tensor = 0.0d0\n\n      CALL ListGetRealArray( Material, Name, Hwrk, n, NodeIndexes, stat )\n      IsScalar = SIZE(HWrk,1) == 1 .AND. SIZE(HWrk,2) == 1\n\n      IF ( .NOT. stat ) RETURN\n\n      IF ( SIZE(Hwrk,1) == 1 ) THEN\n\n         DO i=1,MIN(3,SIZE(Hwrk,2))\n            Tensor( i,1:n ) = Hwrk( 1,1,1:n )\n         END DO\n\n      ELSE\n\n        DO i=1,MIN(3,SIZE(Hwrk,1))\n           Tensor( i,1:n ) = Hwrk( i,1,1:n )\n        END DO\n\n      END IF\n!------------------------------------------------------------------------------\n    END SUBROUTINE InputVector\n!------------------------------------------------------------------------------\n\n!------------------------------------------------------------------------------\n   END FUNCTION DCRInsideResidual\n!------------------------------------------------------------------------------\n\n\n"}]
def main():
    root = Path(sys.argv[1]).resolve()
    root.relative_to(Path.cwd().resolve())
    pending = []
    for patch in PATCHES:
        path = root / patch['path']
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if digest == patch['patched_sha256']:
            continue
        if digest != patch['sha256']:
            raise SystemExit('Unsupported source content: ' + patch['path'])
        pending.append((path, patch['content']))
    for path, content in pending:
        path.write_text(content)
    print(json.dumps({'patched_files': len(pending), 'source': str(root)}))

if __name__ == '__main__':
    main()
